local config = {
  ui_story_5028_50280101_1_dialog_content = "シーッ…静かにして、見つかっちゃうでしょ。",
  ui_story_5028_50280101_2_dialog_content = "<color=#e8d9bb>ザクッ…ザクッ…</color>",
  ui_story_5028_50280101_3_dialog_content = "…",
  ui_story_5028_50280101_4_dialog_content = "モグモグ…モグモグ…",
  ui_story_5028_50280101_5_dialog_content = "わ、何か食べてる！かわい～い！",
  ui_story_5028_50280101_6_dialog_content = "あ、動いちゃダメ！",
  ui_story_5028_50280101_7_dialog_content = "気づかれたら…",
  ui_story_5028_50280101_8_dialog_content = "ガタッ…",
  ui_story_5028_50280101_9_dialog_content = "！！！",
  ui_story_5028_50280101_10_dialog_content = "チィ！？",
  ui_story_5028_50280101_11_dialog_content = "ほら、逃げちゃったじゃない！\nあんたのせいよ、キャロ！",
  ui_story_5028_50280101_12_dialog_content = "ル…？",
  ui_story_5028_50280101_13_dialog_content = "急いで追いかけなさい！\n今日こそ何が何でも捕まえるから！",
  ui_story_5028_50280101_13X_dialog_content = "フィアは珍獣マスターになるんだから！",
  ui_story_5028_50280101_14_dialog_content = "フィア",
  ui_story_5028_50280101_X14_dialog_content = "14歳",
  ui_story_5028_50280101_15_dialog_content = "夢は珍獣の専門家になること",
  ui_story_5028_50280101_16_dialog_content = "チィ…チィ…",
  ui_story_5028_50280101_17_dialog_content = "あっちに行ったよ！",
  ui_story_5028_50280101_18_dialog_content = "ちょっと、キャロ！モタモタしないで！",
  ui_story_5028_50280101_19_dialog_content = "見失っちゃう！",
  ui_story_5028_50280101_20_dialog_content = "ル…？",
  ui_story_5028_50280101_21_dialog_content = "まったく…もうっ！",
  ui_story_5028_50280101_22_dialog_content = "ほら、抱っこされてなさい！",
  ui_story_5028_50280101_23_dialog_content = "よいしょっ！",
  ui_story_5028_50280101_24_dialog_content = "ルルル！",
  ui_story_5028_50280101_25_dialog_content = "じっとしてなさいよ！一気に追いつくから！",
  ui_story_5028_50280101_26_dialog_content = "チィ…",
  ui_story_5028_50280101_27_dialog_content = "ふぅ、ふぅ…やっと追いついた…",
  ui_story_5028_50280101_28_dialog_content = "キャロ、今度は大人しくしてるって約束してくれる？",
  ui_story_5028_50280101_29_dialog_content = "ル…？",
  ui_story_5028_50280101_30_dialog_content = "…",
  ui_story_5028_50280101_31_dialog_content = "いい？ここで大人しく、ひとりで遊んでて。",
  ui_story_5028_50280101_32_dialog_content = "チョウチョを捕まえるでも、\n木の実を食べるでも、何でもいいから。",
  ui_story_5028_50280101_33_dialog_content = "とにかく、あたしから離れて、\nいい子にしててね。",
  ui_story_5028_50280101_34_dialog_content = "ルルル！",
  ui_story_5028_50280101_35_dialog_content = "さあ、イシマジロちゃん。\nいい子ねぇ、ふふふ――",
  ui_story_5028_50280101_36_dialog_content = "！！！",
  ui_story_5028_50280101_37_dialog_content = "大丈夫、怖がらないで…",
  ui_story_5028_50280101_38_dialog_content = "あたしはお友だちになりたいだけなの…",
  ui_story_5028_50280101_39_dialog_content = "？",
  ui_story_5028_50280101_40_dialog_content = "あっ、お友だちが何か、分からない？",
  ui_story_5028_50280101_41_dialog_content = "お友だちっていうのはね、\n一緒に食べたり、遊んだりするの。",
  ui_story_5028_50280101_42_dialog_content = "？",
  ui_story_5028_50280101_43_dialog_content = "そうよ、あなたを傷つけたりしないよ。",
  ui_story_5028_50280101_44_dialog_content = "こっちへおいで…",
  ui_story_5028_50280101_45_dialog_content = "ルルル！！",
  ui_story_5028_50280101_46_dialog_content = "！！！",
  ui_story_5028_50280101_47_dialog_content = "あっ！怖がらないで、今の鳴き声は…",
  ui_story_5028_50280101_48_dialog_content = "チィ！",
  ui_story_5028_50280101_49_dialog_content = "イシマジロちゃん！！！",
  ui_story_5028_50280101_50_dialog_content = "バカ！！逃げられちゃったじゃない！",
  ui_story_5028_50280101_51_dialog_content = "（あともう少しだったのに！）",
  ui_story_5028_50280101_52_dialog_content = "（でも、キャロが鳴いてるし、今はそっちを…）",
  ui_story_5028_50280101_X52_dialog_content = "（…あれ？でも、こんな鳴き方、\n今までしたことあるっけ？）",
  ui_story_5028_50280101_X53_dialog_content = "（のどが壊れそうなぐらい鳴いてる。\nカラスが大合唱してるみたい…）",
  ui_story_5028_50280101_53_dialog_content = "はぁ、何か面倒ごとでも起こしたのかな…",
  ui_story_5028_50280101_54_dialog_content = "…",
  ui_story_5028_50280101_55_dialog_content = "ルルルル！！ルルルル！！",
  ui_story_5028_50280101_56_dialog_content = "キャロ、もう大丈夫。\nあたしが戻ってきたよ。",
  ui_story_5028_50280101_57_dialog_content = "…ちょっと？\n木なんて登って、何してるの？",
  ui_story_5028_50280101_58_dialog_content = "ル…",
  ui_story_5028_50280101_59_dialog_content = "…",
  ui_story_5028_50280101_60_dialog_content = "ウソでしょ…",
  ui_story_5028_50280101_61_dialog_content = "でっかいクセして、ウサギが怖いの…？",
  ui_story_5028_50280101_62_dialog_content = "ル…",
  ui_story_5028_50280101_63_dialog_content = "何なのもう！そのせいであたしは\nイシマジロに逃げられちゃったってこと！？",
  ui_story_5028_50280101_64_dialog_content = "いつもジャマばかりして！\n今日はそのまま、木の上で過ごしてなさい！",
  ui_story_5028_50280101_65_dialog_content = "ル…",
  ui_story_5028_50280101_66_dialog_content = "ル～、ルルル～…",
  ui_story_5028_50280101_67_dialog_content = "もう、冗談だよ…\nそんな憐れな鳴き声出さなくたっていいでしょ。",
  ui_story_5028_50280101_68_dialog_content = "ねえねえ、ウサギさん。\nちょっと離れてもらっていいかな？",
  ui_story_5028_50280101_69_dialog_content = "私のお友だちがビックリしちゃったみたいなの。",
  ui_story_5028_50280101_70_dialog_content = "！？",
  ui_story_5028_50280101_71_dialog_content = "いいえ、あなたのことが怖いからじゃないの！",
  ui_story_5028_50280101_72_dialog_content = "<color=#e8d9bb>バン――！</color>",
  ui_story_5028_50280101_73_dialog_content = "ちょっと！どこにいるの！？\n出て来なさい！",
  ui_story_5028_50280101_74_dialog_content = "あんたが無理やりキャロをついてこさせたせいで、\n失敗したじゃないの！",
  ui_story_5028_50280101_75_dialog_content = "全然役に立たないどころか、\nジャマばっかりして！",
  ui_story_5028_50280101_76_dialog_content = "うるさいなぁ…誰だ？",
  ui_story_5028_50280101_77_dialog_content = "郵便屋か？窓の修理か？それとも…",
  ui_story_5028_50280101_78_dialog_content = "あたしだよ！あんたのカワイイ弟子！",
  ui_story_5028_50280101_79_dialog_content = "弟子？どの弟子だ？",
  ui_story_5028_50280101_80_dialog_content = "ヴィック",
  ui_story_5028_50280101_X80_dialog_content = "18歳？",
  ui_story_5028_50280101_81_dialog_content = "だらしない無職の男",
  ui_story_5028_50280101_82_dialog_content = "フィアだよ！！フィア！！",
  ui_story_5028_50280101_83_dialog_content = "また酔っぱらってボケてるの！？\n自分は誰だかぐらいは覚えてる？",
  ui_story_5028_50280101_83X_dialog_content = "簡単だな、俺はヴィックだ。",
  ui_story_5028_50280101_83X1_dialog_content = "ホントに聞いたわけじゃないよ…",
  ui_story_5028_50280101_84_dialog_content = "ああ、フィアか。",
  ui_story_5028_50280101_85_dialog_content = "ええと、どこに行くって言ってたっけな…",
  ui_story_5028_50280101_86_dialog_content = "リョクミャクゾウのフンを集めに行ったんだっけか？",
  ui_story_5028_50280101_87_dialog_content = "誰がそんなもの集めるの！？",
  ui_story_5028_50280101_88_dialog_content = "イシマジロを探しに行ったの！",
  ui_story_5028_50280101_89_dialog_content = "ああ、そうだそうだ、イシマジロだったな…\nどうだった？捕まったか？",
  ui_story_5028_50280101_90_dialog_content = "あと少しだったの！\nそれなのに！！",
  ui_story_5028_50280101_91_dialog_content = "このキャロにジャマされたの！\nそれで結局、逃げられちゃったの！！",
  ui_story_5028_50280101_S91_dialog_content = "そりゃ残念だったな。\nところで、なんでイシマジロなんて捕まえに行ったんだ？",
  ui_story_5028_50280101_S92_dialog_content = "習性を理解するためでしょ！？\nあんたが出した課題じゃない！",
  ui_story_5028_50280101_S93_dialog_content = "あ、そうだったな…\nだったら、「イシマジロは臆病」って書いときゃいいだろ。",
  ui_story_5028_50280101_S94_dialog_content = "はぁ？それだけ？",
  ui_story_5028_50280101_S95_dialog_content = "残りはゆっくりやりゃいいのさ。俺の言ったこと、覚えてるか？\n珍獣の研究は、相手を尊重することから始まるんだ。",
  ui_story_5028_50280101_S96_dialog_content = "珍獣たちの変わった習性と気性、\nそれから置かれている環境を尊重する。",
  ui_story_5028_50280101_S97_dialog_content = "理解はしても、干渉はしない。\nそれが珍獣の専門家としての心得だ。",
  ui_story_5028_50280101_92_dialog_content = "学問の道ってのは、そういうもんだ。\nお前が学ぶべきことも、まだたくさんある。",
  ui_story_5028_50280101_93_dialog_content = "またソレ？はいはい…\n何でも知ってる年寄りみたいな顔がしたいだけでしょ？",
  ui_story_5028_50280101_94_dialog_content = "なんだと！？俺はまだ若いぞ！！",
  ui_story_5028_50280101_X94_dialog_content = "イケメンに年は関係ないんだよ！",
  ui_story_5028_50280101_X95_dialog_content = "（はあ、大したナルシストだよ…\nいちいち構ってられない！）",
  ui_story_5028_50280101_95_dialog_content = "あたしが知りたいのは、\nなんでキャロを連れて行かせたのかってこと！",
  ui_story_5028_50280101_96_dialog_content = "キャロとは…あ、相性が悪いの！！\n相棒になんてなれないよ！",
  ui_story_5028_50280101_97_dialog_content = "キャロがいたら、何もできないの！\nこんなんじゃ、<color=#FFB400>珍獣マスター</color>になんてなれないよ！",
  ui_story_5028_50280101_98_dialog_content = "キャロとは話せないから、だろ？",
  ui_story_5028_50280101_99_dialog_content = "…",
  ui_story_5028_50280101_100_dialog_content = "…そう。",
  ui_story_5028_50280101_102_dialog_content = "動物と話ができるってのは、お前の生まれもっての才能だ。\nだが、それに頼り過ぎは、よくないな。",
  ui_story_5028_50280101_103_dialog_content = "例えば、光霊の言葉が分かるからって、\nそれだけで友だちになれるわけじゃないだろ？",
  ui_story_5028_50280101_104_dialog_content = "…あ、すまんすまん。\nお前、友だちいないんだったな。",
  ui_story_5028_50280101_105_dialog_content = "ちょっと…！？",
  ui_story_5028_50280101_106_dialog_content = "師匠だっていないでしょ！\nエラソーに！",
  ui_story_5028_50280101_107_dialog_content = "大人と子供じゃ、ワケが違うんだよ！\nお前に何が分かる！",
  ui_story_5028_50280101_108_dialog_content = "ふん、大人の友だち付き合いって、\n酒場でホラを吹くこと！？",
  ui_story_5028_50280101_109_dialog_content = "うっ、そ、それは…",
  ui_story_5028_50280101_110_dialog_content = "結局いつも、弟子のあたしが\n支払いのために呼び出されるんじゃない！",
  ui_story_5028_50280101_111_dialog_content = "やることもなくフラフラしてる中年男って、\n最後はみんな、師匠みたいになるの！？",
  ui_story_5028_50280101_112_dialog_content = "お金も仕事もなくて、毎日家でゴロゴロして！",
  ui_story_5028_50280101_113_dialog_content = "ええい、もう言うな！\n誰がやることもなくフラフラしてる中年男だ！",
  ui_story_5028_50280101_S113_dialog_content = "弟子が面倒見てないと、\n生きてけないくせに！",
  ui_story_5028_50280101_S114_dialog_content = "出かける時にいっつも3食分食事を用意して、\n帰って来たら、動物たちが荒らした部屋を掃除してるんだよ！？",
  ui_story_5028_50280101_S115_dialog_content = "「大人」だって言うなら、自分でちゃんと生活してよ！",
  ui_story_5028_50280101_S116_dialog_content = "お…お前…",
  ui_story_5028_50280101_114_dialog_content = "仮にも師匠なんだぞ？\nもう少し優しくしてもいいだろうが…",
  ui_story_5028_50280101_X114_dialog_content = "じゃあ…",
  ui_story_5028_50280101_X115_dialog_content = "（…違う違う！フィアは間違ってない！）",
  ui_story_5028_50280101_X116_dialog_content = "（ここで退いたら、\nまたいつもみたいにごまかされちゃう…）",
  ui_story_5028_50280101_X117_dialog_content = "（強気に出なきゃ…！そう、強気で！）",
  ui_story_5028_50280101_115_dialog_content = "そんなこと言ったって、\nマジメに教えてくれないじゃない！",
  ui_story_5028_50280101_116_dialog_content = "「自分でやってみろ」って言って、\n自分は家でゴロゴロしてばっかり！",
  ui_story_5028_50280101_117_dialog_content = "それどころか、足手まといまで押し付けて…",
  ui_story_5028_50280101_118_dialog_content = "理由ぐらい教えてくれてもいいでしょ！？",
  ui_story_5028_50280101_119_dialog_content = "分かった、分かった。\nまずは落ち着け…",
  ui_story_5028_50280101_120_dialog_content = "お前、考えたことはないか？他の動物のことは分かるのに、\nどうしてソイツだけダメなのかって。",
  ui_story_5028_50280101_121_dialog_content = "そんなの分からないよ…",
  ui_story_5028_50280101_122_dialog_content = "それはな、キャロが――",
  ui_story_5028_50280101_123_dialog_content = "<color=#FFB400>超希少種</color>だからだ。",
  ui_story_5028_50280101_124_dialog_content = "超希少種？",
  ui_story_5028_50280101_125_dialog_content = "ル…？",
  ui_story_5028_50280101_126_dialog_content = "俺たちが研究してる珍獣ってのは、\n自然界にいる、珍しくてぶっとんだ性質をもった生き物のことだ。",
  ui_story_5028_50280101_X126_dialog_content = "たぶん、それぞれが独自の方法で\n光力を使えるからだろうな。",
  ui_story_5028_50280101_X127_dialog_content = "だが、超希少種ってのは、そういう珍獣の中でもごくわずかな、\nただの珍獣を超える力を持った動物なのさ。",
  ui_story_5028_50280101_127_dialog_content = "でも、そんなに賢そうにも見えないよ？",
  ui_story_5028_50280101_128_dialog_content = "そりゃ、まだガキだからさ。\nお前みたいにな。",
  ui_story_5028_50280101_129_dialog_content = "超希少種ってのは、完全な変態をしてやっと成体になるんだ。\n俺はそれを<color=#FFB400>「進化」</color>って呼んでる。",
  ui_story_5028_50280101_130_dialog_content = "キャロが進化すれば、\nお前の想像もつかない力を持つだろうな。",
  ui_story_5028_50280101_131_dialog_content = "金が欲しけりゃ、\n石を黄金に換えられる…",
  ui_story_5028_50280101_132_dialog_content = "力が欲しけりゃ、軍隊だって簡単に握りつぶせる。\n白夜城だって楽勝だ。",
  ui_story_5028_50280101_133_dialog_content = "権力が欲しけりゃ、そいつの迫力には何も及ばない。\n北境の女王だって、頭を下げるだろうさ！",
  ui_story_5028_50280101_134_dialog_content = "俺はな、そういう生き物を、\n身を切る思いで、お前に預けたんだぞ。",
  ui_story_5028_50280101_135_dialog_content = "なんたって大事な弟子だからな…",
  ui_story_5028_50280101_136_dialog_content = "…",
  ui_story_5028_50280101_137_dialog_content = "ま～たそうやってホラを吹く…",
  ui_story_5028_50280101_138_dialog_content = "あ！？な、なんだって！？\n師匠に向かって何てことを言うんだ！",
  ui_story_5028_50280101_139_dialog_content = "もう耳にタコができるぐらい聞いたよ。",
  ui_story_5028_50280101_140_dialog_content = "去年は、飛空艇を買って\n遊びに連れて行ってくれるって言ったから…",
  ui_story_5028_50280101_141_dialog_content = "荷物をまとめて楽しみに待ってたのに、\n結局、風船をたくさん買って来ただけだったじゃない！",
  ui_story_5028_50280101_142_dialog_content = "いや、それは…飛空艇が\nあんなに高いとは知らなくて…",
  ui_story_5028_50280101_143_dialog_content = "それだけじゃないよ。冬には大事な研究課題があって、\nハリセンボンが必要だって言うから…",
  ui_story_5028_50280101_144_dialog_content = "3日かけてやっと住みかを見つけて、\n1晩かけて捕まえたのに…",
  ui_story_5028_50280101_145_dialog_content = "何かと思えば、\n靴磨きに使うだけだったじゃない！！",
  ui_story_5028_50280101_146_dialog_content = "うっ、それは…",
  ui_story_5028_50280101_147_dialog_content = "あとは自分は貴族だとか、歌手だったとか、何百万人のファンに\n追いかけられる毎日から逃れるために、珍獣研究者になったとか言ってたけど…",
  ui_story_5028_50280101_148_dialog_content = "全部ウソ！あたしをだましてるんでしょ！",
  ui_story_5028_50280101_149_dialog_content = "今回もきっとそう！\n超希少種なんてウソ！！",
  ui_story_5028_50280101_X149_dialog_content = "（なんだかムカついてきた！\nあたしはこんなにがんばってるのに、師匠は…）",
  ui_story_5028_50280101_X150_dialog_content = "フィア、待ってくれ…",
  ui_story_5028_50280101_150_dialog_content = "<size=50>あたしは本気で珍獣マスターになりたいの！</size>",
  ui_story_5028_50280101_151_dialog_content = "何も教えてくれないどころか、\n足手まといまで背負わされて…",
  ui_story_5028_50280101_152_dialog_content = "こんなんだったら、\n一人のほうがマシだよ！",
  ui_story_5028_50280101_153_dialog_content = "…",
  ui_story_5028_50280101_154_dialog_content = "そうか、分かった。",
  ui_story_5028_50280101_155_dialog_content = "俺からは、\nもう教わるものがないってことだな？",
  ui_story_5028_50280101_156_dialog_content = "そ、それは…",
  ui_story_5028_50280101_157_dialog_content = "お前には才能があるし、\n俺の教え方じゃ、もう古臭すぎるのかもな。",
  ui_story_5028_50280101_158_dialog_content = "自分じゃ、お前を一人前に\n育ててるつもりだったんだがな…",
  ui_story_5028_50280101_159_dialog_content = "「自分でやってみろ」って言ったのは、\n実践が大事だと思ったからさ。",
  ui_story_5028_50280101_160_dialog_content = "側にいなかったのも、\n自力で立ち向かう姿勢を身に付けてほしかったからだ。",
  ui_story_5028_50280101_161_dialog_content = "だが、今思えば、全部間違ってたんだな。",
  ui_story_5028_50280101_162_dialog_content = "そ、そうじゃないの…！",
  ui_story_5028_50280101_163_dialog_content = "そりゃそうだよな。\nお前は動物と話せる天才、教育なんて余計だ。",
  ui_story_5028_50280101_164_dialog_content = "…卒業した方がいいな。",
  ui_story_5028_50280101_165_dialog_content = "卒業！？",
  ui_story_5028_50280101_166_dialog_content = "そうだ、お前にはもう、\n俺みたいな師匠は必要ない。",
  ui_story_5028_50280101_167_dialog_content = "そ、そういうつもりで言ったわけじゃ…",
  ui_story_5028_50280101_168_dialog_content = "ちょうどいい。\n卒業試験はコイツにしよう。",
  ui_story_5028_50280101_169_dialog_content = "ル…？",
  ui_story_5028_50280101_170_dialog_content = "えっ？",
  ui_story_5028_50280101_171_dialog_content = "何はともあれ、俺は弟子の願いが\n叶うことを願ってるのは変わらない。",
  ui_story_5028_50280101_172_dialog_content = "俺がプレゼントしたキャロは、\nめったに見つからない超希少種だ。",
  ui_story_5028_50280101_173_dialog_content = "コイツを見事進化させることができれば、\nお前はもう一人前の専門家だと胸を張って言える。",
  ui_story_5028_50280101_174_dialog_content = "それが、俺の最後の授業だ。",
  ui_story_5028_50280101_175_dialog_content = "師匠…",
  ui_story_5028_50280101_176_dialog_content = "泣くんじゃない。\nそれがお前の夢だったんだろ？",
  ui_story_5028_50280101_177_dialog_content = "キャロが進化したらここへ戻ってきて、それで卒業だ。\nお前の夢も実現したことになる。",
  ui_story_5028_50280101_178_dialog_content = "俺みたいな師匠は、いてもいなくても変わらない…\n一人でさみしい晩年を送るとするさ。",
  ui_story_5028_50280101_179_dialog_content = "師匠…",
  ui_story_5028_50280101_180_dialog_content = "どうやったら進化させられるのか、\nまだ教えてくれてないよ。",
  ui_story_5028_50280101_181_dialog_content = "…",
  ui_story_5028_50280101_182_dialog_content = "お前が気にしてることは、それだけか？",
  ui_story_5028_50280101_183_dialog_content = "ほかに何かある？",
  ui_story_5028_50280101_184_dialog_content = "そうまでして専門家になりたいのか？",
  ui_story_5028_50280101_185_dialog_content = "そうだよ！私の夢だもん！",
  ui_story_5028_50280101_186_dialog_content = "し、師匠である俺には\n何も言うことないのか…？",
  ui_story_5028_50280101_187_dialog_content = "うーん…ある！！",
  ui_story_5028_50280101_188_dialog_content = "師匠、今度はウソじゃないよね？",
  ui_story_5028_50280101_189_dialog_content = "…",
  ui_story_5028_50280101_190_dialog_content = "まさか、実は進化させる方法なんて\n何も知らないワケじゃないよね？",
  ui_story_5028_50280101_191_dialog_content = "いや、そもそも進化すること自体がウソ…？",
  ui_story_5028_50280101_192_dialog_content = "そ、そんなワケないだろ！？",
  ui_story_5028_50280101_193_dialog_content = "俺がお前をだましたことなんて有ったか！？",
  ui_story_5028_50280101_194_dialog_content = "…",
  ui_story_5028_50280101_195_dialog_content = "…まあ、いい。\nこれに関してはウソじゃない。",
  ui_story_5028_50280101_196_dialog_content = "超希少種の進化が困難なのも本当だ。\n俺も確実に成功するような方法は知らない。",
  ui_story_5028_50280101_197_dialog_content = "このノートをお前にやる。",
  ui_story_5028_50280101_198_dialog_content = "これは…！",
  ui_story_5028_50280101_199_dialog_content = "そのノートには俺が考えてあった\n試練が書かれてる。",
  ui_story_5028_50280101_200_dialog_content = "覚えておけよ。\n実践が一番大事なんだ。",
  ui_story_5028_50280101_201_dialog_content = "全部やりとげた頃にはきっと、\nキャロが進化してるさ。",
  ui_story_5028_50280101_202_dialog_content = "自分を信じろ、お前はいつか必ず…",
  ui_story_5028_50280101_203_dialog_content = "分かった！ありがとう、師匠！",
  ui_story_5028_50280101_204_dialog_content = "じゃ、あたし行くね！バイバイ！",
  ui_story_5028_50280101_205_dialog_content = "おい、ちょっと待て、\n俺の話はまだ終わってな…",
  ui_story_5028_50280101_206_dialog_content = "<color=#e8d9bb>バタン！</color>",
  ui_story_5028_50280101_207_dialog_content = "とは言ったけど…",
  ui_story_5028_50280101_208_dialog_content = "キャロ、あんたって、\n本当に進化できるの？",
  ui_story_5028_50280101_209_dialog_content = "ルルル！",
  ui_story_5028_50280101_210_dialog_content = "とりあえず、グータラ師匠の\n試練とか言うのを見てみようかな…",
  ui_story_5028_50280101_211_dialog_content = "「超希少種進化論」",
  ui_story_5028_50280101_212_dialog_content = "「前書き：ここに書かれている試練の内容は\n筆者自身の経験に基づくものである」",
  ui_story_5028_50280101_213_dialog_content = "「あくまで提案であり、\n有効性を保証するものではない」",
  ui_story_5028_50280101_214_dialog_content = "フン、いきなり無責任ね…",
  ui_story_5028_50280101_215_dialog_content = "でも、1から4まである。\nけっこう色々考えてくれてたんだ…",
  ui_story_5028_50280101_216_dialog_content = "「試練1：<color=#FFB400>空の末裔</color>を1匹捕獲し、\n飼いならして友とする」",
  ui_story_5028_50280101_217_dialog_content = "空の末裔？どんな動物だろ？",
  ui_story_5028_50280201_1_dialog_content = "試練：空の末裔を捕獲せよ",
  ui_story_5028_50280201_2_dialog_content = "PlayerName、いつになったら遊べるのさ？",
  ui_story_5028_50280201_3_dialog_content = "あとちょっとだけ待ってて…\nもうすぐだから。",
  ui_story_5028_50280201_4_dialog_content = "なんで今じゃダメなの？\nおいら、待ちくたびれたよ。",
  ui_story_5028_50280201_5_dialog_content = "広くて平らな場所じゃないとダメなんだ。",
  ui_story_5028_50280201_6_dialog_content = "ここは障害物ばっかりでしょ。\nバッティングには向かないよ…",
  ui_story_5028_50280201_7_dialog_content = "ふうん、分かった。",
  ui_story_5028_50280201_8_dialog_content = "だったら、もっと早く歩こうよ？",
  ui_story_5028_50280201_9_dialog_content = "アハハ…せっかちだね。\n分かったよ、早歩きで行こう。",
  ui_story_5028_50280201_10_dialog_content = "<color=#e8d9bb>ガサガサ…</color>",
  ui_story_5028_50280201_11_dialog_content = "じゃあ、僕がボールを投げるから、\nバットで打ち返してね。",
  ui_story_5028_50280201_12_dialog_content = "ちょっと前に、古代文明に詳しいルビーが\nルールを教えてくれたんだ。",
  ui_story_5028_50280201_13_dialog_content = "簡単に言うと、ボールが遠くに飛ぶほど、\nすごいってことなんだって。",
  ui_story_5028_50280201_14_dialog_content = "分かった？",
  ui_story_5028_50280201_15_dialog_content = "ボールを打てばいい、分かった！",
  ui_story_5028_50280201_16_dialog_content = "うん！じゃ、1回やってみようか！",
  ui_story_5028_50280201_17_dialog_content = "3、2、1…",
  ui_story_5028_50280201_18_dialog_content = "えい！",
  ui_story_5028_50280201_19_dialog_content = "<color=#e8d9bb>サッ…</color>",
  ui_story_5028_50280201_20_dialog_content = "え？なんで避けたの？",
  ui_story_5028_50280201_21_dialog_content = "PlayerName、どうしておいらを\n急に攻撃するのさ？",
  ui_story_5028_50280201_22_dialog_content = "攻撃したんじゃないよ、\n今のが投球だよ。",
  ui_story_5028_50280201_23_dialog_content = "「投球」？",
  ui_story_5028_50280201_24_dialog_content = "そうだよ。僕がボールを君の方へ投げて、\n君はボールを打ち返す。そういう遊びなんだ。",
  ui_story_5028_50280201_25_dialog_content = "そうなんだ？じゃあ、もう1回。",
  ui_story_5028_50280201_26_dialog_content = "じゃあ行くよ。緊張しないでね。\n当たらなくても普通らしいから。",
  ui_story_5028_50280201_27_dialog_content = "うん。",
  ui_story_5028_50280201_28_dialog_content = "じゃあ、行くよ！\n3、2、1…",
  ui_story_5028_50280201_29_dialog_content = "それ！",
  ui_story_5028_50280201_30_dialog_content = "<color=#e8d9bb>シュッ…</color>",
  ui_story_5028_50280201_31_dialog_content = "<color=#e8d9bb>カキーン！！！</color>",
  ui_story_5028_50280201_32_dialog_content = "当たった！！！",
  ui_story_5028_50280201_33_dialog_content = "おお～！出来た！",
  ui_story_5028_50280201_34_dialog_content = "ボールが、遠くまで飛んでく！",
  ui_story_5028_50280201_35_dialog_content = "ホントだね！\nこれが話に聞いた「ホームラン」かな！？",
  ui_story_5028_50280201_36_dialog_content = "レビィ、才能があるのかもね！",
  ui_story_5028_50280201_37_dialog_content = "おいら、才能あるのかな？",
  ui_story_5028_50280201_38_dialog_content = "そうだよ！初めてでこんなに\n遠くに飛ばせるなんて！",
  ui_story_5028_50280201_39_dialog_content = "バッティング、面白い。",
  ui_story_5028_50280201_40_dialog_content = "で、この後はどうやって遊ぶの？",
  ui_story_5028_50280201_41_dialog_content = "この後は…",
  ui_story_5028_50280201_42_dialog_content = "ええと、まずはボールを拾ってこないとね。",
  ui_story_5028_50280201_43_dialog_content = "でも、ずいぶん遠くに\n飛んで行っちゃったから、大変だなぁ…",
  ui_story_5028_50280201_44_dialog_content = "ごめん。\n次は、軽く打つ。",
  ui_story_5028_50280201_45_dialog_content = "いやいや、責めたわけじゃないよ。\nそもそも遠くに飛ぶほどいいってルールなんだから！",
  ui_story_5028_50280201_46_dialog_content = "じゃ、おいらが拾ってくる。\nおいらの方が速いから。",
  ui_story_5028_50280201_47_dialog_content = "…もう5、6分経った気がするけど、\nレビィ、まだ帰ってこない…",
  ui_story_5028_50280201_48_dialog_content = "<color=#e8d9bb>ガサガサ…</color>",
  ui_story_5028_50280201_49_dialog_content = "ボールが見つからないのかな？\nまさか、何か危険な目にあったりは…",
  ui_story_5028_50280201_50_dialog_content = "そういえば、バイスがこの近くで\n暗鬼が出たらしいって言ってたような…",
  ui_story_5028_50280201_51_dialog_content = "<color=#e8d9bb>ガサガサ…</color>",
  ui_story_5028_50280201_52_dialog_content = "まぁ、普通の暗鬼は、\nレビィなら危険でも何でもないか。",
  ui_story_5028_50280201_53_dialog_content = "強いからね…",
  ui_story_5028_50280201_54_dialog_content = "おりゃー！！",
  ui_story_5028_50280201_55_dialog_content = "え…アミ？",
  ui_story_5028_50280201_56_dialog_content = "キャロのバカ！そっちじゃない！",
  ui_story_5028_50280201_57_dialog_content = "仕方ないわ！！\nこうなったら、強硬手段よ！",
  ui_story_5028_50280201_58_dialog_content = "だ、誰！？何だか分からないけど、\n僕にはすごい仲間がいるんだよ！？",
  ui_story_5028_50280201_59_dialog_content = "さっき僕の側にいた子なんて、\n素手で暗鬼をスイカみたいに割れるんだから！",
  ui_story_5028_50280201_60_dialog_content = "これ以上近づいたら、\n「感知能力」で仲間を呼ぶよ！",
  ui_story_5028_50280201_61_dialog_content = "「感知能力」？\nやっぱり空の末裔ね！",
  ui_story_5028_50280201_62_dialog_content = "仲間なんて呼ばせない！",
  ui_story_5028_50280201_63_dialog_content = "キャロ、プランB！",
  ui_story_5028_50280201_64_dialog_content = "ルルル！",
  ui_story_5028_50280201_65_dialog_content = "ちょっと待って！\nプランBって何！？",
  ui_story_5028_50280201_66_dialog_content = "これ以上近づかないで！\nじゃないと、本当に助けを呼ぶよ！",
  ui_story_5028_50280201_67_dialog_content = "いっけーっ！",
  ui_story_5028_50280201_68_option_content = "強制…うわっ！！",
  ui_story_5028_50280201_69_dialog_content = "腰が…！",
  ui_story_5028_50280201_70_dialog_content = "ルルル～！",
  ui_story_5028_50280201_71_dialog_content = "よくやったわ、キャロ！\n作戦通り、森まで退くよ！",
  ui_story_5028_50280201_72_dialog_content = "ルル！",
  ui_story_5028_50280201_73_dialog_content = "お、下ろして！\n僕をどこへ連れて行く気！？",
  ui_story_5028_50280201_74_dialog_content = "<anim type=Shake><size=45>レビィ！レビィ！？</size></anim>",
  ui_story_5028_50280201_76_dialog_content = "取って来たよ。白いウサギをボールだとカン違いして、\nさっきまでずっと追いかけてたんだ…",
  ui_story_5028_50280201_77_dialog_content = "…ん？PlayerNameは？",
  ui_story_5028_50280201_78_dialog_content = "ボールとバットが置きっぱなしだ。\nあっ、分かった。ホームランの練習してろってことかな？",
  ui_story_5028_50280201_79_dialog_content = "期待にはこたえないとね。\nまずは素振り1000回ぐらいやろっと。",
  ui_story_5028_50280201_80_dialog_content = "ルルル！",
  ui_story_5028_50280201_81_dialog_content = "ねぇ、ちょっと待ってよ…ヘンな生き物に\n僕を担がせて、どこへ連れて行くつもり？",
  ui_story_5028_50280201_82_dialog_content = "僕を下ろしてよ。さっきぶつけられた\n腰がすごく痛むし…",
  ui_story_5028_50280201_83_dialog_content = "ル…？",
  ui_story_5028_50280201_84_dialog_content = "ストップ！",
  ui_story_5028_50280201_85_dialog_content = "ふぅ…やっと止まってくれたね。\nイタタタタ…",
  ui_story_5028_50280201_86_dialog_content = "キャロ、ここ…プランBで\n決めてあったルート？",
  ui_story_5028_50280201_87_dialog_content = "ルル？",
  ui_story_5028_50280201_88_dialog_content = "もしかして、テキトーに森へ\n駆け込んだだけ？",
  ui_story_5028_50280201_89_dialog_content = "ル…？",
  ui_story_5028_50280201_90_dialog_content = "もう来た道が分からなくなってるじゃない…\n周りには木しかないし…",
  ui_story_5028_50280201_91_dialog_content = "君たち、軽率すぎるよ！\nこの森には暗鬼が出るって話なんだよ！？",
  ui_story_5028_50280201_92_dialog_content = "暗鬼？",
  ui_story_5028_50280201_93_dialog_content = "グォォ――！！",
  ui_story_5028_50280201_94_dialog_content = "本当に出て来た！",
  ui_story_5028_50280201_95_dialog_content = "どうして暗鬼が！？",
  ui_story_5028_50280201_96_dialog_content = "ぼうっとしてないで！\n早く逃げないと！",
  ui_story_5028_50280201_97_dialog_content = "グア！！",
  ui_story_5028_50280201_98_dialog_content = "キャロ！",
  ui_story_5028_50280201_99_dialog_content = "ルルル！",
  ui_story_5028_50280201_100_dialog_content = "暗鬼がなんでこんな所に！？",
  ui_story_5028_50280201_101_dialog_content = "今はそんなこと言ってる場合じゃないよ！\nまずは逃げるんだ！",
  ui_story_5028_50280201_102_dialog_content = "ダメ、もう走れない、うう…",
  ui_story_5028_50280201_103_dialog_content = "あたし、珍獣と仲良くするのは得意だけど、\n暗鬼は、大っキライなの！",
  ui_story_5028_50280201_104_dialog_content = "まだ夢もかなってないのに、\n暗鬼に食べられたくなんかないよぉ…！",
  ui_story_5028_50280201_105_dialog_content = "考えなきゃ、きっと何か方法があるはず…",
  ui_story_5028_50280201_106_dialog_content = "師匠が言ってたもん！危険を前にした時こそ、\n絶対に泣いちゃダメだ、頭を使えって！",
  ui_story_5028_50280201_107_dialog_content = "いっそあたしが時間稼ぎして、\nキャロと空の末裔を先に逃がすとか…",
  ui_story_5028_50280201_108_dialog_content = "あたしのせいで危険な目に遭わせるわけにはいかない！\nでも、あたしの力じゃ…",
  ui_story_5028_50280201_109_dialog_content = "あ、あの、少し落ち着いて。\n君って戦える？",
  ui_story_5028_50280201_110_dialog_content = "ううん…少しはやれるけど、\nあくまで護身用だよ。",
  ui_story_5028_50280201_111_dialog_content = "大丈夫！冒険を始めたてで出てくる敵は\n大体弱いものだから！",
  ui_story_5028_50280201_112_dialog_content = "運命なんて、そんな感じなんだよ。",
  ui_story_5028_50280201_113_dialog_content = "僕の能力を使えば助けてあげられる！",
  ui_story_5028_50280201_114_dialog_content = "このまま森の中を逃げ回っても、\nもっと多くの暗鬼の注意を引くだけだし…",
  ui_story_5028_50280201_114X_dialog_content = "まずは追ってきてる敵を倒して、\nそれから方法を考えることにしよう！",
  ui_story_5028_50280201_115_dialog_content = "でも、こんなにたくさん…",
  ui_story_5028_50280201_116_dialog_content = "僕を信じて！",
  ui_story_5028_50280201_117_dialog_content = "僕たち2人だけじゃない、この子も君の友だちだよね？\n全員で協力すればきっと勝てるよ！",
  ui_story_5028_50280201_118_dialog_content = "ルルル！",
  ui_story_5028_50280201_119_dialog_content = "…フン！そうね！",
  ui_story_5028_50280201_120_dialog_content = "それと、「君」じゃないわ！\nあたしは世界一の珍獣マスターになるんだから！",
  ui_story_5028_50280201_121_dialog_content = "暗鬼のくせに、急に出てきて、\nこのあたしをおどかそうなんて100年早い！",
  ui_story_5028_50280201_122_dialog_content = "さあ、覚悟しなさい！！",
  ui_story_5028_50280202_1_dialog_content = "ほ、本当に勝てた！",
  ui_story_5028_50280202_2_dialog_content = "やった！キャロ、見た？見た！？",
  ui_story_5028_50280202_3_dialog_content = "ルルルル！！ルルルル！！",
  ui_story_5028_50280202_4_dialog_content = "へへヘ…キャロもすごいじゃない。\nちょっと見直したよ！",
  ui_story_5028_50280202_5_dialog_content = "ル～！",
  ui_story_5028_50280202_6_dialog_content = "（喜んでるスキに離れよう…）",
  ui_story_5028_50280202_7_dialog_content = "あの…",
  ui_story_5028_50280202_8_dialog_content = "（…と思ったけど、暗鬼がいるし、\nこのままおいて行くのも危ないかな…）",
  ui_story_5028_50280202_9_dialog_content = "（うーん…）",
  ui_story_5028_50280202_10_dialog_content = "あの、空の末裔さん？",
  ui_story_5028_50280202_11_dialog_content = "えっ、何？",
  ui_story_5028_50280202_12_dialog_content = "さっきは…あたしとキャロを助けてくれて、\nありがとう。",
  ui_story_5028_50280202_13_dialog_content = "いやいや、とんでもない。\n大したことじゃないよ。",
  ui_story_5028_50280202_14_dialog_content = "感謝する必要なんて全くないよ。\nじゃあ、迷惑かけないうちに、僕はこれで失礼するね…",
  ui_story_5028_50280202_15_dialog_content = "迷惑なんかじゃないよ！\n空の末裔さん。",
  ui_story_5028_50280202_16_dialog_content = "でもまさか、あたしの恥ずかしい姿を見ておいて、\n逃げられるとでも思ってるの？",
  ui_story_5028_50280202_17_dialog_content = "な、何のことかな？ぼ、僕は何も覚えてないよ！\nここはどこ？さっきは何が…",
  ui_story_5028_50280202_18_dialog_content = "記憶喪失のフリなんてしてもムダだよ。",
  ui_story_5028_50280202_19_dialog_content = "キャロみたいにあたしのペットになって、\n大人しくあたしを助けて！",
  ui_story_5028_50280202_20_dialog_content = "（へへヘヘ、あたしのとびきり可愛い笑顔があれば、\n空の末裔をゲットするぐらい…）",
  ui_story_5028_50280202_21_dialog_content = "お断りだよ！",
  ui_story_5028_50280202_22_dialog_content = "えっ？",
  ui_story_5028_50280202_23_dialog_content = "成り行きで助けただけで、\n君の言うことを聞くかどうかは別の話だよ。",
  ui_story_5028_50280202_24_dialog_content = "それに、そのキャロっていうのにぶつかられた上に、\nここまで無理やり連れてこられたこともあるし…",
  ui_story_5028_50280202_25_dialog_content = "とにかく、まずは一緒に森を出よう。\nその後はお互い何もなかったことにして、お別れだ！",
  ui_story_5028_50280202_26_dialog_content = "…ぐすっ…",
  ui_story_5028_50280202_27_dialog_content = "（きつく言い過ぎたかな…？）",
  ui_story_5028_50280202_28_dialog_content = "（いや、まだ僕をだまそうとしてる可能性もある。\nキャロっていう生き物だって怪しい…）",
  ui_story_5028_50280202_29_dialog_content = "うぅ…",
  ui_story_5028_50280202_30_dialog_content = "あ、あたしはただ…\nお友だちが欲しかっただけなのに…",
  ui_story_5028_50280202_31_dialog_content = "ル…",
  ui_story_5028_50280202_32_dialog_content = "フィアを好きになるのなんて、珍獣ぐらいだって皆に言われて…\nあたしだって光霊や空の末裔とお友だちになれるって証明したかったのに…",
  ui_story_5028_50280202_33_dialog_content = "ただ、師匠の最後の言葉を\n叶えようとしただけなのに…",
  ui_story_5028_50280202_34_dialog_content = "（師匠？さっきフィアが話してた人かな？\n「最後の言葉」ってことは…もう亡くなってたの？）",
  ui_story_5028_50280202_35_dialog_content = "ハクション！！",
  ui_story_5028_50280202_36_dialog_content = "大丈夫だよ、モジャ。\nたぶん、風邪かなんかだろう。",
  ui_story_5028_50280202_37_dialog_content = "俺のことが心配か？\nじゃあ、お前で鼻をかんでもいいか？",
  ui_story_5028_50280202_38_dialog_content = "…ハハハ、冗談に決まってるだろ。\nお前の抜け毛は、酒と交換できるんだしな。",
  ui_story_5028_50280202_39_dialog_content = "（まさか、本当に泣きだしそう？\n目が真っ赤だ…）",
  ui_story_5028_50280202_40_dialog_content = "（この子はレビィよりもずっと小さいし、\n戦いも得意じゃない…）",
  ui_story_5028_50280202_40X_dialog_content = "（一人で苦労してるのかな…）",
  ui_story_5028_50280202_41_dialog_content = "だから、あたし、空の末裔を捕まえて、\nお友だちになってもらおうと思って…",
  ui_story_5028_50280202_42_dialog_content = "（まずい、こんな所で泣き出されたら…）",
  ui_story_5028_50280202_43_dialog_content = "ほ、本当に…ごめんなさい…\nひどい事しちゃったって、後悔してる…",
  ui_story_5028_50280202_44_dialog_content = "あたしのことが嫌いになったなら、\nこのまま、あたしを置き去りにして…",
  ui_story_5028_50280202_45_dialog_content = "好きにしてくれればいいから…",
  ui_story_5028_50280202_46_dialog_content = "うわあああああん！！",
  ui_story_5028_50280202_47_dialog_content = "わ、悪かったよ、ごめん！！",
  ui_story_5028_50280202_48_dialog_content = "僕が間違ってたよ！\nつい、きつく言いすぎちゃったんだ。",
  ui_story_5028_50280202_49_dialog_content = "友だちになりたいんだったよね。\n僕も君と友だちになりたい。名前はPlayerNameっていうんだ。",
  ui_story_5028_50280202_50_dialog_content = "ほ、ほんとに？あたし、フィア！",
  ui_story_5028_50280202_51_dialog_content = "じゃあ、フィア。\nこれで僕たちは友だちだ！",
  ui_story_5028_50280202_52_dialog_content = "ほんとに…？",
  ui_story_5028_50280202_53_dialog_content = "ほんとだよ！絶対にほんと！",
  ui_story_5028_50280202_54_dialog_content = "ルルル！",
  ui_story_5028_50280202_55_dialog_content = "えへへ…じゃあ、PlayerNameは、\nあたしの初めてのお友だちだね！",
  ui_story_5028_50280202_56_dialog_content = "お友だちになってくれて、\n本当にうれしい！",
  ui_story_5028_50280202_57_dialog_content = "師匠…フィア、お友だちができたよ！",
  ui_story_5028_50280202_58_dialog_content = "ルル～！",
  ui_story_5028_50280202_59_dialog_content = "（うっ！泣き落としの後に\nとびきりの笑顔…！？）",
  ui_story_5028_50280202_60_dialog_content = "（…でも、本当に昔の僕みたいに、友だちがいないのかな？\nいや…僕にはソラヴァンがいた）",
  ui_story_5028_50280202_61_dialog_content = "（この子にも、キャロっていう生き物がいる）",
  ui_story_5028_50280202_62_dialog_content = "（…まぁ、仮に演技だとしても、泣く子を\n置き去りにするワケにはいかないか…）",
  ui_story_5028_50280202_63_dialog_content = "PlayerName、PlayerName！\n何考えてるの？",
  ui_story_5028_50280202_64_dialog_content = "いや、大したことじゃないよ。ただ、そろそろ戻らないと。\n巨像で家まで送ってあげるよ。",
  ui_story_5028_50280202_65_dialog_content = "そうだった！\n空の末裔って、巨像を持ってるんだよね！",
  ui_story_5028_50280202_66_dialog_content = "じゃあ、これからの旅は巨像で移動できるんだね。\n師匠の試練もすぐに達成できそう！",
  ui_story_5028_50280202_67_dialog_content = "さあさあ、行こ！\nPlayerNameお兄ちゃ～ん！",
  ui_story_5028_50280202_68_dialog_content = "え？試練って何？\n手を引っ張らないで…？",
  ui_story_5028_50280202_69_dialog_content = "アイタタ！腰がまだ痛い！\n引っ張らないで！",
  ui_story_5028_50280202_70_dialog_content = "あと、レビィに声をかけておかないと――！",
  ui_story_5028_50280202_71_dialog_content = "998…フン！999…フン！",
  ui_story_5028_50280202_72_dialog_content = "1000回目…それっ！！",
  ui_story_5028_50280202_73_dialog_content = "PlayerName、まだ戻ってこないのかな？\n練習終わっちゃったよ。",
  ui_story_5028_50280202_74_dialog_content = "ま、いっか。もう巨像に戻ってるかもしれないね。\nおいらも戻ろ…",
  ui_story_5028_50280202_75_dialog_content = "あれ？",
  ui_story_5028_50280202_76_dialog_content = "巨像は？",
  ui_story_5028_50280202_77_dialog_content = "PlayerNameは…？",
  ui_story_5028_50280202_78_dialog_content = "どこ行ったんだろ？",
  ui_story_5028_50280202_79_dialog_content = "…ん？なんだろ、これ。書き置きかな？",
  ui_story_5028_50280301_1_dialog_content = "試練：ドラゴライオンの誕生を見届けよ",
  ui_story_5028_50280301_2_dialog_content = "<color=#FFB400>ドラゴライオン</color>は、\n神話に登場する巨龍のような頭部を持つ生物である…",
  ui_story_5028_50280301_3_dialog_content = "ライオンのようながっしりとした体に、\nタカやワシに似た、たくましい翼が生えており…",
  ui_story_5028_50280301_4_dialog_content = "サイを簡単に吹き飛ばせるほどの、\n強いしっぽも生えている。",
  ui_story_5028_50280301_5_dialog_content = "しかし、何より恐ろしいのは、強健な足である…",
  ui_story_5028_50280301_5X_dialog_content = "ドラゴライオンは地上のあらゆる獲物に追いつき、\n容赦なく仕留めるのだ…",
  ui_story_5028_50280301_6_dialog_content = "幸い、地上を走るより\n空を飛ぶことを好むため…",
  ui_story_5028_50280301_6X_dialog_content = "一般に目撃されることはほとんどない…",
  ui_story_5028_50280301_7_dialog_content = "しかし、今回は…そのドラゴライオンという\n<color=#FFB400>「超希少種」</color>こそが、我々のターゲットである…",
  ui_story_5028_50280301_8_dialog_content = "…ねぇ、フィア。\n何をブツブツ言ってるの？",
  ui_story_5028_50280301_9_dialog_content = "君が持ってる本、面白そうだね。\n僕にも見せてくれる？",
  ui_story_5028_50280301_10_dialog_content = "シーッ！！",
  ui_story_5028_50280301_11_dialog_content = "もう！！完璧なナレーションが\n台無しになっちゃったじゃない！！",
  ui_story_5028_50280301_12_dialog_content = "ル～！",
  ui_story_5028_50280301_13_dialog_content = "「ナレーション」？\nここには君と僕しかいないでしょ。",
  ui_story_5028_50280301_14_dialog_content = "なんでナレーションなんて必要なの？",
  ui_story_5028_50280301_15_dialog_content = "フフン！あたしたちのギョーカイには、\n大事なお決まりってモノがあるの！",
  ui_story_5028_50280301_16_dialog_content = "ターゲットの珍獣と接触する前に、\n必ず生態を復習しなきゃいけないんだよ。",
  ui_story_5028_50280301_17_dialog_content = "特にドラゴライオンぐらいの珍獣なら、\n出没する可能性のある場所から調査しないといけないし。",
  ui_story_5028_50280301_18_dialog_content = "まぁ、急に何かあった時でも対応できるようにって、\nおまじないみたいなもの！",
  ui_story_5028_50280301_19_dialog_content = "ルル！",
  ui_story_5028_50280301_20_dialog_content = "…ちょっと怖くなってきたなぁ。\nよく知らないから、今さら確認してただけなんじゃないの？",
  ui_story_5028_50280301_21_dialog_content = "もう、心配いらないって。メンミツに調査済みなんだから！\nドラゴライオンは、ほぼ100％出て来るよ！",
  ui_story_5028_50280301_22_dialog_content = "オッホン！\n…タカやワシに似た翼には…",
  ui_story_5028_50280301_23_dialog_content = "そこは、さっきもう聞いたよ。\nまた確認しなきゃいけないの？",
  ui_story_5028_50280301_24_dialog_content = "シーッ！もう、ジャマしないで！",
  ui_story_5028_50280301_25_dialog_content = "師匠のヘッタクソな字を読むだけで、\nこっちは手いっぱいなの！！",
  ui_story_5028_50280301_26_dialog_content = "ああ…そのノートって、\n君の師匠が遺した…？",
  ui_story_5028_50280301_27_dialog_content = "とにかく、ちょっと静かにしてて！\nここからが大事なところなの！",
  ui_story_5028_50280301_28_dialog_content = "ドラゴライオンはとても不思議な習性があり、\n空に異常なまでに執着する。",
  ui_story_5028_50280301_29_dialog_content = "生まれてくる子どもの命を脅かす生き物が周りにいるのでもなければ、\n出産の時でさえ、地上に降りてこようとしない。",
  ui_story_5028_50280301_30_dialog_content = "もっとも、脅威が現われれば、雷を呼び起こし、\nまた同時に鋭い爪で、引き裂いてしまうだろう。",
  ui_story_5028_50280301_31_dialog_content = "しかしながら、空から産み落とした卵が\n何事もなく着地し、無事にふ化するかどうかには、一切関心を示さない。",
  ui_story_5028_50280301_32_dialog_content = "子どもを危険だらけの世界に一人で向き合わせる…\n蒼き空の王が自らの子孫に対して行う、選別の儀式と言うべきだろうか。",
  ui_story_5028_50280301_33_dialog_content = "また、まさしくこの習性のため、\nドラゴライオンはほとんど繁殖できない。",
  ui_story_5028_50280301_34_dialog_content = "…ま、それでドラゴライオンの卵を安全にかえす、\nってのが課題にされたってコトね。",
  ui_story_5028_50280301_35_dialog_content = "珍獣本来の習性を重んじるのは当然だけど、\n時には手を差し伸べることも必要ってワケね。",
  ui_story_5028_50280301_36_dialog_content = "うんうん！こういう試練こそ、\nまさに珍獣マスターって感じ！",
  ui_story_5028_50280301_37_dialog_content = "ル～！",
  ui_story_5028_50280301_38_dialog_content = "どう考えても危険すぎるでしょ！\n僕は止めとく！！",
  ui_story_5028_50280301_39_dialog_content = "ちょ、ちょっと待ってよ！\nアッサリ見捨てないで！",
  ui_story_5028_50280301_40_dialog_content = "ルルル～！",
  ui_story_5028_50280301_41_dialog_content = "師匠のノートの通りなら、ドラゴライオンの赤ちゃんは\n卵が着地した瞬間に生まれるはずなの。",
  ui_story_5028_50280301_42_dialog_content = "つまり、卵が無事に着地できるように\nしてあげるだけでオッケーってこと！",
  ui_story_5028_50280301_43_dialog_content = "そんなに簡単な話なの…？\n「ナレーション」だと、恐ろしそうな生き物だったけど…",
  ui_story_5028_50280301_44_dialog_content = "専門家として見て、\nドラゴライオンの危険度って、何点ぐらい？",
  ui_story_5028_50280301_45_dialog_content = "だいたい？う～ん、50点ぐらいかな？",
  ui_story_5028_50280301_46_dialog_content = "そこそこって感じなんだね。\n少し安心したよ。",
  ui_story_5028_50280301_47_dialog_content = "（アッサリ信じられると、なんか罪悪感がすごい…）",
  ui_story_5028_50280301_48_dialog_content = "…10点満点だけどね…",
  ui_story_5028_50280301_49_dialog_content = "…",
  ui_story_5028_50280301_50_dialog_content = "ル…",
  ui_story_5028_50280301_51_dialog_content = "今のはちゃんと聞こえたよ！\nやっぱり、僕は帰る！",
  ui_story_5028_50280301_52_dialog_content = "ダメダメ、帰らないで！\nお願い！",
  ui_story_5028_50280301_53_dialog_content = "ちゃんと道具も持って来てるの！\nほら、におい消しだよ！",
  ui_story_5028_50280301_54_dialog_content = "これがあれば絶対に大丈夫だから！ノートにも書いてあるの。\nドラゴライオンは目がすごく悪いって！",
  ui_story_5028_50280301_55_dialog_content = "はぁ…",
  ui_story_5028_50280301_56_dialog_content = "もうちょっと安全そうな方法はないの？",
  ui_story_5028_50280301_57_dialog_content = "例えば、ソラヴァンで\n卵を受け止める、とか…？",
  ui_story_5028_50280301_58_dialog_content = "理論上はできるけど、1つ質問があるよ。",
  ui_story_5028_50280301_59_dialog_content = "ドラゴライオンに攻撃されたくないなら、\n知っとかないとなんだけど…ソラヴァンって…オス？それともメス？",
  ui_story_5028_50280301_60_dialog_content = "…",
  ui_story_5028_50280301_61_dialog_content = "…",
  ui_story_5028_50280301_62_dialog_content = "…ル？",
  ui_story_5028_50280301_63_dialog_content = "難しい質問だね…",
  ui_story_5028_50280301_64_dialog_content = "やっぱり、今の話はなかったことにして。",
  ui_story_5028_50280301_65_dialog_content = "専門家の君が考えたやり方が一番だと思うよ。\nたぶん、おそらく、きっと…",
  ui_story_5028_50280301_66_dialog_content = "もちろん、安心して！\n珍獣マスターの力を見せてあげる！",
  ui_story_5028_50280301_67_dialog_content = "ル～！",
  ui_story_5028_50280301_68_dialog_content = "ハッ…ハックション！",
  ui_story_5028_50280301_69_dialog_content = "このにおい消しのにおい、\nどこかで嗅いだことあるような…",
  ui_story_5028_50280301_70_dialog_content = "少なくとも、虫よけ効果は抜群だね。\n草むらに隠れてるのに、虫が僕たちを避けて通ってる…",
  ui_story_5028_50280301_71_dialog_content = "ル～！",
  ui_story_5028_50280301_72_dialog_content = "ふふふ…キャロの分泌物でできてるの。\nよく効くんだから！",
  ui_story_5028_50280301_73_dialog_content = "――ブーッ！",
  ui_story_5028_50280301_74_dialog_content = "そういうことは早く言ってよ！",
  ui_story_5028_50280301_75_dialog_content = "なんだか全身がかゆくなってきた気が…\n有害なものじゃないんだよね？",
  ui_story_5028_50280301_76_dialog_content = "大丈夫、大丈夫！\nあたしもたくさん塗ってるでしょ。",
  ui_story_5028_50280301_77_dialog_content = "粘り気があって保湿効果も高いんだ。\nお肌にすごくいいの。",
  ui_story_5028_50280301_78_dialog_content = "あたしなんか、普段からこれで\nスキンケアしてるぐらいだよ。",
  ui_story_5028_50280301_78X_dialog_content = "そのおかげで、一日中どんなところに調査に行っても、\nお肌がツルツルピカピカなんだから。",
  ui_story_5028_50280301_79_dialog_content = "ルル～！",
  ui_story_5028_50280301_80_dialog_content = "シッ…何かいる！",
  ui_story_5028_50280301_81_dialog_content = "ドラゴライオン？",
  ui_story_5028_50280301_82_dialog_content = "ドラゴライオンは産卵が近づくと、できるだけ静かに、\n自分が安全だと思う場所へ飛んでいくはずなの。",
  ui_story_5028_50280301_83_dialog_content = "だけど、あたしには分かる。\n空気をあおぐみたいなこの音、間違いなく…",
  ui_story_5028_50280301_84_dialog_content = "<color=#e8d9bb>ガサガサ…</color>",
  ui_story_5028_50280301_85_dialog_content = "ううん、ドラゴライオンの羽ばたく音なんて\n聞いたことないけど…あっちの草むらかな？",
  ui_story_5028_50280301_86_dialog_content = "マズい気がする…\nまた、何かがジャマしにきたのかな。",
  ui_story_5028_50280301_87_dialog_content = "キャロ、追い払って来て！",
  ui_story_5028_50280301_88_dialog_content = "ルルル！",
  ui_story_5028_50280301_89_dialog_content = "PlayerName、本当に聞こえない？\n楽器の弦をはじくみたいな音。",
  ui_story_5028_50280301_90_dialog_content = "<color=#e8d9bb>ガサガサガサガサ…</color>",
  ui_story_5028_50280301_91_dialog_content = "…ル！",
  ui_story_5028_50280301_92_dialog_content = "僕には聞こえないよ。\n聞こえるのはキャロと草の音だけ…",
  ui_story_5028_50280301_93_dialog_content = "ルルル！ルルル！",
  ui_story_5028_50280301_94_dialog_content = "もう！髪の毛ひっこ抜いて\n弾いて聞かせなきゃ分かんないの！？",
  ui_story_5028_50280301_95_dialog_content = "<size=45>ルルルル！！</size>",
  ui_story_5028_50280301_96_dialog_content = "キャロ、うるさい！",
  ui_story_5028_50280301_97_dialog_content = "グォォ――！！",
  ui_story_5028_50280301_98_dialog_content = "暗鬼だ！",
  ui_story_5028_50280301_99_dialog_content = "よりによってこんな時に…！？\n産卵が近いドラゴライオンに見つかったら、全員オシマイだよ！",
  ui_story_5028_50280301_100_dialog_content = "PlayerName、早く片付けないと！",
  ui_story_5028_50280301_101_dialog_content = "分かった、行くよ！",
  ui_story_5028_50280301_102_dialog_content = "ル！！",
  ui_story_5028_50280302_1_dialog_content = "何とか片付いたね。",
  ui_story_5028_50280302_2_dialog_content = "におい消しを塗ったはずだけど、\n暗鬼には効かないのかな。",
  ui_story_5028_50280302_3_dialog_content = "PlayerNameってもしかして、\n暗鬼を引き付ける装置か何かなんじゃないの？",
  ui_story_5028_50280302_4_dialog_content = "暗鬼にとっては、灯台みたいに\n光ってるみたいな感じで、すっごく目を引くとか…",
  ui_story_5028_50280302_5_dialog_content = "ガが明かりに突っ込むみたいな感じで…",
  ui_story_5028_50280302_6_dialog_content = "よく考えて見ると、\n本当にそうかもしれないなぁ…",
  ui_story_5028_50280302_7_dialog_content = "海でしょ、雪山に、砂漠に、遺跡…\nどこに行っても、暗鬼が突然出て来るんだ。",
  ui_story_5028_50280302_8_dialog_content = "名探偵がどこへ行っても事件が起きる、みたいな…",
  ui_story_5028_50280302_9_dialog_content = "<size=30>やっぱり…師匠、そういうことね…</size>",
  ui_story_5028_50280302_10_dialog_content = "え？",
  ui_story_5028_50280302_11_dialog_content = "ま、それは置いとくとして…\nドラゴライオンにはまだ気づかれてないみたい。",
  ui_story_5028_50280302_12_dialog_content = "たぶん、もうすぐ産卵するよ。\n今まさに、降りてきてる。隠れないと…",
  ui_story_5028_50280302_13_dialog_content = "僕にも見えたけど…あんな高い所で産む気？\n卵なんて確実に割れちゃうんじゃないの？",
  ui_story_5028_50280302_14_dialog_content = "ヘンな習性だなぁ…\nこれじゃ、いくら卵を産んでも絶滅まっしぐらだよ。",
  ui_story_5028_50280302_15_dialog_content = "アストラ大陸の動物学者もみんな、\n同じ疑問を持ってるの。",
  ui_story_5028_50280302_16_dialog_content = "でも、珍獣っていうのは、そういうものなんだよ。\n習性と合理的かどうかは関係ないの！",
  ui_story_5028_50280302_17_dialog_content = "だから…このままじゃ、ダメ。\nなにか方法を考えなきゃ…",
  ui_story_5028_50280302_18_dialog_content = "ルルル！",
  ui_story_5028_50280302_19_dialog_content = "フィア？なにをする気？",
  ui_story_5028_50280302_20_dialog_content = "き、木の上で受け止める！",
  ui_story_5028_50280302_21_dialog_content = "ムリだよ！高い木だって言っても、\nいちばん上まで登ったところで届かないよ！",
  ui_story_5028_50280302_22_dialog_content = "それに、木に登ってたら、\nアミが使えないでしょ？",
  ui_story_5028_50280302_23_dialog_content = "うーん…じゃあ、どうしたら、\n助けてあげられるの…",
  ui_story_5028_50280302_24_dialog_content = "ドラゴライオンって何十年に1度しか卵を産まないんだよ！\n本当に珍しい、絶滅危惧種なの！",
  ui_story_5028_50280302_25_dialog_content = "師匠から確かな情報をもらったのに、\n守ってあげられないなんて。師匠…",
  ui_story_5028_50280302_26_dialog_content = "ル…",
  ui_story_5028_50280302_27_dialog_content = "分かった！",
  ui_story_5028_50280302_28_dialog_content = "何か思いついたの？まさか…",
  ui_story_5028_50280302_29_dialog_content = "…本当に大丈夫？",
  ui_story_5028_50280302_30_dialog_content = "イチかバチか、やってみるしかない！",
  ui_story_5028_50280302_31_dialog_content = "ソラヴァンまで使って助けてくれるなんて…\nPlayerName、頼りになるんだね！",
  ui_story_5028_50280302_32_dialog_content = "命が目の前で消えていくのを、\n何もせずに見てるわけにはいかないでしょ。",
  ui_story_5028_50280302_33_dialog_content = "ソラヴァンのことを気に入ってくれるかは\n分からないけど、試してみる価値はある！",
  ui_story_5028_50280302_34_dialog_content = "ガオオォォォ――",
  ui_story_5028_50280302_35_dialog_content = "ドラゴライオン、\nソラヴァンにすごく興味があるみたい！",
  ui_story_5028_50280302_36_dialog_content = "友だちだと思ってるみたいだね。\nまっすぐ近づいてくる…",
  ui_story_5028_50280302_37_dialog_content = "いい感じ！あと少し、あと少しだけ近づいて、\nアミで卵を…",
  ui_story_5028_50280302_38_dialog_content = "（ん？ドラゴライオンの足首、何か付いてる…？\nまあいいや、今はこっちに集中！）",
  ui_story_5028_50280302_39_dialog_content = "ルルルル！！ルルルル！！",
  ui_story_5028_50280302_40_dialog_content = "ガオオォォォ――",
  ui_story_5028_50280302_41_dialog_content = "フィア！近づいて来たよ！",
  ui_story_5028_50280302_42_dialog_content = "分かってる！もう少し近づいて！\nその後は、あたしとキャロに任せて！",
  ui_story_5028_50280302_43_dialog_content = "３…",
  ui_story_5028_50280302_44_dialog_content = "2…",
  ui_story_5028_50280302_45_dialog_content = "1！",
  ui_story_5028_50280302_46_dialog_content = "フィア！",
  ui_story_5028_50280302_47_dialog_content = "ル！！",
  ui_story_5028_50280302_48_dialog_content = "！",
  ui_story_5028_50280302_49_dialog_content = "やった！！",
  ui_story_5028_50280302_50_dialog_content = "まぶしい！\n卵がかえったのかな？",
  ui_story_5028_50280302_51_dialog_content = "プー…",
  ui_story_5028_50280302_52_dialog_content = "プ？",
  ui_story_5028_50280302_53_dialog_content = "ルル～！",
  ui_story_5028_50280302_54_dialog_content = "か、かわいい…！",
  ui_story_5028_50280302_55_dialog_content = "こんなに小さいコが、\nあんなに大きく育つんだ？",
  ui_story_5028_50280302_56_dialog_content = "不思議だな～。\nさすがは<color=#FFB400>超希少種</color>だけあるね。",
  ui_story_5028_50280302_57_dialog_content = "フィア！どう、うまく行った？",
  ui_story_5028_50280302_58_dialog_content = "うん！PlayerNameとソラヴァンのおかげで、\nちゃんと生まれたよ。",
  ui_story_5028_50280302_59_dialog_content = "ル～！",
  ui_story_5028_50280302_60_dialog_content = "キャロも、ありがと。",
  ui_story_5028_50280302_61_dialog_content = "ルル～！",
  ui_story_5028_50280302_62_dialog_content = "ポピ～！",
  ui_story_5028_50280302_63_dialog_content = "でも、お祝いにはまだ早いみたい…",
  ui_story_5028_50280302_64_dialog_content = "ドラゴライオンがソラヴァンをつかんで、離してくれない！\nこれじゃ僕たち、地上に降りられないよ！",
  ui_story_5028_50280302_65_dialog_content = "あっ、さっきはいい所で切られちゃったけど…",
  ui_story_5028_50280302_65X_dialog_content = "ドラゴライオンって、無事に生まれた子供には、\n強烈な保護意識を持ってるんだって。あたしたち、子供泥棒だと思われてるかも…",
  ui_story_5028_50280302_66_dialog_content = "え！？だったら僕たち、終わりじゃない…？",
  ui_story_5028_50280302_67_dialog_content = "う～ん、でも違う。\n鳴き方に敵意がなさそう。",
  ui_story_5028_50280302_68_dialog_content = "この鳴き方…まさか、ソラヴァンのこと、\n本当に好きになっちゃったとか…？",
  ui_story_5028_50280302_69_dialog_content = "何だって！？",
  ui_story_5028_50280302_70_dialog_content = "…PlayerName、ここにもいないなー…",
  ui_story_5028_50280302_71_dialog_content = "あれ？アンタ、レビィじゃん？\nなんでこんなとこフラついてんの？",
  ui_story_5028_50280302_72_dialog_content = "あっ、スモーキー。",
  ui_story_5028_50280302_73_dialog_content = "おいら、空の末裔を探してるんだ。",
  ui_story_5028_50280302_74_dialog_content = "ちょっと前まで、PlayerNameと\n近くでバッティングしてたんだけど…",
  ui_story_5028_50280302_75_dialog_content = "遊んでたら、いなくなっちゃって。書き置きっぽいのが有ったけど、\nユーカイされたんじゃないかって心配してるとこ。",
  ui_story_5028_50280302_76_dialog_content = "はあ？",
  ui_story_5028_50280302_77_dialog_content = "何つった？\nPlayerNameが誘拐？",
  ui_story_5028_50280302_78_dialog_content = "書き置きってのは？",
  ui_story_5028_50280302_79_dialog_content = "暗鬼と戦ってたら失くしちゃった。",
  ui_story_5028_50280302_80_dialog_content = "ふ～ん、面白そーじゃん…",
  ui_story_5028_50280302_81_dialog_content = "アイツも災難だね。\n誘拐なんて、どこの物好きだろ…",
  ui_story_5028_50280302_82_dialog_content = "探すの、手伝って。",
  ui_story_5028_50280302_83_dialog_content = "おいら、バイスとグラムに叱られちゃうよ。",
  ui_story_5028_50280302_84_dialog_content = "ちょうどヒマだったし、\nカワイソーな空の末裔探しにつきあってあげっかな。",
  ui_story_5028_50280401_1_dialog_content = "試練：ブドウ園の危機を解決せよ",
  ui_story_5028_50280401_2_dialog_content = "ふぅ…ふぅ…はあ…",
  ui_story_5028_50280401_3_dialog_content = "ちょ…ちょっと、フィア。\nもっとゆっくり歩いて…",
  ui_story_5028_50280401_4_dialog_content = "僕たち、どこへ向かってるの？",
  ui_story_5028_50280401_5_dialog_content = "ブドウの木ばっかりだけど、\n今度はブドウドラゴンの産卵でも見るつもり？",
  ui_story_5028_50280401_6_dialog_content = "ル…",
  ui_story_5028_50280401_7_dialog_content = "シーッ…今、ドラゴライオンの幼体の\n観察記録を整理してるの。",
  ui_story_5028_50280401_8_dialog_content = "こんなに成長が速いとは思わなかったよ。\nあっという間にキャロより大きくなって、独り立ちしちゃった…",
  ui_story_5028_50280401_9_dialog_content = "もう自分の住む場所を自分で探しに行けるなんて…",
  ui_story_5028_50280401_9X_dialog_content = "可愛い赤ちゃんドラゴンの姿、\nもっと見たかったのに…",
  ui_story_5028_50280401_10_dialog_content = "こっちはしつこく絡んでくるドラゴライオンのせいで\nそれどころじゃなかったよ！",
  ui_story_5028_50280401_11_dialog_content = "もう歩けない…ちょっと休憩しよう。",
  ui_story_5028_50280401_12_dialog_content = "ええ～、もう疲れたの？\nあと少しで着くよ。",
  ui_story_5028_50280401_13_dialog_content = "PlayerNameは世話が焼けるな～。\nほら、早く口開けて、これ飲んで。",
  ui_story_5028_50280401_14_dialog_content = "な、何するの！飲まないよ！？",
  ui_story_5028_50280401_15_dialog_content = "いいから、いいから～！",
  ui_story_5028_50280401_16_dialog_content = "来ないで！",
  ui_story_5028_50280401_17_dialog_content = "キャロ、PlayerNameを抑えてて！",
  ui_story_5028_50280401_18_dialog_content = "ルル～！",
  ui_story_5028_50280401_19_dialog_content = "うわっ！ゴクゴクゴク…",
  ui_story_5028_50280401_20_dialog_content = "辛い！あれ、違う…口の中にミルクみたいな味が…\nいや、ちょっと待って、今度はなんかヒンヤリしてきた！？",
  ui_story_5028_50280401_21_dialog_content = "何を僕に飲ませたの！？",
  ui_story_5028_50280401_22_dialog_content = "カエンギュウから絞ったミルクに、クリクリ草の根っこから取った汁を混ぜた、\nあたし特製のエナジードリンクだよ！",
  ui_story_5028_50280401_23_dialog_content = "北境でしか採れないスノーミントでわざわざ味付けしたんだよ。\nヒンヤリして、気分もスッキリするでしょ？",
  ui_story_5028_50280401_24_dialog_content = "全部キャロにのませて、キャロのお腹の中で調合するの。\n手で作るよりうまく混ざるんだ。",
  ui_story_5028_50280401_25_dialog_content = "PlayerNameもすぐに元気が出るよ！",
  ui_story_5028_50280401_25X_dialog_content = "けっこう貴重な材料で作ってあるんだから！",
  ui_story_5028_50280401_26_dialog_content = "ル～！",
  ui_story_5028_50280401_27_dialog_content = "おぇっ！\nキャロ、そんなこと手伝わなくていいよ！",
  ui_story_5028_50280401_28_dialog_content = "ル…？",
  ui_story_5028_50280401_29_dialog_content = "それからフィア、君もだよ！",
  ui_story_5028_50280401_30_dialog_content = "えっ？",
  ui_story_5028_50280401_31_dialog_content = "ヘンな薬を勝手に作って人に試すなんて、\n違法行為でしょ！？",
  ui_story_5028_50280401_32_dialog_content = "え！？そ、そうなの…！？",
  ui_story_5028_50280401_33_dialog_content = "こ、このことは、ヒミツにしといて！\nフィア、若いうちから牢屋なんて入りたくないよ…！",
  ui_story_5028_50280401_34_dialog_content = "…捕まりたくないなら、\n今後、いきなり変なものを人に飲ませるのはやめてね…",
  ui_story_5028_50280401_35_dialog_content = "分かったよ～、\nせっかく飲ませてあげたのに…",
  ui_story_5028_50280401_36_dialog_content = "…ん？でも、\n確かに効き目が出てきたような…",
  ui_story_5028_50280401_37_dialog_content = "体力が八割ぐらい戻った気がする。",
  ui_story_5028_50280401_38_dialog_content = "ほら、言ったでしょ！ちょっと待ってて。\n今回のレシピ、記録しとかなきゃ…",
  ui_story_5028_50280401_39_dialog_content = "ちょっと！？初めて試したの！？\n僕に何かあったら、空の末裔が絶滅動物のリスト入りだよ！？",
  ui_story_5028_50280401_40_dialog_content = "いきなり飲まされたヘンなもので死ぬなんて…",
  ui_story_5028_50280401_41_dialog_content = "打ち切りになった小説でもなかなか見ないよ！",
  ui_story_5028_50280401_42_dialog_content = "え？さすがにそんなことはしないよ。\nで、身体の調子はどう？",
  ui_story_5028_50280401_42X_dialog_content = "キャロからもう少し分けてもらう？",
  ui_story_5028_50280401_43_dialog_content = "ル！？",
  ui_story_5028_50280401_44_dialog_content = "いらない！自分で飲んで！",
  ui_story_5028_50280401_45_dialog_content = "とにかく、もう僕にヘンなものを\n食べさせたり飲ませたりしないで！",
  ui_story_5028_50280401_46_dialog_content = "空の末裔のクセに、エナジードリンクが怖いの～？\nへえ～、PlayerNameって怖がりなんだ～。",
  ui_story_5028_50280401_47_dialog_content = "ソラヴァンの回収を手伝ってもらう必要がなかったら、\n今すぐ君にお仕置きしたいところだよ…",
  ui_story_5028_50280401_48_dialog_content = "えへへ、そこは安心して。\nあたしたち、ちゃんとドラゴライオンから逃げてこられたでしょ？",
  ui_story_5028_50280401_49_dialog_content = "ソラヴァン、ずいぶん気に入られちゃったみたいだけど…\nてことは、ヒドいことはされないはずだよ。",
  ui_story_5028_50280401_50_dialog_content = "ドラゴライオンに捕まって振り回されてるだけで、\nもう十分ヒドい目だと思うんだけど…",
  ui_story_5028_50280401_51_dialog_content = "もし…",
  ui_story_5028_50280401_52_dialog_content = "うひゃあ！！",
  ui_story_5028_50280401_53_dialog_content = "え、だ、誰？\n暗鬼？野獣？妖怪？",
  ui_story_5028_50280401_54_dialog_content = "驚かせてすみませんが…ただの光霊ですよ。",
  ui_story_5028_50280401_55_dialog_content = "ヴィックさんの優秀なお弟子さんとは、あなたかな？",
  ui_story_5028_50280401_56_dialog_content = "ヴィック？",
  ui_story_5028_50280401_57_dialog_content = "（こんな優しそうなおじさんに驚かされるなんて、\nまだまだあたし、注意力が足りないんだ。しっかりしないと…）",
  ui_story_5028_50280401_58_dialog_content = "あの、おじさん…ヴィックの弟子はあたし！\n珍獣マスターのフィアだよ！",
  ui_story_5028_50280401_59_dialog_content = "まだ修行中じゃなかった？",
  ui_story_5028_50280401_60_dialog_content = "修行中でも専門家は専門家でしょ！",
  ui_story_5028_50280401_61_dialog_content = "おお！これはこれは、失礼しました。\n私に見る目がなかったようで。",
  ui_story_5028_50280401_62_dialog_content = "ええと、師匠の…？",
  ui_story_5028_50280401_63_dialog_content = "昔、白夜城で衛兵をしていまして。\n戦争も何度か経験しました。",
  ui_story_5028_50280401_64_dialog_content = "ほら、私のヒザを見てください。\nソルラド殿下と共に暗鬼に立ち向かった時、受けた傷です。",
  ui_story_5028_50280401_65_dialog_content = "おじさんって、一体――",
  ui_story_5028_50280401_66_dialog_content = "ああ…でも、私はずっと物書きになりたかったんです。\nそれで、勤務中にこっそり小説を書くようになって…",
  ui_story_5028_50280401_67_dialog_content = "それが長官に見つかってしまって、繰り上げで退役になったんです。\nその後、ここでブドウを育ててるってわけです。",
  ui_story_5028_50280401_68_dialog_content = "あの、あたしの話を――",
  ui_story_5028_50280401_69_dialog_content = "でも、おかげでヒット作品もたくさん書けたんですよ。",
  ui_story_5028_50280401_69X_dialog_content = "『騎士はもう死んでいる』、『裁判官ファミリー』、\n『カオナシライダー』、あとは…",
  ui_story_5028_50280401_70_dialog_content = "おじさん！お願いだから、\n先に依頼の内容を教えて！",
  ui_story_5028_50280401_71_dialog_content = "ああ、そうでしたそうでした。\n依頼でいらしたんでしたね。すぐお話します。",
  ui_story_5028_50280401_72_dialog_content = "もう、ダメダメダメダメ、ダメ師匠！",
  ui_story_5028_50280401_73_dialog_content = "伝書バト1つで、あのボケたおじさんの代わりに\nブドウ棚の見張りなんて！",
  ui_story_5028_50280401_74_dialog_content = "フィアは珍獣マスターになりたいの！\nコソ泥の見張りなんてガラじゃないのに！",
  ui_story_5028_50280401_75_dialog_content = "ほら、寝てないで。\n交代の時間だよ！",
  ui_story_5028_50280401_76_dialog_content = "…ヨダレたらして寝てる…",
  ui_story_5028_50280401_77_dialog_content = "起きなさーい！！",
  ui_story_5028_50280401_78_dialog_content = "うわぁっ！？ど、泥棒が来たの！？",
  ui_story_5028_50280401_79_dialog_content = "そうそう！ソラヴァンが盗まれて、\n雲の向こうに行っちゃったよ！",
  ui_story_5028_50280401_80_dialog_content = "え？ほんとに！？",
  ui_story_5028_50280401_81_dialog_content = "ウソに決まってるでしょ！\n交代の時間だよ！あたし、もう眠くて…",
  ui_story_5028_50280401_82_dialog_content = "<color=#e8d9bb>ずいぶん後</color>",
  ui_story_5028_50280401_83_dialog_content = "…ふぅ。",
  ui_story_5028_50280401_84_dialog_content = "ハ～イ。",
  ui_story_5028_50280401_85_dialog_content = "ん…えっ？",
  ui_story_5028_50280401_86_dialog_content = "モグモグ…",
  ui_story_5028_50280401_87_dialog_content = "フィア！！",
  ui_story_5028_50280401_88_dialog_content = "ん、んんにゃにぃ？",
  ui_story_5028_50280401_89_dialog_content = "ル…？",
  ui_story_5028_50280401_90_dialog_content = "早く起きて！",
  ui_story_5028_50280401_91_dialog_content = "ブドウが食べられちゃってる！！",
  ui_story_5028_50280401_92_dialog_content = "へ…！？",
  ui_story_5028_50280401_93_dialog_content = "犯人があっちに逃げた！\n急いで追いかけよう！",
  ui_story_5028_50280401_94_dialog_content = "なんてずる賢いヤツ！",
  ui_story_5028_50280401_95_dialog_content = "一瞬で森に逃げ込んじゃって…\nどこへ行ったか分からないよ。",
  ui_story_5028_50280401_96_dialog_content = "仕方ないよ。あんな速さじゃ、\nそもそも追いつけない…",
  ui_story_5028_50280401_97_dialog_content = "仲間がいるかもしれないから、\n早く戻ってブドウの見張りを続けよう。",
  ui_story_5028_50280401_98_dialog_content = "ぷっ、くくく…",
  ui_story_5028_50280401_99_dialog_content = "フィア？大丈夫？犯人は逃がしちゃったけど、\n急におかしくなるほどマズい状況じゃないよ。",
  ui_story_5028_50280401_100_dialog_content = "ち、違うの。\n急にジョークを思い出しちゃっただけ。",
  ui_story_5028_50280401_101_dialog_content = "えっ？",
  ui_story_5028_50280401_102_dialog_content = "「旅人がR・W砂漠の奥に行けば、\n必ずサンドワームが出る」っていうありがちな話のヤツ…",
  ui_story_5028_50280401_103_dialog_content = "きっと続きは、\n「空の末裔が森に行けば、必ず…」",
  ui_story_5028_50280401_104_dialog_content = "グォォ――！！",
  ui_story_5028_50280401_105_dialog_content = "どこが笑いどころなの！？\n本当に暗鬼が出て来たし、早く逃げよう！！",
  ui_story_5028_50280401_106_dialog_content = "まさか本当に！？\nちょっと！？あたしを置いて逃げないでよ！？",
  ui_story_5028_50280401_107_dialog_content = "待ってってば！",
  ui_story_5028_50280402_1_dialog_content = "ふぅ、ふぅ…",
  ui_story_5028_50280402_2_dialog_content = "暗鬼、しつこい…！",
  ui_story_5028_50280402_3_dialog_content = "グゥアアアア――！？",
  ui_story_5028_50280402_4_dialog_content = "気をつけて！",
  ui_story_5028_50280402_5_dialog_content = "あっ！",
  ui_story_5028_50280402_6_dialog_content = "だ、大丈夫…\nありがと、PlayerName…",
  ui_story_5028_50280402_7_dialog_content = "…あっ！ノートが…！？",
  ui_story_5028_50280402_8_dialog_content = "フィア！これ以上集まる前に、急いでノートを拾いに行って！\nこっちは僕に任せて！",
  ui_story_5028_50280402_9_dialog_content = "でも…",
  ui_story_5028_50280402_10_dialog_content = "急いで！",
  ui_story_5028_50280402_11_dialog_content = "グアアッ！",
  ui_story_5028_50280402_12_dialog_content = "フィアを追いかけて行っちゃった…\n暗鬼たち、僕のことは目に入ってない…",
  ui_story_5028_50280402_13_dialog_content = "（チャンスをうかがって、\n暗鬼の弱点をしっかり狙えば…）",
  ui_story_5028_50280402_14_dialog_content = "グアアッ！",
  ui_story_5028_50280402_15_dialog_content = "（いや、ダメだ！このままじゃフィアが囲まれる！\nゆっくりしてられない！）",
  ui_story_5028_50280402_16_dialog_content = "食らえ！！",
  ui_story_5028_50280402_17_dialog_content = "どうだ、暗鬼め！！\n僕の体当たりでも、不意打ちなら…",
  ui_story_5028_50280402_18_dialog_content = "…イタタタタ！\nこっちが石にぶつかった気分だ…",
  ui_story_5028_50280402_19_dialog_content = "グア！",
  ui_story_5028_50280402_20_dialog_content = "やっぱりダメだったか…\n急いでフィアを連れて逃げないと！",
  ui_story_5028_50280402_21_dialog_content = "ノート…あった！\nPlayerName、急いで逃げよう！",
  ui_story_5028_50280402_22_dialog_content = "はぁ――やっと振り切れた…",
  ui_story_5028_50280402_23_dialog_content = "PlayerName、大丈夫！？\n腕が腫れてるよ！？",
  ui_story_5028_50280402_24_dialog_content = "大したことじゃないよ。\nさっき暗鬼に体当たりしたせいだ。すごく硬くて…",
  ui_story_5028_50280402_25_dialog_content = "あたしのせいで…\nごめん、すぐにお薬を塗ってあげるね！",
  ui_story_5028_50280402_26_dialog_content = "大丈夫だよ。\nフィアが師匠の形見を取り戻せたなら…",
  ui_story_5028_50280402_27_dialog_content = "え？形見？",
  ui_story_5028_50280402_28_dialog_content = "あっ…ええと、それは…\nウソ泣きしてた時の…",
  ui_story_5028_50280402_29_dialog_content = "…ごめんなさい！\n実は師匠、まだ生きてる…",
  ui_story_5028_50280402_30_dialog_content = "えっ？",
  ui_story_5028_50280402_31_dialog_content = "薬は塗ったし、包帯も巻いたよ。\n腫れはすぐに引くはず…",
  ui_story_5028_50280402_32_dialog_content = "<size=30>とにかく…ごめんなさい…</size>",
  ui_story_5028_50280402_33_dialog_content = "何か言った？",
  ui_story_5028_50280402_34_dialog_content = "<size=30>ごめんなさいって言ったの…</size>",
  ui_story_5028_50280402_35_dialog_content = "声が小さすぎて、\n何を言ってるか聞こえないよ…",
  ui_story_5028_50280402_36_dialog_content = "すうっ――",
  ui_story_5028_50280402_37_dialog_content = "<size=45>ごめんなさい、ごめんなさいごめんなさい！\n謝ってるの！！！</size>",
  ui_story_5028_50280402_38_dialog_content = "うわあ！きゅ、急にどうしたの？",
  ui_story_5028_50280402_39_dialog_content = "ごめんなさい。あたし、ウソをついてた。\n謝るし、ちゃんと反省してる。",
  ui_story_5028_50280402_40_dialog_content = "でも…あたしの師匠、\nいつも、あたしをだましたり、こき使ってばっかりで…",
  ui_story_5028_50280402_41_dialog_content = "PlayerNameとは違って、\nぜんぜん優しく助けてくれたりしないの。",
  ui_story_5028_50280402_42_dialog_content = "あの時は焦って、つい出まかせを言っちゃったけど、\n友だちになりたいのはホント！ウソじゃないよ！",
  ui_story_5028_50280402_43_dialog_content = "だから、ウソついたこと、許して…",
  ui_story_5028_50280402_44_dialog_content = "…それはそれとして、\n師匠は爆発か何かすればいいと思うけど！",
  ui_story_5028_50280402_45_dialog_content = "ハクション――！",
  ui_story_5028_50280402_46_dialog_content = "なんだ？また誰か、俺のウワサか？\nどこのどいつだ…？",
  ui_story_5028_50280402_47_dialog_content = "…イヤな予感がするな…",
  ui_story_5028_50280402_48_dialog_content = "分かったよ。ウソ泣きなのは予想してたけど、\nほっとくわけにもいかなかったから。",
  ui_story_5028_50280402_49_dialog_content = "でも、師匠のこと、\nそこまで言わなくていいんじゃないかな。",
  ui_story_5028_50280402_50_dialog_content = "どんな人か知らないけど、仮にも師匠なんでしょ？\n冗談だとしても、良くないよ。",
  ui_story_5028_50280402_51_dialog_content = "このノートも、字は汚いけど、内容はすごい。\n書いた人がどれだけの努力をつぎ込んでるか、よく分かる。",
  ui_story_5028_50280402_52_dialog_content = "大切なノートを預けてくれてるんだ。\n師匠はきっと、君のことを高く買ってるはずだよ。",
  ui_story_5028_50280402_53_dialog_content = "うっ…わ、分かった…\nたぶん、その通りかもね。",
  ui_story_5028_50280402_54_dialog_content = "師匠はホントにどうしようもない人だけど、言い過ぎた。\nここにいないけど、ごめんなさい、師匠。",
  ui_story_5028_50280402_55_dialog_content = "もう言わないって約束する！\nだから…",
  ui_story_5028_50280402_56_dialog_content = "頭をなでるの、やめてくれる？\nいくら友だちでも、恥ずかしいよ。キャロだって見てるし…",
  ui_story_5028_50280402_57_dialog_content = "あっ、ごめん。\nちょうどいいところに頭があったから…",
  ui_story_5028_50280402_58_dialog_content = "何！？\nあたしがチビだって言いたいの！？",
  ui_story_5028_50280402_59_dialog_content = "コホン、それは、ええと…\nところで、さっきのブドウ泥棒、何か手がかりはある？",
  ui_story_5028_50280402_60_dialog_content = "あたしの見間違いじゃなければ、\nたぶん、<color=#FFB400>「ビッカー」</color>っていう珍獣だよ。",
  ui_story_5028_50280402_61_dialog_content = "ノートに、丸い食べ物が好きって書いてあるの。\nどんな大きさでも、一口で丸のみしちゃうんだって。",
  ui_story_5028_50280402_62_dialog_content = "よく伸びる体で、飲み込んだ食べ物の大きさに合わせて、\n自分の大きさも変化するみたい。",
  ui_story_5028_50280402_63_dialog_content = "足も速くて、\n飛ぶような速度で逃げられるけど…",
  ui_story_5028_50280402_64_dialog_content = "あんまり賢くはなくて、\nちょっと鈍いぐらいの珍獣だって。",
  ui_story_5028_50280402_65_dialog_content = "丸い食べ物？\nちょっと考えさせて…",
  ui_story_5028_50280402_66_dialog_content = "<size=30>これで、本当に大丈夫？</size>",
  ui_story_5028_50280402_67_dialog_content = "<size=30>カゴの中にスイカを置いただけだよ？\nおいしそうなスイカだけど…</size>",
  ui_story_5028_50280402_68_dialog_content = "<size=30>いくら何でも、こんなに簡単に…</size>",
  ui_story_5028_50280402_69_dialog_content = "<size=30>間違いないよ。ノートに書いてあることが本当なら、\nこんなに大きくて丸い食べ物をガマンできるはずがない。</size>",
  ui_story_5028_50280402_70_dialog_content = "<size=30>師匠のノートも、僕の判断も、\n信じてくれるでしょ？</size>",
  ui_story_5028_50280402_71_dialog_content = "<size=30>分かったよ…\nあ、何か近づいてきた…</size>",
  ui_story_5028_50280402_72_dialog_content = "ハーイ…ハーイ…",
  ui_story_5028_50280402_73_dialog_content = "ハイ？",
  ui_story_5028_50280402_74_dialog_content = "ハイ～～",
  ui_story_5028_50280402_75_dialog_content = "食べた！",
  ui_story_5028_50280402_76_dialog_content = "ルルル！",
  ui_story_5028_50280402_77_dialog_content = "ほんとに引っかかった！\nあんまり賢くないっていうのも間違いないみたいだね。",
  ui_story_5028_50280402_78_dialog_content = "ハイ！？ハイ！？",
  ui_story_5028_50280402_79_dialog_content = "怖がらないで、僕は悪い人じゃないよ。",
  ui_story_5028_50280402_80_dialog_content = "ハイ？",
  ui_story_5028_50280402_81_dialog_content = "ねえ、ここのブドウを食べるの、\nやめてくれないかな？",
  ui_story_5028_50280402_82_dialog_content = "ハイハイ？",
  ui_story_5028_50280402_83_dialog_content = "あたしが話すよ。",
  ui_story_5028_50280402_84_dialog_content = "怖がらないで…\nあなたを傷つけるつもりはないの。",
  ui_story_5028_50280402_85_dialog_content = "ハイ…？",
  ui_story_5028_50280402_86_dialog_content = "PlayerName、カゴを開けてくれる？\nもう逃げないから、大丈夫。",
  ui_story_5028_50280402_87_dialog_content = "本当に？\nじゃあ、開けるよ？",
  ui_story_5028_50280402_88_dialog_content = "ハイ…",
  ui_story_5028_50280402_89_dialog_content = "え？スイカがおいしかった？\n捕まったのに、そんなこと考えてたの？",
  ui_story_5028_50280402_90_dialog_content = "ハイハイ！",
  ui_story_5028_50280402_91_dialog_content = "この子、恐ろしい怪物から\n逃げて来たって言ってる。",
  ui_story_5028_50280402_92_dialog_content = "きっと怖かったんだね…かわいそうに。\nでも、ブドウは盗み食いしちゃダメだからね。",
  ui_story_5028_50280402_93_dialog_content = "フィア、君ってまさか…",
  ui_story_5028_50280402_94_dialog_content = "ハ～イ。",
  ui_story_5028_50280402_95_dialog_content = "え？あたしと一緒の方が安全だし、\nたくさんスイカが食べられそう？",
  ui_story_5028_50280402_96_dialog_content = "もう、ほめたってなにも出ないよ～？",
  ui_story_5028_50280402_97_dialog_content = "PlayerName、この子、飼おうよ。そうすれば、\n畑の物を食べちゃうこともないし、他の動物にもいじめられないよ。",
  ui_story_5028_50280402_98_dialog_content = "君がそう言うなら、\n僕に異論はないよ。",
  ui_story_5028_50280402_99_dialog_content = "キャロ、この子と一緒がいいでしょ？",
  ui_story_5028_50280402_100_dialog_content = "ル～！",
  ui_story_5028_50280402_101_dialog_content = "うん…じゃあ、この子もこれで、\n新しい旅の仲間だね！",
  ui_story_5028_50280402_102_dialog_content = "――おいらの分、貼ったよ。",
  ui_story_5028_50280402_103_dialog_content = "こっちも終わったとこ。",
  ui_story_5028_50280402_104_dialog_content = "人探しの張り紙なんてどーせ大して役に立たないけど、\nちょっとは情報入るっしょ、運が良ければ。",
  ui_story_5028_50280402_105_dialog_content = "…ん？誰？",
  ui_story_5028_50280402_106_dialog_content = "フフフ…見たわよ、スモーキー！",
  ui_story_5028_50280402_107_dialog_content = "まさか、あなたが広告張りの仕事をするほど\nお金に困っているなんてね。",
  ui_story_5028_50280402_108_dialog_content = "しかも、啓光のお友だちとご一緒？",
  ui_story_5028_50280402_109_dialog_content = "どうしてもって言うなら、\n貸してあげてもいいわよ？",
  ui_story_5028_50280402_110_dialog_content = "利息は、そうね…\n「気持ち」と言ったところかしら？",
  ui_story_5028_50280402_111_dialog_content = "チッ…ウザいのが来た…",
  ui_story_5028_50280402_112_dialog_content = "レビィ、啓光の銃とコイツと、どっちがうるさい？",
  ui_story_5028_50280402_113_dialog_content = "おいら、銃使わないから、分かんない。",
  ui_story_5028_50280402_114_dialog_content = "PlayerNameがいなくなっちゃったんだ。\nスモーキーは探すの、手伝ってくれてるの。",
  ui_story_5028_50280402_115_dialog_content = "あら？空から槍でも降って来やしないかしら。\nあなたが理にかなったことをするなんてね。",
  ui_story_5028_50280402_116_dialog_content = "でも、PlayerNameを探してるっていうなら、\n私も探すわ。あなたに先を越されるのは面白くないもの。",
  ui_story_5028_50280402_117_dialog_content = "止めてくんない？",
  ui_story_5028_50280402_118_dialog_content = "アンタはさっさと病院に行って、\n負けず嫌いをなんとかしてもらう方が先っしょ。",
  ui_story_5028_50280402_119_dialog_content = "アンタが付いてくると、いっつも面倒なことになんの。\nそもそも、空の末裔とそんなに仲良かった？",
  ui_story_5028_50280402_120_dialog_content = "それか、なんか企んでる？\nアンタの金魚のフンどもの仲間に入れようとか？",
  ui_story_5028_50280402_121_dialog_content = "安心しなさい！\n企むならもっと他に相手がいるわ。",
  ui_story_5028_50280402_122_dialog_content = "へー、そんな「ラッキー」なヤツ、いるんだ？",
  ui_story_5028_50280402_123_dialog_content = "おいら、ゴミ箱の裏に\nPlayerNameがいないか、探してくるよ。",
  ui_story_5028_50280501_1_dialog_content = "試練：海岸の謎を解き明かせ",
  ui_story_5028_50280501_2_dialog_content = "日差しが強くて暑いなぁ…",
  ui_story_5028_50280501_3_dialog_content = "でも、海風が気持ちいい。",
  ui_story_5028_50280501_4_dialog_content = "人もいっぱいだ！",
  ui_story_5028_50280501_5_dialog_content = "まさか、またここに来られるなんて。",
  ui_story_5028_50280501_6_dialog_content = "暑いよ～、人も多すぎるよ～…",
  ui_story_5028_50280501_7_dialog_content = "ル～！",
  ui_story_5028_50280501_8_dialog_content = "やっぱり、この季節の海はいいね！",
  ui_story_5028_50280501_9_dialog_content = "おっと！",
  ui_story_5028_50280501_10_dialog_content = "あっ、すみません！\n大丈夫ですか？",
  ui_story_5028_50280501_11_dialog_content = "大丈夫です、こっちこそすみません。",
  ui_story_5028_50280501_12_dialog_content = "ん～？もしかして、倒れてきたのが\n女の子だったら良かったのに～とか思った？",
  ui_story_5028_50280501_13_dialog_content = "そんなことないよ！",
  ui_story_5028_50280501_14_dialog_content = "そう？ってことは、\n今の男の人が好みなんだ？",
  ui_story_5028_50280501_15_dialog_content = "そうでもないよ！\nからかわないで！",
  ui_story_5028_50280501_16_dialog_content = "それはそうと、君の師匠って、\n君のこと、本当に大事に思ってるみたいだね。",
  ui_story_5028_50280501_17_dialog_content = "海で息抜きするのも試練のうちなの？",
  ui_story_5028_50280501_18_dialog_content = "そんなワケないでしょ。\nあの師匠がそんないい事考えるワケないもん。",
  ui_story_5028_50280501_19_dialog_content = "人が多すぎてうっとうしいし…どうしてここへ来させたんだろ？\nちゃんと説明もしてくれないし…",
  ui_story_5028_50280501_20_dialog_content = "師匠ってね、モジャたちのブラッシングをあたしにさせて、\n集めた毛を、お金に換えるの。",
  ui_story_5028_50280501_21_dialog_content = "で、お金に換えた後は、\nお酒とか遊びに使っちゃうの。",
  ui_story_5028_50280501_22_dialog_content = "なのにあたしは、家に置いてかれて、ポチャ鳥のエサを作ったり、\nココナツシカのフンの始末をしたり、ハヤイヌを散歩に連れて行ったり…",
  ui_story_5028_50280501_23_dialog_content = "あたしみたいなカワイイ女の子を、\n使用人みたいにこき使ってるんだよ！？",
  ui_story_5028_50280501_24_dialog_content = "研究観察で出かけた時も、\n師匠のテキトーなメモのせいで、ヒドい目に遭わされたし…",
  ui_story_5028_50280501_25_dialog_content = "ル、ル。",
  ui_story_5028_50280501_26_dialog_content = "ううん…じゃあ、なんで弟子なんてやってるの？",
  ui_story_5028_50280501_27_dialog_content = "それに、文句は言ってるけど、\nマジメに師匠から言われた仕事をこなしてるよね？",
  ui_story_5028_50280501_28_dialog_content = "師匠とは腐れ縁なの！",
  ui_story_5028_50280501_29_dialog_content = "あたし、小さい頃から、\n<color=#FFB400>『ふしぎな小動物』</color>っていう本が大好きで…",
  ui_story_5028_50280501_30_dialog_content = "あたしが楽しい子供時代を過ごせたのは、\nその本のおかげなんだ。",
  ui_story_5028_50280501_30X_dialog_content = "本がきっかけで、あたしも小動物と交流するようになって、\nどんどん動物たちのことが好きになったの。",
  ui_story_5028_50280501_31_dialog_content = "でも、影ノ街は光霊だらけで、珍獣なんていないから…\n満足できなくて、決心したの。",
  ui_story_5028_50280501_32_dialog_content = "この本を書いた人のところへ行って、あたしをワクワクさせてくれた珍獣たちが\nどこにいるのか、直接聞こうって。",
  ui_story_5028_50280501_33_dialog_content = "それで、あたしはパパとママにさよならして、\n荷物をまとめて、一人で作者が住んでるって聞いた森に行ったの。",
  ui_story_5028_50280501_34_dialog_content = "毎日探しても、手がかりが全く見つからなかったんだけど、\nテントの前でクリクリの実を焼いて食べてたら…",
  ui_story_5028_50280501_35_dialog_content = "男の人が突然草むらから出てきて、ゆっくりあたしの方へはいずって来たの。\n行き倒れ寸前って感じで。",
  ui_story_5028_50280501_36_dialog_content = "まさか、それが…",
  ui_story_5028_50280501_37_dialog_content = "そういうこと。その時のあたしは、\n探してた人が見つかったなんて思わなかったけど。",
  ui_story_5028_50280501_38_dialog_content = "散々食べた後に、その人が言いだしたの。\n「俺は大陸で唯一の珍獣研究者で、今は近くで生態調査をしてる」って。",
  ui_story_5028_50280501_39_dialog_content = "どう考えても怪しかったから、\n街に戻って衛兵さんを呼ぼうかって思ったぐらいだったけど…",
  ui_story_5028_50280501_40_dialog_content = "ノートを見せられたんだ。雑な字だけど、マジメに色々書かれてた。\nそれから、不思議な道具も色々持ってた。",
  ui_story_5028_50280501_41_dialog_content = "あと、口笛を吹いただけで、\n近くのいろんな珍獣を呼び寄せたりもできたの。",
  ui_story_5028_50280501_42_dialog_content = "PlayerName、\nビッカーに会った時のこと、覚えてる？",
  ui_story_5028_50280501_43_dialog_content = "もう分かってると思うけど、あたし、珍獣と話ができるの。\n空の末裔の能力と似てるかもね。",
  ui_story_5028_50280501_44_dialog_content = "あたしにはドラゴライオンやビッカーの鳴き声も分かるの。\n光霊といるより…珍獣たちと一緒にいる方が好き。",
  ui_story_5028_50280501_45_dialog_content = "ま、あの時のあたしは、きっと珍獣たちに囲まれて、\n舞い上がってたんだと思う。",
  ui_story_5028_50280501_46_dialog_content = "おまけに、「珍獣と話せるのか？\n偉大な研究者になる素質があるぞ」って言われて…",
  ui_story_5028_50280501_47_dialog_content = "その時のあたしには、\nあまりにも魅力的な話すぎた…",
  ui_story_5028_50280501_48_dialog_content = "いや、今だって、そんなこと言われたら、\n弟子になっちゃうかも…",
  ui_story_5028_50280501_49_dialog_content = "とにかく、その時に確信したの。\n目の前にいるのがあの本を書いた、珍獣マスターのヴィックに違いないって。",
  ui_story_5028_50280501_50_dialog_content = "…自分で選んだ道だけど、\nやっぱり師匠、ダメ師匠ね！",
  ui_story_5028_50280501_51_dialog_content = "ハハハ…ずっと自分の好きな道を突き進んで来たんだね。",
  ui_story_5028_50280501_52_dialog_content = "あっ――！",
  ui_story_5028_50280501_53_dialog_content = "気をつけて！",
  ui_story_5028_50280501_54_dialog_content = "ご、ごめんなさい！足元が滑ってしまって…",
  ui_story_5028_50280501_55_dialog_content = "大丈夫ですよ、ケガがなくてよかった。",
  ui_story_5028_50280501_56_dialog_content = "（また？）",
  ui_story_5028_50280501_57_dialog_content = "悪いけど、僕に言わせてもらえるなら…",
  ui_story_5028_50280501_58_dialog_content = "人生って、そういうものじゃないかな。\n何もかも満足なんていかないし、君はもう、大勢の人より幸せだと思うよ！",
  ui_story_5028_50280501_59_dialog_content = "何それ、お兄さんぶってるの？\nムリに大人のフリしたって痛々しいだけだよ。",
  ui_story_5028_50280501_60_dialog_content = "さっきスタイルのいいお姉さんが転んだ時に、\n頭でもぶつけちゃった？",
  ui_story_5028_50280501_61_dialog_content = "いやいや、さっきの人とはぶつかってないよ。\n手を出して支えてあげただけ。",
  ui_story_5028_50280501_62_dialog_content = "…ひょっとして、フィア…\n僕にヤキモチを焼いてる？",
  ui_story_5028_50280501_63_dialog_content = "フン、そんなくだらないこと、するワケないでしょ！\n珍獣がいっぱい側に居てくれれば、あたしは十分だもん。",
  ui_story_5028_50280501_64_dialog_content = "本当にそうかな？",
  ui_story_5028_50280501_65_dialog_content = "フンだ！！！",
  ui_story_5028_50280501_66_dialog_content = "わ、分かったよ…話を戻すと、珍獣と意思疎通ができるなら、\n確かに珍獣マスターになれる素質があるよね。",
  ui_story_5028_50280501_67_dialog_content = "僕が光霊のみんなの戦いを指揮して助けられるのも、\nそういう能力があるからっていうのと同じだ。",
  ui_story_5028_50280501_68_dialog_content = "フン、確かにそうかも。でも、例外もあるんだ。\nキャロの考えてることは分からないの。",
  ui_story_5028_50280501_69_dialog_content = "ル～！",
  ui_story_5028_50280501_70_dialog_content = "どうして？",
  ui_story_5028_50280501_71_dialog_content = "分かんない…師匠が言うには、\nキャロは超希少種で、トクベツなんだって。",
  ui_story_5028_50280501_72_dialog_content = "ルルル！",
  ui_story_5028_50280501_73_dialog_content = "「超希少種」？超希少種って、\nあのドラゴライオンみたいな動物のことじゃないの？",
  ui_story_5028_50280501_74_dialog_content = "あんたもそう思うでしょ？\nやっぱり師匠のヨタ話なんて信じらんないよね。",
  ui_story_5028_50280501_75_dialog_content = "ル…ル…",
  ui_story_5028_50280501_76_dialog_content = "落ち込まないで、キャロ。",
  ui_story_5028_50280501_77_dialog_content = "考えてることを読み取れなくても、\nあなたがいい子だってことは、ちゃんと分かってるから。",
  ui_story_5028_50280501_78_dialog_content = "ル～！",
  ui_story_5028_50280501_79_dialog_content = "ま、何の役にも立たないし、\n頼りがいもないけど…",
  ui_story_5028_50280501_80_dialog_content = "ル！！",
  ui_story_5028_50280501_81_dialog_content = "あっ！！",
  ui_story_5028_50280501_82_dialog_content = "人が転んだ？また？",
  ui_story_5028_50280501_83_dialog_content = "やっぱりここ、何かおかしい。\n転んだ人がいた所を見てみないと！",
  ui_story_5028_50280501_84_dialog_content = "フィア！そんなに急いだら――",
  ui_story_5028_50280501_85_dialog_content = "あっ――",
  ui_story_5028_50280501_86_dialog_content = "よいしょ！",
  ui_story_5028_50280501_87_dialog_content = "あ、ありがとう、PlayerName…",
  ui_story_5028_50280501_88_dialog_content = "まったく…転びやすいって分かってるのに、\n飛び出して行っちゃうなんて。",
  ui_story_5028_50280501_89_dialog_content = "ごめん…つい、あせっちゃった。\n…早く下ろしてくれる？",
  ui_story_5028_50280501_90_dialog_content = "あっ、うん…",
  ui_story_5028_50280501_91_dialog_content = "でも、分かったよ。\nやっぱりコイツのせいね！",
  ui_story_5028_50280501_92_dialog_content = "え？",
  ui_story_5028_50280501_93_dialog_content = "分からない？\nあたしの足についてるネバネバ。",
  ui_story_5028_50280501_94_dialog_content = "透明な生き物で、\n<color=#FFB400>ネバネバスライム</color>っていうの。",
  ui_story_5028_50280501_95_dialog_content = "モチモチ…",
  ui_story_5028_50280501_96_dialog_content = "普段は水の中で暮らしてるんだけど、\nたまに岸に上がって、呼吸しないと生きていけないの。",
  ui_story_5028_50280501_97_dialog_content = "ぱっと見透明だから、\nみんな気が付かずに転んじゃうってワケ。",
  ui_story_5028_50280501_98_dialog_content = "こんなに光霊がいる場所じゃ、\nネバネバスライムが暮らすのにはもう向かないから…",
  ui_story_5028_50280501_99_dialog_content = "みんなで巣から出てきて、\n別の所に引っ越すつもりなんじゃないかな。",
  ui_story_5028_50280501_100_dialog_content = "でも、足が遅いし、人に踏まれちゃうし…\nこのままじゃ、この子たちも観光客も、ケガしちゃう。",
  ui_story_5028_50280501_101_dialog_content = "（珍獣の話の時は、\n急にマジメになるなぁ…）",
  ui_story_5028_50280501_102_dialog_content = "あっ、そうか！師匠の試練って、\nそのスライムたちを無事に移住させることなんじゃない？",
  ui_story_5028_50280501_103_dialog_content = "たぶんね。人ごみではぐれちゃったネバネバスライムを\n全員見つけて、別の場所に移してあげないと！",
  ui_story_5028_50280501_104_dialog_content = "キャロ、その子と遊んでないで、手伝って！",
  ui_story_5028_50280501_105_dialog_content = "ルルル！",
  ui_story_5028_50280501_106_dialog_content = "ふぅ、これで最後の1匹だよね？",
  ui_story_5028_50280501_107_dialog_content = "モチモチ…",
  ui_story_5028_50280501_108_dialog_content = "うん、みんな同じ方向に向かってる。",
  ui_story_5028_50280501_109_dialog_content = "暮らしやすい海岸は自分たちで見つけるから、\nあたしたちは、それを見守ってあげればいいだけだよ。",
  ui_story_5028_50280501_110_dialog_content = "あ、ちょっと待って…あっちの方、暗鬼がいるみたいだ。\n回り道させられないかな？",
  ui_story_5028_50280501_111_dialog_content = "ムリね。ネバネバスライムって単純だから。\nでなきゃ、海岸で人に踏まれまくりなんてコトにならないでしょ？",
  ui_story_5028_50280501_112_dialog_content = "それに、ちょっとやそっとの暗鬼ぐらいで、\nあたしはもう逃げたりしない！",
  ui_story_5028_50280501_113_dialog_content = "このフィア様が、暗鬼なんて全部追い払ってあげる！",
  ui_story_5028_50280502_1_dialog_content = "<color=#e8d9bb>ザザーン…</color>",
  ui_story_5028_50280502_2_dialog_content = "静かな海岸だね。\nカモメの声さえほとんど聞こえないよ。",
  ui_story_5028_50280502_3_dialog_content = "ここならネバネバスライムたちも、\n安心して暮らせそうだ。",
  ui_story_5028_50280502_4_dialog_content = "モチモチ…モチモチ…",
  ui_story_5028_50280502_5_dialog_content = "次は気をつけるんだよ。\n人が増える前に逃げてね。",
  ui_story_5028_50280502_6_dialog_content = "逃げるって、別に観光客の人たちだって\n悪意があったわけじゃないでしょ…",
  ui_story_5028_50280502_7_dialog_content = "暗鬼の大量出現とか、環境の急な変化とかで、\n珍獣の住む場所はどんどん減ってるの。",
  ui_story_5028_50280502_8_dialog_content = "知ってる？実は光霊って、自分たちの知らないところで\n珍獣たちに守られてるんだよ。",
  ui_story_5028_50280502_9_dialog_content = "いろんな街の近くにも住んでて、実は一番最初に暗鬼を見つけて、\n誰より先に戦ってるのは珍獣ってことが多いの。",
  ui_story_5028_50280502_10_dialog_content = "それは初めて聞いたよ。",
  ui_story_5028_50280502_11_dialog_content = "とにかく、これでまた試練を1つクリアね！\n今日はいっぱい珍獣を助けられたよ！",
  ui_story_5028_50280502_12_dialog_content = "（あれ？足がネバネバする…？）",
  ui_story_5028_50280502_13_dialog_content = "モチモチ…",
  ui_story_5028_50280502_14_dialog_content = "え？前にこの近くに恐ろしい怪物が出たけど、\nみんな信じてくれなかったら、あたしの近くに残りたいって？",
  ui_story_5028_50280502_15_dialog_content = "えへへ…仕方ないなぁ…",
  ui_story_5028_50280502_16_dialog_content = "いいよ！みんなと一緒に、あたしの側にいなさい！",
  ui_story_5028_50280502_17_dialog_content = "PlayerName、ほらほら！\nまた新しい仲間が増えたよ！",
  ui_story_5028_50280502_18_dialog_content = "ル～！",
  ui_story_5028_50280502_19_dialog_content = "また？いつもそんなに珍獣に人気があるの？",
  ui_story_5028_50280502_20_dialog_content = "ハ～イ。",
  ui_story_5028_50280502_21_dialog_content = "トーゼンでしょ！あたしは未来の珍獣マスターだもん！\n珍獣全部とお友だちにならなきゃ！",
  ui_story_5028_50280502_22_dialog_content = "まぁ、数が多い時は、師匠に預けて世話してもらうけどね。\nあたしの側だと危険なこともあるし。",
  ui_story_5028_50280502_23_dialog_content = "はいはい…それじゃ、未来の珍獣マスターさん。\n試練を全部達成するまで、後どれくらいかかるの？",
  ui_story_5028_50280502_24_dialog_content = "ええと…ノートを見てみないと。",
  ui_story_5028_50280502_25_dialog_content = "よかった！あっ、いや、よくない！！",
  ui_story_5028_50280502_26_dialog_content = "ル…？",
  ui_story_5028_50280502_27_dialog_content = "え？",
  ui_story_5028_50280502_28_dialog_content = "試練は全部やり遂げたって言ってもいいけど、\n永遠にできないとも言えそう。",
  ui_story_5028_50280502_29_dialog_content = "どういうこと？",
  ui_story_5028_50280502_30_dialog_content = "ええとね…危険な試練は全部終わったの。",
  ui_story_5028_50280502_31_dialog_content = "でも、一番難しいのが…師匠の書いた『珍獣大百科』を全部暗記するって！\nそんなこと、いつできるのか見当もつかないよ！",
  ui_story_5028_50280502_32_dialog_content = "こんなのムリムリ！！\n1週間かけても、2ページ半しか覚えられてないのに！！",
  ui_story_5028_50280502_33_dialog_content = "ル…",
  ui_story_5028_50280502_34_dialog_content = "まぁ、そういうものは、\n口先や力ずくじゃ、解決できないね…",
  ui_story_5028_50280502_35_dialog_content = "記憶を刷り込むみたいなことは\n空の末裔の能力でもできないし…",
  ui_story_5028_50280502_36_dialog_content = "…ル！",
  ui_story_5028_50280502_37_dialog_content = "ううぅ…",
  ui_story_5028_50280502_38_dialog_content = "ルルルル！！ルルルル！！",
  ui_story_5028_50280502_39_dialog_content = "キャロ、何するの！？",
  ui_story_5028_50280502_40_dialog_content = "引っ張らないで、ノートが破れちゃう！",
  ui_story_5028_50280502_41_dialog_content = "ルルル！",
  ui_story_5028_50280502_42_dialog_content = "止めてってば――あっ！",
  ui_story_5028_50280502_43_dialog_content = "フィア、大丈夫！？",
  ui_story_5028_50280502_44_dialog_content = "キャロ！ケンカ売ってるの！？",
  ui_story_5028_50280502_45_dialog_content = "待って、キャロがノートをめくってる。",
  ui_story_5028_50280502_46_dialog_content = "え？",
  ui_story_5028_50280502_47_dialog_content = "ルルルル！！ルルルル！！",
  ui_story_5028_50280502_48_dialog_content = "このページ？ウサギ？",
  ui_story_5028_50280502_49_dialog_content = "ウサギ？",
  ui_story_5028_50280502_50_dialog_content = "――着いたよ。",
  ui_story_5028_50280502_51_dialog_content = "大金はたいて手に入れた手がかりで、ここ？",
  ui_story_5028_50280502_52_dialog_content = "影ノ街で長いこと名を知られたスモーキーさんも、\nヤキが回ったのかしらね？",
  ui_story_5028_50280502_53_dialog_content = "それとも、海で遊びのお誘い？\n悪いけど、水着は用意してないわ。",
  ui_story_5028_50280502_54_dialog_content = "あたしはもう着てるし。",
  ui_story_5028_50280502_55_dialog_content = "悪かったねー、水着じゃ身を守れないほど弱いから、\nあんたじゃ着れなくってさ。",
  ui_story_5028_50280502_56_dialog_content = "今日は厚着して、\nバカみたいに海辺で突っ立てれば？",
  ui_story_5028_50280502_57_dialog_content = "あたしへの嫉妬に燃えた顔ってヤツ、\n海から眺めといてあげるから。",
  ui_story_5028_50280502_58_dialog_content = "あなたね…！いいわ、空の末裔を探す前に、\nあなたを海の底へ道連れにしてあげる！",
  ui_story_5028_50280502_59_dialog_content = "空の末裔なんてどうでもいいじゃん？\nあたしはヒマつぶしで付き合ってるだけだし。",
  ui_story_5028_50280502_60_dialog_content = "アンタだって同じっしょ？",
  ui_story_5028_50280502_61_dialog_content = "私はそんなに適当な生き物じゃないわ！\n一緒にしないでほしいわね。",
  ui_story_5028_50280502_62_dialog_content = "今度こそ、この私が正々堂々\nあなたを超える絶好の機会だもの！",
  ui_story_5028_50280502_63_dialog_content = "水着なんか無くても、\n誇り高き賞金稼ぎのプロ精神で勝ってみせる！",
  ui_story_5028_50280502_64_dialog_content = "へえ、ずいぶん自身ありそーじゃん？\nでも、水着がなきゃ――",
  ui_story_5028_50280502_65_dialog_content = "いいな～、おいらも水着欲しい。",
  ui_story_5028_50280502_66_dialog_content = "そこの皆さん、こっちをご覧なすって――",
  ui_story_5028_50280502_67_dialog_content = "<color=#e8d9bb>カシャ！</color>",
  ui_story_5028_50280502_68_dialog_content = "レスター？",
  ui_story_5028_50280502_69_dialog_content = "おや、スモーキーさんでございやしたか。",
  ui_story_5028_50280502_70_dialog_content = "アンタ、どうしてここにいんの？\n旅行中っしょ？",
  ui_story_5028_50280502_71_dialog_content = "そうでござんすよ。そちらのお2人も\nどこかでお会いした気がござんすね。ここへは遊びで？",
  ui_story_5028_50280502_72_dialog_content = "それはそうと、今撮った記念写真でござんす。",
  ui_story_5028_50280502_73_dialog_content = "あっ、ありがと。",
  ui_story_5028_50280502_74_dialog_content = "…私にも見せて。",
  ui_story_5028_50280502_75_dialog_content = "ま、そんな感じ。ついでに誘拐だったか、\n行方不明だったかのダチを探してるとこ。",
  ui_story_5028_50280502_76_dialog_content = "空の末裔、アンタも知ってるっしょ？",
  ui_story_5028_50280502_77_dialog_content = "空の末裔さんがいなくなったんでござんすか？\nこの大陸でたった一匹の、あのダンナが？",
  ui_story_5028_50280502_78_dialog_content = "そ。1匹か1人か…ま、どうでもいいけど。\nとにかく、行方不明なんだってさ。",
  ui_story_5028_50280502_79_dialog_content = "さいでござんすか…\n旅先で注意しておきやすね。",
  ui_story_5028_50280502_80_dialog_content = "ダンナを見かけたら、\nそのまま捕まえておきやす。",
  ui_story_5028_50280601_1_dialog_content = "試練：『珍獣大百科』を暗記せよ",
  ui_story_5028_50280601_2_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5028_50280601_3_dialog_content = "<color=#e8d9bb>バン！バン！</color>",
  ui_story_5028_50280601_4_dialog_content = "もういい！やたらに撃つな！",
  ui_story_5028_50280601_5_dialog_content = "獲物が逃げちまうだろうが。",
  ui_story_5028_50280601_6_dialog_content = "チッ…あのガキ2人は見逃がすのか？",
  ui_story_5028_50280601_7_dialog_content = "追ってるヒマはねぇよ。<color=#FFB400>ゲイリー</color>親分に、\n<color=#FFB400>「ペコペコウサギ」</color>を届けるのが優先だ。",
  ui_story_5028_50280601_8_dialog_content = "親分を怒らせちまったら、\n俺たち、タダじゃ済まねぇぞ。",
  ui_story_5028_50280601_9_dialog_content = "うう…",
  ui_story_5028_50280601_10_dialog_content = "ハ、ハ…",
  ui_story_5028_50280601_11_dialog_content = "ハクション！！",
  ui_story_5028_50280601_12_dialog_content = "シーッ…",
  ui_story_5028_50280601_13_dialog_content = "もう行ったよ。",
  ui_story_5028_50280601_14_dialog_content = "ル…",
  ui_story_5028_50280601_15_dialog_content = "キャロが賢くて助かった…\n雪に覆われた森まで連れてきてくれたおかげで、隠れられたよ。",
  ui_story_5028_50280601_16_dialog_content = "ル～！",
  ui_story_5028_50280601_17_dialog_content = "…クシュン！",
  ui_story_5028_50280601_18_dialog_content = "ハクション！ハクション！",
  ui_story_5028_50280601_19_dialog_content = "大丈夫？これで鼻をかんで。",
  ui_story_5028_50280601_20_dialog_content = "ふぅ…ありがと。",
  ui_story_5028_50280601_21_dialog_content = "それで、ここは一体どこ？\n寒くて手足が固まりそう。",
  ui_story_5028_50280601_22_dialog_content = "ノートに書かれてた「ペコペコウサギ」を捕まえるのでもなかったら、\nこんな寒いところ、二度とごめんだよ。",
  ui_story_5028_50280601_23_dialog_content = "僕の上着を貸してあげるよ。\nそうだ、スカーフも予備が有ったっけ。",
  ui_story_5028_50280601_24_dialog_content = "いいよ…あたしが着ちゃったら、\n今度はあんたが持たないでしょ。",
  ui_story_5028_50280601_25_dialog_content = "これ、飲んで。",
  ui_story_5028_50280601_26_dialog_content = "え？",
  ui_story_5028_50280601_27_dialog_content = "これは、サンドワームパウダーとオイルと、\nそれからニチリンソウを調合した丸薬だよ。",
  ui_story_5028_50280601_28_dialog_content = "寒い所でも身体がホッカホカになるの。",
  ui_story_5028_50280601_29_dialog_content = "最近サンドワームパウダーが手に入らなくて、\nもう1粒しか残ってないけど…",
  ui_story_5028_50280601_30_dialog_content = "温かくなってきた気がする…\nでも、君はどうするの？",
  ui_story_5028_50280601_31_dialog_content = "フィアはネバネバスライムを体にくっつけて、\n出来るだけ温度を逃がさないようにしとく。",
  ui_story_5028_50280601_32_dialog_content = "モチモチ…",
  ui_story_5028_50280601_33_dialog_content = "あたしがもし倒れたら、\nあんたが担いで山を下りて、助けを呼べるでしょ。",
  ui_story_5028_50280601_34_dialog_content = "でも、あんたが倒れたら、\n逆はムリだし。",
  ui_story_5028_50280601_35_dialog_content = "分かったよ。\n万が一の時は、必ずそうする。",
  ui_story_5028_50280601_36_dialog_content = "でも…よく考えたら、あんたの貧弱な体じゃ、あまり頼りにならなそう。\nやっぱり吐き出して。キャロにあげるから。",
  ui_story_5028_50280601_37_dialog_content = "もう飲んじゃったよ！！",
  ui_story_5028_50280601_38_dialog_content = "アハハ、本当にさせるワケないでしょ？",
  ui_story_5028_50280601_39_dialog_content = "ル…？",
  ui_story_5028_50280601_40_dialog_content = "元気になったら、早く行こ。",
  ui_story_5028_50280601_41_dialog_content = "アイツらより先に「ペコペコウサギ」を見つけなきゃ…",
  ui_story_5028_50280601_42_dialog_content = "こんな場所までハンターがチームで来るなんて、\nそのウサギ、本当にすごく珍しい動物なんだね？",
  ui_story_5028_50280601_43_dialog_content = "きちんと訓練を受けてる人たちみたいだし、\n雇い主も、きっと大金を出してるんだろうね…",
  ui_story_5028_50280601_44_dialog_content = "フン、おバカさんがいくら集まったって、\nなんの意味もないよ。",
  ui_story_5028_50280601_45_dialog_content = "数を増やしたり、いい銃や猟犬をそろえたり、\n山のあちこちに落とし穴を掘ったり…全部ムダ。",
  ui_story_5028_50280601_46_dialog_content = "ペコペコウサギはずる賢いの。引っ掛からないよ。",
  ui_story_5028_50280601_47_dialog_content = "経験豊富なハンターがあれだけ集まっても無理なら、\n僕たちだけで本当に捕まえられるの？",
  ui_story_5028_50280601_48_dialog_content = "安心して！あたしは実戦経験豊富な\n珍獣マスターだもん！",
  ui_story_5028_50280601_49_dialog_content = "素手で簡単に捕まえられるよ。",
  ui_story_5028_50280601_50_dialog_content = "手がかじかんでなければね…！",
  ui_story_5028_50280601_51_dialog_content = "師匠のノートは見つかった？\n一緒に探そうか？",
  ui_story_5028_50280601_52_dialog_content = "大丈夫、もう見つけたから。",
  ui_story_5028_50280601_53_dialog_content = "ペコペコウサギは素早く、賢い。捕まえるのは非常に困難だ。\nしかし、本をかじることを好む習性があり…",
  ui_story_5028_50280601_54_dialog_content = "なるほど！\nじゃあ、本をエサにしておびき出せば…",
  ui_story_5028_50280601_55_dialog_content = "そんな誰でも思いつく方法で捕まると思ってるなら、\n手ぶらで帰ることになるよ？",
  ui_story_5028_50280601_56_dialog_content = "…今言ったことは忘れて。",
  ui_story_5028_50280601_57_dialog_content = "ペコペコウサギはずる賢いの。\n突然本が出て来たら、かえって警戒されちゃうよ。",
  ui_story_5028_50280601_58_dialog_content = "でも、好奇心を利用すればうまくいくかも。\n「隣の芝生は青く見える」とか言うでしょ。",
  ui_story_5028_50280601_59_dialog_content = "好奇心…そうだ、PlayerName。\nここ2日、何か本を読んでたでしょ。貸して！",
  ui_story_5028_50280601_60_dialog_content = "…『時々ボソっと日蝕語でデレる隣のアンキさん』？\n何これ？",
  ui_story_5028_50280601_61_dialog_content = "ずいぶん長いタイトルだね。",
  ui_story_5028_50280601_62_dialog_content = "ブドウ園のおじさんがくれたんだ。\n自分が出した本だって言ってたよ。",
  ui_story_5028_50280601_63_dialog_content = "サインもしてくれたんだ。\n何年かしたらいい値段で売れるだろうって言ってた。",
  ui_story_5028_50280601_64_dialog_content = "そうなの？ま、いいや。\nおかげで師匠のノートを使わなくて済むし。",
  ui_story_5028_50280601_65_dialog_content = "…はあ。",
  ui_story_5028_50280601_66_dialog_content = "なんだろう、そのため息で心の中にいるブドウ園のおじさんが\n深く傷ついたような気がする…",
  ui_story_5028_50280601_67_dialog_content = "さ、おしゃべりはここまで！\nアイツらに先を越されるワケにはいかないもん。",
  ui_story_5028_50280601_68_dialog_content = "あんたは隠れてて。\nあたしが本を読むから。",
  ui_story_5028_50280601_69_dialog_content = "ウサギが来たら、ボタンを押して。",
  ui_story_5028_50280601_70_dialog_content = "でも、そんなことしたら、\n君も一緒にアミにかかっちゃうよ？",
  ui_story_5028_50280601_71_dialog_content = "大丈夫だよ。\nペコペコウサギは咬んだりしないから。",
  ui_story_5028_50280601_72_dialog_content = "もし咬まれたら咬み返してやるもんね。",
  ui_story_5028_50280601_73_dialog_content = "<color=#e8d9bb>しばらくして</color>",
  ui_story_5028_50280601_74_dialog_content = "ペコ？",
  ui_story_5028_50280601_75_option_content = "フィアと感知をつなぐ",
  ui_story_5028_50280601_76_dialog_content = "何か来てるよ。\nフィア、落ち着いてね。",
  ui_story_5028_50280601_77_dialog_content = "分かったよ。\nあんたも、タイミングを逃さないでよね。",
  ui_story_5028_50280601_78_dialog_content = "ル…",
  ui_story_5028_50280601_79_dialog_content = "ペコペコ…",
  ui_story_5028_50280601_80_dialog_content = "（フフフ…そうそう、こっち…\n好奇心がシゲキされるでしょ…早く、来ちゃいなさい！）",
  ui_story_5028_50280601_81_dialog_content = "ペコ…",
  ui_story_5028_50280601_82_dialog_content = "ダメだ、警戒心が強い…ずっとアミの近くをとび回ってるだけで、\n内側に全然入ろうとしない。",
  ui_story_5028_50280601_83_dialog_content = "これじゃアミを下ろしても逃げられちゃう。\nでも、次のチャンスはいつになるか分からないし…",
  ui_story_5028_50280601_84_dialog_content = "仕方ないなぁ。あたしが飛びかかるから、\nPlayerNameはうまく合わせて。",
  ui_story_5028_50280601_85_dialog_content = "サッサと――",
  ui_story_5028_50280601_86_dialog_content = "ペコ？",
  ui_story_5028_50280601_87_dialog_content = "あたしに捕まりなさい！！",
  ui_story_5028_50280601_88_dialog_content = "ペコ！！",
  ui_story_5028_50280601_89_dialog_content = "今だ！！",
  ui_story_5028_50280601_90_dialog_content = "捕まえた！",
  ui_story_5028_50280601_91_dialog_content = "ペコペコペコペコ！？",
  ui_story_5028_50280601_92_dialog_content = "フィアが大声をあげたら、\nビックリして動きが止まっちゃったみたいだね。",
  ui_story_5028_50280601_93_dialog_content = "それでうまくいくなんて、素質があるって言うのか、\n動物を越える野生の本能って言うのか…",
  ui_story_5028_50280601_94_dialog_content = "ほめ言葉だと思っておいてあげるよ。\nぼーっとしてないで、さっさとここから出してくれる？",
  ui_story_5028_50280601_95_dialog_content = "ふふふ…これで最後の試練の達成に\n一歩近づいたよ。",
  ui_story_5028_50280601_96_dialog_content = "ペ…ペコ…",
  ui_story_5028_50280601_97_dialog_content = "ル～！",
  ui_story_5028_50280601_98_dialog_content = "このウサギがどんな役に立つの？",
  ui_story_5028_50280601_99_dialog_content = "ノートによると、ペコペコウサギは大量の本の内容を取り込んで、\nそれを全部誰かに移せるんだって。",
  ui_story_5028_50280601_100_dialog_content = "ワケが分からない生態だけど、もう驚かなくなってきた…\nで、具体的にはどうすればいいの？",
  ui_story_5028_50280601_101_dialog_content = "ええと…まずは移したい内容、\nつまり本を食べさせてあげないと。",
  ui_story_5028_50280601_102_dialog_content = "まぁ、珍獣とはいえ、\nそこは分からなくもないかな…",
  ui_story_5028_50280601_103_dialog_content = "それから？",
  ui_story_5028_50280601_104_dialog_content = "それから…適量の油を注いで温めて…\nみじん切りにしたショウガとニンニクを入れる…",
  ui_story_5028_50280601_105_dialog_content = "…？",
  ui_story_5028_50280601_106_dialog_content = "ペコ…！！",
  ui_story_5028_50280601_107_dialog_content = "ル！！",
  ui_story_5028_50280601_108_dialog_content = "砂糖少々を加え、きつね色になるまで炒め、\nそこに毛を抜いた…",
  ui_story_5028_50280601_109_dialog_content = "…待って。それ、角煮の作り方じゃ…？",
  ui_story_5028_50280601_110_dialog_content = "なお、蒸し焼きにしてもよい…\nって、いいワケないでしょ！あのダメ師匠！",
  ui_story_5028_50280601_111_dialog_content = "…足を1本だけ、とか…？\n効果があるかも…",
  ui_story_5028_50280601_112_dialog_content = "ペコペコペコペコ！？",
  ui_story_5028_50280601_113_dialog_content = "冗談でもやめて。\nペコペコウサギが怖がっちゃってるでしょ。",
  ui_story_5028_50280601_114_dialog_content = "…ちょっと待って。\nこの子、あたしたちに注意しろって言ってる。",
  ui_story_5028_50280601_115_dialog_content = "注意って、何に？\nハンターたちからは離れたはずだけど。",
  ui_story_5028_50280601_116_dialog_content = "ハンターじゃない…<color=#FFB400>暗鬼に注意しろ</color>って言ってる！",
  ui_story_5028_50280602_1_dialog_content = "まったく、しつこいヤツらだね。",
  ui_story_5028_50280602_2_dialog_content = "なんでどこに行っても暗鬼が出るの？\n珍獣マスターより、暗鬼マスターになる方が速いかもね。",
  ui_story_5028_50280602_3_dialog_content = "ウサギが教えてくれてよかったよ。\nでなかったら、包囲されてるところだった。",
  ui_story_5028_50280602_4_dialog_content = "ペコペコ～。",
  ui_story_5028_50280602_5_dialog_content = "これでなおさら、食べるわけにはいかなくなったね。\n試練はどうするの？",
  ui_story_5028_50280602_6_dialog_content = "他のやり方を考えるよ。自分の欲のために珍獣を傷つけるのは、\n珍獣マスターのするべきことじゃないもん。",
  ui_story_5028_50280602_7_dialog_content = "仮にそれで試練をクリアできなくなったとしても、\nあたしはそんなこと、絶対…",
  ui_story_5028_50280602_8_dialog_content = "うーん、でも、どうすれば…",
  ui_story_5028_50280602_9_dialog_content = "ペコ…",
  ui_story_5028_50280602_10_dialog_content = "ル…",
  ui_story_5028_50280602_11_dialog_content = "モチモチ…",
  ui_story_5028_50280602_12_dialog_content = "なぐさめてくれてるの？ありがと…",
  ui_story_5028_50280602_13_dialog_content = "ううん、他の方法…",
  ui_story_5028_50280602_14_dialog_content = "ウサギを傷つけずに、\n手伝ってもらえる方法は…",
  ui_story_5028_50280602_15_dialog_content = "ひらめいた！",
  ui_story_5028_50280602_16_dialog_content = "ペコペコウサギちゃん、\nあたしの完璧な計画を聞いてくれる？",
  ui_story_5028_50280602_17_dialog_content = "ペコ！",
  ui_story_5028_50280602_17X1_dialog_content = "きゃあ！",
  ui_story_5028_50280602_18_dialog_content = "喜んでスリスリしてるね。",
  ui_story_5028_50280602_19_dialog_content = "ふふふ！これがフィア様の\n恐るべきカリスマってこと！",
  ui_story_5028_50280602_19X1_dialog_content = "はいはい…で、どんな方法を思いついたの？",
  ui_story_5028_50280602_19X2_dialog_content = "他の人には難しいかもしれないけど、\nあたしにとっては簡単なことだよ。",
  ui_story_5028_50280602_19X3_dialog_content = "覚えてるでしょ？\nあたしは珍獣の鳴き声で言いたいことがわかるの。",
  ui_story_5028_50280602_19X4_dialog_content = "つまり、テストの時、ペコペコウサギを胸元とか、\nポケットの中とかに入れておいて…",
  ui_story_5028_50280602_19X5_dialog_content = "こっそり正解を教えてもらえばいいんだよ。",
  ui_story_5028_50280602_19X6_dialog_content = "そうすれば、暗記のテストなんか楽勝でしょ！\nあのダメ師匠、ギャフンと言わせてやる！",
  ui_story_5028_50280602_19X7_dialog_content = "そんなにうまく行くかな？\n難しいと思うけどなぁ。",
  ui_story_5028_50280602_20_dialog_content = "ペコペコ～！",
  ui_story_5028_50280602_20X1_dialog_content = "じゃあ、テストの時、ポケットの中に隠れて…",
  ui_story_5028_50280602_20X2_dialog_content = "こっそり正解を教えてもらってもいい？",
  ui_story_5028_50280602_20X3_dialog_content = "ペコペコ～！",
  ui_story_5028_50280602_20X4_dialog_content = "えへへ、よかった！",
  ui_story_5028_50280602_21_dialog_content = "喜んで助けてくれるって。\nあと、一緒に来てくれるって！",
  ui_story_5028_50280602_22_dialog_content = "ペコ～！",
  ui_story_5028_50280602_22X1_dialog_content = "これで試練もカンペキ！\n師匠のところへ戻れるよ！",
  ui_story_5028_50280602_23_dialog_content = "もうこれだけ珍獣を連れてるんだし、\n今さら1匹増えたところで問題なさそうだね。",
  ui_story_5028_50280602_24_dialog_content = "ヘヘ、PlayerNameもありがと。",
  ui_story_5028_50280602_25_dialog_content = "え…？ペコペコウサギちゃん、自分はラッキーなウサギだって？\n恐ろしい怪物に捕まった時も、無事に解放してもらった？",
  ui_story_5028_50280602_26_dialog_content = "へぇ～。じゃ、あたしたちの旅ももっとラッキーになるかもね。\nこれから、よろしくね！",
  ui_story_5028_50280602_27_dialog_content = "ペコ～！",
  ui_story_5028_50280602_28_dialog_content = "レビィ、突撃！",
  ui_story_5028_50280602_29_dialog_content = "<color=#e8d9bb>バン！バン！</color>",
  ui_story_5028_50280602_30_dialog_content = "燃やせ！マンティコア！",
  ui_story_5028_50280602_31_dialog_content = "に、逃げろ！\nコイツら、ヤベぇ！",
  ui_story_5028_50280602_32_dialog_content = "覚えてろよ！<color=#FFB400>ゲイリー親分</color>と\n<color=#FFB400>アイアン・ウィップ団</color>が、絶対に許さねえからな！",
  ui_story_5028_50280602_33_dialog_content = "逃げちゃった。",
  ui_story_5028_50280602_34_dialog_content = "空の末裔が見つからないどころか、\n敵意むき出しのハンターがいるなんて…",
  ui_story_5028_50280602_35_dialog_content = "何しに来てたのかしら？\nPlayerNameが巻き込まれた何かと関係が？",
  ui_story_5028_50280602_36_dialog_content = "チッ…1人とっ捕まえて吐かせりゃ良かった。",
  ui_story_5028_50280602_37_dialog_content = "あれれ、やっほ～！\nPlayerNameのお友達さんたちじゃない？",
  ui_story_5028_50280602_38_dialog_content = "あなたは…ローラ？\nどうしてここに？",
  ui_story_5028_50280602_39_dialog_content = "おつかいの途中で銃の音がしたから、\n何かあったのかと思って見に来たんだ！みんな、ケガはない？",
  ui_story_5028_50280602_40_dialog_content = "おいらたち、空の末裔を探してたんだけど、\nハンターがいて、いきなり攻撃してきたんだ。",
  ui_story_5028_50280602_41_dialog_content = "でも、ケガはしてないよ。\nハンターも、みんな逃げちゃった。",
  ui_story_5028_50280602_42_dialog_content = "空の末裔…ええええ？\nPlayerName、行方不明になっちゃったの？",
  ui_story_5028_50280602_43_dialog_content = "そういえば、ここに来る途中で、\nキャンプのあとを見かけたよ。何か手がかりがあるかも。",
  ui_story_5028_50280602_44_dialog_content = "案内したげるよ。\nおつかいは後回し！",
  ui_story_5028_50280602_45_dialog_content = "何だか、ツアー旅行でもしてる気分だわ…",
  ui_story_5028_50280602_46_dialog_content = "面白いじゃん？いろんな景色見て回んのも、\nついでに暗鬼とか光霊とか片付けんのも。",
  ui_story_5028_50280602_47_dialog_content = "まぁ、それはそうね。",
  ui_story_5028_50280701_1_dialog_content = "試練：誘惑に抗え",
  ui_story_5028_50280701_2_dialog_content = "真っ白い雲～元気な木～♪",
  ui_story_5028_50280701_3_dialog_content = "フィアと仲間たちがお出かけお出かけ～♪",
  ui_story_5028_50280701_4_dialog_content = "楽しい仲間、空の末裔も一緒～♪",
  ui_story_5028_50280701_5_dialog_content = "ルルル～♫",
  ui_story_5028_50280701_6_dialog_content = "楽しそうだね。",
  ui_story_5028_50280701_7_dialog_content = "えへへ、試練達成まで、あと一歩だもん！",
  ui_story_5028_50280701_8_dialog_content = "PlayerNameとキャロたちのおかげで、\nずいぶん順調に片付いたよ。",
  ui_story_5028_50280701_9_dialog_content = "僕も意外だったよ。",
  ui_story_5028_50280701_10_dialog_content = "本当のことを言うと、君はすぐにあきらめそうなタイプだし、\n長くは付き合わなくて済むだろうって思ってた。",
  ui_story_5028_50280701_11_dialog_content = "残念でした～！\n珍獣のことは、そう簡単にあきらめないもんね！",
  ui_story_5028_50280701_12_dialog_content = "もうちょっと腰が低ければもっといいんだけどね…",
  ui_story_5028_50280701_13_dialog_content = "それはダメ！あたしの個性だもん。\n個性を取ったらあたしの魅力が半減しちゃうでしょ！",
  ui_story_5028_50280701_14_dialog_content = "実にフィアらしいよ。それでこそ君だ。",
  ui_story_5028_50280701_15_dialog_content = "へへへ！",
  ui_story_5028_50280701_16_dialog_content = "（実際、フィアは態度のわりに、内心は優しい）",
  ui_story_5028_50280701_16X_dialog_content = "（動物たちも人の心が見通せるのか、\nそのことをよく分かってる）",
  ui_story_5028_50280701_17_dialog_content = "（動物たちは、単純だけど賢い。\n誠実で優しい人とウソツキで残酷な人を見抜けるんだ）",
  ui_story_5028_50280701_18_dialog_content = "（珍獣たちとフィアの仲が良いのは、\nフィアが善良で優しい子だっていう何よりの証拠だ）",
  ui_story_5028_50280701_19_dialog_content = "…ん？何か考え事？",
  ui_story_5028_50280701_20_dialog_content = "のど乾いてない？ほら、水筒。",
  ui_story_5028_50280701_21_dialog_content = "あと半日も歩けば師匠の家に着くから、\nもうひとがんばりだよ。",
  ui_story_5028_50280701_22_dialog_content = "大丈夫だよ。のどは乾いてない。",
  ui_story_5028_50280701_23_dialog_content = "君は独り立ちした後、\nどうするつもりなのかなって、考えてたんだ。",
  ui_story_5028_50280701_24_dialog_content = "う～ん…あちこちを旅行して、もっとたくさん珍獣と会って、記録するかな。\n師匠よりすごい本を書くの！",
  ui_story_5028_50280701_25_dialog_content = "君らしい計画だね…",
  ui_story_5028_50280701_26_dialog_content = "ヘヘヘ！そういうPlayerNameは、\nどうするつもり？",
  ui_story_5028_50280701_27_dialog_content = "まずは何とかして、\nドラゴライオンのことを解決しないとね…",
  ui_story_5028_50280701_28_dialog_content = "今後もあんな大きな竜にソラヴァンが\n追い回されるなら、たまったもんじゃないよ。",
  ui_story_5028_50280701_29_dialog_content = "安心して。フィアが何とかしてあげる。",
  ui_story_5028_50280701_30_dialog_content = "それに、そもそも繁殖期を過ぎれば、\nドラゴライオンが巨像を追いかけてくることもないと思うよ。",
  ui_story_5028_50280701_31_dialog_content = "心からそうであることを願うよ…",
  ui_story_5028_50280701_32_dialog_content = "ソラヴァン、ここしばらくはずっと上空で旋回し続けてるし、\n疲れきってるかもしれない…",
  ui_story_5028_50280701_33_dialog_content = "まぁまぁ、フィアの知識を信じなさい！",
  ui_story_5028_50280701_34_dialog_content = "ル～！",
  ui_story_5028_50280701_35_dialog_content = "はいはい…",
  ui_story_5028_50280701_36_dialog_content = "…ん？あれは何だろう？",
  ui_story_5028_50280701_37_dialog_content = "<color=#FFB400>神サマの像</color>みたいだよ？",
  ui_story_5028_50280701_38_dialog_content = "あんな神像、初めて見るなぁ。",
  ui_story_5028_50280701_39_dialog_content = "（この奇妙な感覚はなんだろう…\nどこか親近感と懐かしさを感じる気がする）",
  ui_story_5028_50280701_40_dialog_content = "ちょっとお祈りでもしていかない？\n試練が無事に終わりますようにって。",
  ui_story_5028_50280701_41_dialog_content = "いいんじゃない？\n別に害はなさそうだし。",
  ui_story_5028_50280701_42_dialog_content = "（像に近づけば近づくほど、妙な心地よさが強くなってくる。\n心地よすぎて、今にもめまいがしそうだ…）",
  ui_story_5028_50280701_43_dialog_content = "えーと、どこのどんな神様か知らないけど、\nどうか、あたしが無事に試練を達成できますよーに…",
  ui_story_5028_50280701_44_dialog_content = "あと、ドラゴライオンがちゃんとしたパートナーを見つけて、\nソラヴァンがPlayerNameの元へ帰れますよーに…",
  ui_story_5028_50280701_45_dialog_content = "それから、キャロが…",
  ui_story_5028_50280701_46_dialog_content = "キャロが…",
  ui_story_5028_50280701_47_dialog_content = "…",
  ui_story_5028_50280701_48_dialog_content = "あれ？あたし、どうしたの…？",
  ui_story_5028_50280701_49_dialog_content = "おめでとう！フィア！！",
  ui_story_5028_50280701_50_dialog_content = "試練は合格だ！！\n今日からお前が世界でいちばん偉大な、珍獣マスターだ！",
  ui_story_5028_50280701_51_dialog_content = "え？師匠？\nあたしが「世界でいちばん偉大」？",
  ui_story_5028_50280701_52_dialog_content = "そうそう、その通りでございます。\nささ、おかけください…",
  ui_story_5028_50280701_53_dialog_content = "フィア様の功績は、私の功績などはるかに超えています。\n珍獣に対する知識と理解で、あなたにかなう者はいないでしょう。",
  ui_story_5028_50280701_54_dialog_content = "あなたに比べたら、私なんて月とスッポンポンガメの差です。\nどうか、弟子にしてください！",
  ui_story_5028_50280701_55_dialog_content = "ヘヘヘ、それほどでもないよ～。\nでも、考えてあげてもいいかな～？",
  ui_story_5028_50280701_56_dialog_content = "フィア様！",
  ui_story_5028_50280701_57_dialog_content = "え？誰？",
  ui_story_5028_50280701_58_dialog_content = "あなた様の偉大な業績は大陸中に響き渡っております！\nそして私は、あなた様の才能をおしたいする者の1人です！",
  ui_story_5028_50280701_59_dialog_content = "あなた様をしたう者たちがすでに準備を整え、待機しております。\nどうか次の冒険のお手伝いをさせてください！",
  ui_story_5028_50280701_60_dialog_content = "フィア様！フィア様！フィア様！",
  ui_story_5028_50280701_61_dialog_content = "ええ？あたしのファンがこんなに？",
  ui_story_5028_50280701_62_dialog_content = "えへへへ！偉大なことを成し遂げると、\nたくさんの人がしたってくれるんだね～。",
  ui_story_5028_50280701_63_dialog_content = "…いや、ちょっと待って。\n誰かの事を忘れてる気がする…",
  ui_story_5028_50280701_64_dialog_content = "PlayerName！PlayerNameはどこ！？",
  ui_story_5028_50280701_65_dialog_content = "<color=#e8d9bb>その頃</color>",
  ui_story_5028_50280701_66_dialog_content = "あれ…？いつの間に巨像に戻ったんだっけ。\nこれは…",
  ui_story_5028_50280701_67_dialog_content = "すごい！！こんなにたくさん光珀がある！\nこれ、夢じゃないよね？",
  ui_story_5028_50280701_68_dialog_content = "どっちだっていいや！！この光珀全部使って、光霊を呼び出しちゃおう！\nとりあえず100回はレバーを引かないと！",
  ui_story_5028_50280701_69_dialog_content = "<color=#e8d9bb>バン！！</color>",
  ui_story_5028_50280701_70_dialog_content = "<color=#e8d9bb>ドカン、ガタン！！</color>",
  ui_story_5028_50280701_71_dialog_content = "ん？戦いの音？どこだろう…",
  ui_story_5028_50280701_72_dialog_content = "起きなさい――おバカさん！！",
  ui_story_5028_50280701_73_dialog_content = "誰かの声がした…？",
  ui_story_5028_50280701_74_dialog_content = "あ、あと、10回！これで最後にするから！\n引き終わったら行くから！",
  ui_story_5028_50280701_75_dialog_content = "グア！",
  ui_story_5028_50280701_76_dialog_content = "えっ！？",
  ui_story_5028_50280701_77_dialog_content = "あ、暗鬼？",
  ui_story_5028_50280701_78_dialog_content = "な、何が起こったの！？",
  ui_story_5028_50280701_79_dialog_content = "フィア？ここはどこ？どうして暗鬼がいるの？\nあと…君は誰？",
  ui_story_5028_50280701_80_dialog_content = "ムダ口を叩いてないで、戦いなさい。",
  ui_story_5028_50280701_81_dialog_content = "<size=45>グアア！！！</size>",
  ui_story_5028_50280701_82_dialog_content = "フィア！",
  ui_story_5028_50280701_83_dialog_content = "わ、分かった…PlayerName、キャロ！\nとにかく、行くよ！",
  ui_story_5028_50280702_1_dialog_content = "暗鬼が出るなんて…",
  ui_story_5028_50280702_2_dialog_content = "一体どういうこと？\nさっきまで、あたしたちは神サマの像に…",
  ui_story_5028_50280702_3_dialog_content = "そうだ、そしたら、ぼーっとして来て…\n自分が珍獣マスターになれた夢を見てた気がする…",
  ui_story_5028_50280702_4_dialog_content = "僕もだよ。確か、目の前に金色と紫色のものが\nたくさん並んで、キラキラ光る夢だったような…",
  ui_story_5028_50280702_5_dialog_content = "それから、知り合いの光霊に、\n別れたはずの光霊まで、僕の仲間になってくれて…",
  ui_story_5028_50280702_6_dialog_content = "あなたたちの白昼夢、なかなか面白いわね。",
  ui_story_5028_50280702_7_dialog_content = "さっき、神の像を拝んだって言ったかしら？",
  ui_story_5028_50280702_8_dialog_content = "そうだよ、それがどうかした？",
  ui_story_5028_50280702_9_dialog_content = "何の神かも分からないものに祈るなんて、\nたいした度胸ね。",
  ui_story_5028_50280702_10_dialog_content = "そんなだらしない有り様で珍獣たちを\n手なづけようなんて、妄想もいいところだわ。",
  ui_story_5028_50280702_11_dialog_content = "啓光には義務教育があるでしょ？\n今のうちにきちんと勉強して、マトモな仕事に就いた方がいいわ。",
  ui_story_5028_50280702_12_dialog_content = "何よ！？",
  ui_story_5028_50280702_13_dialog_content = "あんた一体誰！？\nいきなり出てきて、あたしをバカにするなんて！",
  ui_story_5028_50280702_14_dialog_content = "助けてくれたからって、\nヒドいこと言っていいってわけじゃないよ！！",
  ui_story_5028_50280702_15_dialog_content = "キャロ、オシオキ…",
  ui_story_5028_50280702_16_dialog_content = "…",
  ui_story_5028_50280702_17_dialog_content = "…キャロ？",
  ui_story_5028_50280702_18_dialog_content = "珍獣たちはここにはいないみたいだよ。\n感知もできない。",
  ui_story_5028_50280702_19_dialog_content = "おバカさんね。",
  ui_story_5028_50280702_20_dialog_content = "私が誰かなんて、教える義理もないわ。",
  ui_story_5028_50280702_21_dialog_content = "ただ、そんな子供のお遊びみたいな態度のまま、\n珍獣の専門家を目指すつもりなら…",
  ui_story_5028_50280702_22_dialog_content = "そんな！？キャロ、いなくなっちゃったの！？",
  ui_story_5028_50280702_23_dialog_content = "…今すぐあきらめたほうがいいわ。",
  ui_story_5028_50280702_24_dialog_content = "あの子たちはあなたのペットではないし、おままごとの相手でもないの。\n言うことを素直に聞くような、大人しい動物でもない。",
  ui_story_5028_50280702_25_dialog_content = "覚悟と精神力もなしに、泳ぎ切れる海じゃないわ。\n夢なかばでおぼれ死ぬのが関の山ね。",
  ui_story_5028_50280702_26_dialog_content = "キャロ…キャロ…！？",
  ui_story_5028_50280702_27_dialog_content = "自分だけじゃないわ。おままごとに付き合ってくれた「仲間」だって、\nみんな道連れになるでしょうね。",
  ui_story_5028_50280702_28_dialog_content = "あ、あんた…やっぱり、\nキャロの居場所を知ってるんでしょ！？",
  ui_story_5028_50280702_29_dialog_content = "お願い、教えて！\nみんなはどこにいるの？",
  ui_story_5028_50280702_30_dialog_content = "あなた、本当におバカさんね…\n私の言ったこと、まだ理解できていないのかしら――？",
  ui_story_5028_50280702_31_dialog_content = "辺りを見たけど、キャロたち、見当たらないね。\nあと、僕が持ってた、装備の入った荷物も…",
  ui_story_5028_50280702_32_dialog_content = "そんなものはどうでもいいの…！\nお願い！キャロたちがどこにいるのか教えて！！",
  ui_story_5028_50280702_33_dialog_content = "師匠から預かった、大事な仲間なの！\nちょっとでも知ってるなら、お願いだから教えて！",
  ui_story_5028_50280702_34_dialog_content = "…そのマヌケ面を見てると、気分が悪くなるわ。",
  ui_story_5028_50280702_35_dialog_content = "私はもう行くことにするけど、\nここにいたいなら、好きなだけ残ればいいわ。",
  ui_story_5028_50280702_36_dialog_content = "あなたが泣き終わるまで1日中、\n山のふもとで大人しく待っててくれたりはしないわよ。",
  ui_story_5028_50280702_37_dialog_content = "子どもって、これだから面倒臭いわ…",
  ui_story_5028_50280702_38_dialog_content = "フィア！",
  ui_story_5028_50280702_39_dialog_content = "うん！",
  ui_story_5028_50280702_40_dialog_content = "荷物と装備は後！\nとにかく、キャロたちを探しに行かないと！",
  ui_story_5028_50280702_41_dialog_content = "ちょっと待って…",
  ui_story_5028_50280702_42_dialog_content = "さっきの人、\n何か落として行ったみたいだよ？",
  ui_story_5028_50280702_43_dialog_content = "これは…野外探検に使うコンパスとか、\n必須の装備だよ。",
  ui_story_5028_50280702_44_dialog_content = "あたしの失くしたヤツじゃないけど、新しいモノみたい。\n予備用の装備、わざと置いていってくれたのかな？",
  ui_story_5028_50280702_45_dialog_content = "きついことを言ってたけど、\n本当はいい人なのかな…？",
  ui_story_5028_50280702_46_dialog_content = "うん…次に会った時は、\nちゃんとお礼言わないと。",
  ui_story_5028_50280702_47_dialog_content = "それにあの人、見たことある気がするんだよね…\nどこかで会ったことがあるのかも…",
  ui_story_5028_50280702_48_dialog_content = "キャロー！！",
  ui_story_5028_50280702_49_dialog_content = "ルルル！！",
  ui_story_5028_50280702_50_dialog_content = "モチモチ…",
  ui_story_5028_50280702_51_dialog_content = "ハイハ～イ。",
  ui_story_5028_50280702_52_dialog_content = "ペコ～！",
  ui_story_5028_50280702_53_dialog_content = "よかった、みんな神像の前で待っててくれたんだね。",
  ui_story_5028_50280702_54_dialog_content = "でも僕たち、なんで夢なんか見たんだろう？\nそれに、どうやってあの場所に…？",
  ui_story_5028_50280702_55_dialog_content = "ルルル！ルルル！",
  ui_story_5028_50280702_56_dialog_content = "この像が気になるの、キャロ？",
  ui_story_5028_50280702_57_dialog_content = "やっぱり、何かあるんだね？",
  ui_story_5028_50280702_58_dialog_content = "ホゥ…",
  ui_story_5028_50280702_59_dialog_content = "石像が動いた！？",
  ui_story_5028_50280702_60_dialog_content = "違う！これ、そもそも神サマの像なんかじゃない！",
  ui_story_5028_50280702_61_dialog_content = "<color=#FFB400>アリガタモドキドリ</color>！珍獣だよ！\nこんな所で会えるなんて思わなかったよ。",
  ui_story_5028_50280702_62_dialog_content = "絶滅寸前だって、師匠が言ってた。\nノートにもほとんど何も書かれてないよ。",
  ui_story_5028_50280702_63_dialog_content = "ええと…アリガタモドキドリは神像に化け、\n拝みに来た人々を眠らせる。",
  ui_story_5028_50280702_63X_dialog_content = "そして、寝ているスキに金目のモノを奪っていく…",
  ui_story_5028_50280702_64_dialog_content = "ホウ…ホウ…",
  ui_story_5028_50280702_65_dialog_content = "金目のモノ？奪って、どうするんだろう？",
  ui_story_5028_50280702_66_dialog_content = "たぶん、単に光るコインとかが好きなだけじゃない？\nそういう習性の動物なら、結構いるよ。",
  ui_story_5028_50280702_67_dialog_content = "ホゥ！！",
  ui_story_5028_50280702_68_dialog_content = "大変だ、逃げた！",
  ui_story_5028_50280702_69_dialog_content = "ルルル！",
  ui_story_5028_50280702_70_dialog_content = "ナイス、キャロ！\nしっかり捕まえて！逃がしちゃダメだよ！",
  ui_story_5028_50280702_71_dialog_content = "捕まえた！！",
  ui_story_5028_50280702_72_dialog_content = "ホゥ！？",
  ui_story_5028_50280702_73_option_content = "アリガタモドキドリを力いっぱい振る",
  ui_story_5028_50280702_74_dialog_content = "あたしたちの荷物が出て来た！",
  ui_story_5028_50280702_75_option_content = "もう少し振ってみる",
  ui_story_5028_50280702_76_dialog_content = "ホウ！？",
  ui_story_5028_50280702_77_dialog_content = "<color=#e8d9bb>振り続けることしばらく…</color>",
  ui_story_5028_50280702_78_dialog_content = "ホゥ…",
  ui_story_5028_50280702_79_dialog_content = "どんどん出てくる！これ、啓光の缶詰でしょ、白夜コインに…\nそれから、北境の宝石！？",
  ui_story_5028_50280702_80_dialog_content = "コイツ、そうとうたくさんの人を困らせてるね。\n他の人のものは、ここに置いて行こっと。",
  ui_story_5028_50280702_81_dialog_content = "ヘヘヘ…あんたには選ぶチャンスをあげる。",
  ui_story_5028_50280702_82_dialog_content = "ホゥ？",
  ui_story_5028_50280702_83_dialog_content = "ここで今すぐオシオキされたい？",
  ui_story_5028_50280702_84_dialog_content = "ホゥホゥホゥ！？",
  ui_story_5028_50280702_85_dialog_content = "それとも大人しく、あたしに付いてくる？",
  ui_story_5028_50280702_86_dialog_content = "ホゥ…",
  ui_story_5028_50280702_87_dialog_content = "ホゥ！",
  ui_story_5028_50280702_88_dialog_content = "えヘヘ！じゃあ、大人しく付いてきなさい！",
  ui_story_5028_50280702_89_dialog_content = "フィアはこれから師匠に会いに行くんだよ。\nあたしの力、見せつけてやるんだから！",
  ui_story_5028_50280702_90_dialog_content = "ぐぅ…",
  ui_story_5028_50280702_91_dialog_content = "すぅ…",
  ui_story_5028_50280702_92_dialog_content = "ふぅ…グラム、おかわり！",
  ui_story_5028_50280702_93_dialog_content = "…あれ？おいら、寝ちゃってた？",
  ui_story_5028_50280702_94_dialog_content = "みんな、起きて！",
  ui_story_5028_50280702_95_dialog_content = "これ、ワナだ！！",
  ui_story_5028_50280702_96_dialog_content = "ふわぁ…ああ…あたしたち、\nあのボロっちい石像にダマされたってコトか。",
  ui_story_5028_50280702_97_dialog_content = "だから、止めとけって言ったじゃん。",
  ui_story_5028_50280702_98_dialog_content = "だいたい「良縁に恵まれますように」って何？\nいい年こいて、迷信にハマってんの？",
  ui_story_5028_50280702_99_dialog_content = "おかげであたしたち、スッカラカンじゃん。",
  ui_story_5028_50280702_100_dialog_content = "わ、私はただ、あなたに勝てるようにって\nお願いしただけよ！",
  ui_story_5028_50280702_101_dialog_content = "イヤミを言うヒマがあるなら、\nなくなったものをさっさと探しなさい！",
  ui_story_5028_50280702_102_dialog_content = "…それで、あの憎たらしい石像は？",
  ui_story_5028_50280702_103_dialog_content = "消えた？",
  ui_story_5028_50280702_104_dialog_content = "…いえ、何かあるわね。",
  ui_story_5028_50280702_105_dialog_content = "あら？スモーキー、あなたが使ってた、\nエレキギターのピックじゃない？",
  ui_story_5028_50280702_106_dialog_content = "ん？マジだ。\nこれ、ビンのフタ開けるのにちょうどいいんだよね。",
  ui_story_5028_50280702_107_dialog_content = "他のものは？",
  ui_story_5028_50280702_108_dialog_content = "神サマはいなくなっちゃったけど、\nモノはあるよ。",
  ui_story_5028_50280702_109_dialog_content = "あと、空の末裔の匂いがする。",
  ui_story_5028_50280801_1_dialog_content = "ダメ師匠、戻ったよ！",
  ui_story_5028_50280801_2_dialog_content = "ワケの分からない試練、\n全部やり遂げて来たんだから！！",
  ui_story_5028_50280801_X2_dialog_content = "でも、キャロがぜんぜん\n進化しないみたいなんだけど？",
  ui_story_5028_50280801_3_dialog_content = "お邪魔しま――",
  ui_story_5028_50280801_4_dialog_content = "（うっ、汚い！！）",
  ui_story_5028_50280801_5_dialog_content = "（本があちこち積み上がってるし…\nだらしない人なのかな）",
  ui_story_5028_50280801_6_dialog_content = "フィア、これで卒業できるんでしょ？\n師匠？ダメ師匠？？",
  ui_story_5028_50280801_7_dialog_content = "どういうこと？\n部屋もメチャクチャなんだけど！",
  ui_story_5028_50280801_8_dialog_content = "えっ…ここって、\nいつも散らかってるわけじゃないの？",
  ui_story_5028_50280801_9_dialog_content = "ううん？ダメ師匠の家はいつも散らかってるけど、\nだいたい散らかり方が決まってるの。",
  ui_story_5028_50280801_10_dialog_content = "完全にバラバラに物が置かれてるワケじゃなくて、\n本人なりに整頓してるんだよ。",
  ui_story_5028_50280801_11_dialog_content = "例えば、同じ分野の本は\n同じ山に放りこむんだ。",
  ui_story_5028_50280801_12_dialog_content = "あと、変なクセがあって…読みかけは開いたまま、一番上に置くの。\nそのせいで余計に散らかって見えるんだけど。",
  ui_story_5028_50280801_13_dialog_content = "ほら、ここの本の山、昆虫の本ばっかりでしょ？\nでも、上の2冊が、水生動物の本なの。",
  ui_story_5028_50280801_14_dialog_content = "頼りなくてどうしようもない中年ハゲ師匠だけど、\n本をメチャクチャに置いたりは絶対しない！！",
  ui_story_5028_50280801_15_dialog_content = "って、ことは…\n師匠以外の人が本をいじったってこと？",
  ui_story_5028_50280801_16_dialog_content = "たぶん。でも、今一番大事なのは、\n師匠を見つけることだよ！",
  ui_story_5028_50280801_17_dialog_content = "ダメ師匠、どこ？\n早く出てきなさい！",
  ui_story_5028_50280801_18_dialog_content = "<size=45>ねえったら――！！</size>",
  ui_story_5028_50280801_19_option_content = "ヴィックさん！",
  ui_story_5028_50280801_20_dialog_content = "…",
  ui_story_5028_50280801_21_dialog_content = "…いないみたいだね。",
  ui_story_5028_50280801_22_dialog_content = "机の引き出しがきちんとしまってない。イスの場所も違う。\nあたしには触らせようとしない収蔵棚の扉も開いてる…",
  ui_story_5028_50280801_23_dialog_content = "この部屋を離れた時、\nかなりあわててたってことかな？",
  ui_story_5028_50280801_24_dialog_content = "部屋もヘンに散らかってる。\nまさか…",
  ui_story_5028_50280801_25_dialog_content = "うん…可能性はあるよ。\nヴィックさんに何か…",
  ui_story_5028_50280801_26_dialog_content = "あたしにサギ師だってバレるのが怖くて、\n戻ってくる前に逃げたんだ！！",
  ui_story_5028_50280801_27_dialog_content = "へっ？",
  ui_story_5028_50280801_28_dialog_content = "きっとそう！！",
  ui_story_5028_50280801_29_dialog_content = "誰かに誘拐されたとか、\n考えないの？",
  ui_story_5028_50280801_30_dialog_content = "えっ！？",
  ui_story_5028_50280801_31_dialog_content = "…オッホン！\nそ、それぐらいとっくに思いついてたよ！",
  ui_story_5028_50280801_32_dialog_content = "…でも、師匠みたいな人を誘拐するヤツなんて、\nフツーいないでしょ…？",
  ui_story_5028_50280801_33_dialog_content = "何一つまともに出来ないし、\n大酒のみで、ポケットには白夜コイン半分だって入ってないし…",
  ui_story_5028_50280801_34_dialog_content = "一応君の師匠なんだから、\nそこまで言わなくても…",
  ui_story_5028_50280801_35_dialog_content = "とにかく、どうする？",
  ui_story_5028_50280801_36_dialog_content = "師匠がいないんじゃ、\nあたしが珍獣マスターとして卒業もできないでしょ。",
  ui_story_5028_50280801_37_dialog_content = "どういうことでも、まず師匠を見つけないと。",
  ui_story_5028_50280801_38_dialog_content = "じゃあ、まずは近くで手がかりを探そう。\n足取りが分かるかもしれない。",
  ui_story_5028_50280801_39_dialog_content = "フン…本当に世話が焼ける師匠なんだから。",
  ui_story_5028_50280801_40_dialog_content = "手がかりちゃ～ん！\n出てきなさい！",
  ui_story_5028_50280801_41_dialog_content = "<color=#e8d9bb>ガタン！</color>",
  ui_story_5028_50280801_42_dialog_content = "<color=#e8d9bb>パリン！ガチャン！！！</color>",
  ui_story_5028_50280801_43_dialog_content = "ストップストップ、止めて！",
  ui_story_5028_50280801_44_dialog_content = "それのどこが手がかり探しなの！？\n現場を荒らしてるだけだよ！！",
  ui_story_5028_50280801_45_dialog_content = "さ、探してる最中に、\nうっかり物を壊しちゃっただけ！",
  ui_story_5028_50280801_46_dialog_content = "そんな探し方じゃ、\nそのうち家ごと壊れちゃうよ…",
  ui_story_5028_50280801_47_dialog_content = "そこまで乱暴じゃないよ！",
  ui_story_5028_50280801_48_dialog_content = "ここは僕がさがすね…",
  ui_story_5028_50280801_49_dialog_content = "家ごと無くなっちゃわないうちに…",
  ui_story_5028_50280801_50_dialog_content = "どういうことよ！？",
  ui_story_5028_50280801_51_dialog_content = "とにかく、また一から調べなおさないと。",
  ui_story_5028_50280801_52_dialog_content = "どこから手をつけようかな？",
  ui_story_5028_50280801_53_option_content = "机のあたりを調べる",
  ui_story_5028_50280801_54_dialog_content = "机の引き出しが全部開けられてるよ。\n中身もメチャクチャにかき回されてる…",
  ui_story_5028_50280801_55_dialog_content = "ダメ師匠、いつもテキトーに引き出しに物をしまってるけど、\n引き出しごとに分類はしてるんだ。",
  ui_story_5028_50280801_56_dialog_content = "この空の引き出しには何が入ってたの？",
  ui_story_5028_50280801_57_dialog_content = "ええと…確か、珍獣について書いてある原稿だよ。",
  ui_story_5028_50280801_58_dialog_content = "師匠がキャロをあたしに預けてくれた時、\nしばらくそれを見て決めてたから、覚えてる。",
  ui_story_5028_50280801_59_dialog_content = "でも、それがなくなってる…",
  ui_story_5028_50280801_60_dialog_content = "待って。机の下に何かメモがあるよ？",
  ui_story_5028_50280801_61_dialog_content = "見せて！",
  ui_story_5028_50280801_62_dialog_content = "丸が1つ、その中にバツが1つ…",
  ui_story_5028_50280801_63_dialog_content = "あわてて書いたみたい…インクが乾ききってないから、\nまだ時間がそんなに経ってない！",
  ui_story_5028_50280801_64_dialog_content = "暗号か何か？",
  ui_story_5028_50280801_65_dialog_content = "分かんない…",
  ui_story_5028_50280801_66_option_content = "本棚の近くを調べる",
  ui_story_5028_50280801_67_dialog_content = "本棚はきれいに整頓されたままだよ。",
  ui_story_5028_50280801_68_dialog_content = "師匠、ここの本はあまり読まないし、\n掃除もしないから、ホコリが積もっちゃってるけど。",
  ui_story_5028_50280801_69_dialog_content = "でも、一番上のあの本、ホコリが積もってないよ。\nってことは、それを読んでたってことになる。",
  ui_story_5028_50280801_70_dialog_content = "何の本だろう…",
  ui_story_5028_50280801_71_dialog_content = "と、届かない！",
  ui_story_5028_50280801_72_dialog_content = "プッ…",
  ui_story_5028_50280801_73_dialog_content = "笑わないで！",
  ui_story_5028_50280801_74_dialog_content = "PlayerName！\nあんたなら届くでしょ！さっさと取って！",
  ui_story_5028_50280801_75_dialog_content = "よいしょ…",
  ui_story_5028_50280801_76_dialog_content = "ん？この本、写真が挟まれてる。",
  ui_story_5028_50280801_77_dialog_content = "写真に写ってるのは師匠だね。\nでも、もう半分が破り捨てられちゃってる…",
  ui_story_5028_50280801_78_dialog_content = "ずっと持ってたってことは、\nたぶん大事なもの？",
  ui_story_5028_50280801_79_dialog_content = "もう1人が気になるな…\n一体誰なんだろう？",
  ui_story_5028_50280801_80_dialog_content = "足がしびれて来るほど探したけど、\n見つかった手がかりは、これだけかな…",
  ui_story_5028_50280801_81_dialog_content = "どうしよう？",
  ui_story_5028_50280801_82_dialog_content = "…",
  ui_story_5028_50280801_83_dialog_content = "…ねぇ、フィア…",
  ui_story_5028_50280801_84_dialog_content = "何か、寒気がしない？",
  ui_story_5028_50280801_85_dialog_content = "た、確かに…",
  ui_story_5028_50280801_86_dialog_content = "あなたたち…",
  ui_story_5028_50280801_87_dialog_content = "うっ…！！！",
  ui_story_5028_50280801_88_dialog_content = "あっ、あんたは…！",
  ui_story_5028_50280801_89_dialog_content = "泥棒なら、金目の物だけさっさと探して、逃げればよかったでしょうに。\nまあ、ここには大したものないと思うけど。",
  ui_story_5028_50280801_90_dialog_content = "でも、部屋を荒らしたのは、許せないわね。",
  ui_story_5028_50280801_91_dialog_content = "バラバラの本を分類して元の場所に戻すのって、\nけっこう面倒なのよ。",
  ui_story_5028_50280801_92_dialog_content = "収蔵棚の扉も開きっぱなしね。収蔵品が全部ホコリを被ってるし、\nきれいにするだけで、少なくとも数日はかかるわ。",
  ui_story_5028_50280801_93_dialog_content = "何より腹立たしいのは…私が何年も時間をかけて整理した、\n珍獣の分布図と貴重な原稿がみんな、失くなっていること…",
  ui_story_5028_50280801_94_dialog_content = "…この流れはまずい！",
  ui_story_5028_50280801_95_dialog_content = "あの…ちょっと落ち着いて聞いてもらえるかな…",
  ui_story_5028_50280801_96_dialog_content = "僕たちは――",
  ui_story_5028_50280801_97_dialog_content = "弁償する？ムリよ。",
  ui_story_5028_50280801_98_dialog_content = "貴重な資料に値段はつかないの。\n弁償なんて出来ないのよ。",
  ui_story_5028_50280801_99_dialog_content = "待って！僕たちがやったんじゃない！",
  ui_story_5028_50280801_100_dialog_content = "そうだよ！あたしたちが戻ってきた時には、\n師匠はもういなかったし、部屋の中もメチャクチャだったの！",
  ui_story_5028_50280801_101_dialog_content = "…手がかりを探してる時に、\nうっかりイスと花ビンとグラスを壊しちゃったけど…",
  ui_story_5028_50280801_102_dialog_content = "余計なことは言わないで！？",
  ui_story_5028_50280801_103_dialog_content = "この状況でしらを切るつもり？\n時間のムダよ。",
  ui_story_5028_50280801_104_dialog_content = "無害な珍獣好きだとばかり思っていたわ。\nこんなことをしでかすなんてね。",
  ui_story_5028_50280801_105_dialog_content = "おとなしく、罪を償いなさい。",
  ui_story_5028_50280801_110_dialog_content = "ちょっと、話を聞いてる！？\nあたしたちじゃないって言ってるでしょ！",
  ui_story_5028_50280801_112_dialog_content = "わわわ！？",
  ui_story_5028_50280801_113_dialog_content = "何するの！？\nいきなり手を出してくるなんて！",
  ui_story_5028_50280801_114_dialog_content = "私だって乱暴なことはしたくないわ。\n指とか触手を動かすのだって、疲れるもの。",
  ui_story_5028_50280801_X114_dialog_content = "だから、素直に白状しなさい。",
  ui_story_5028_50280801_115_dialog_content = "本当に僕たちじゃ――",
  ui_story_5028_50280801_116_dialog_content = "うわっ…！！！",
  ui_story_5028_50280801_117_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_5028_50280801_118_dialog_content = "しょ、触手を避けたら、\n地面に大きな穴が…",
  ui_story_5028_50280801_119_dialog_content = "まともに食らってたら、\n命が危なかった…！",
  ui_story_5028_50280801_120_dialog_content = "そうよ、ものすごく痛いでしょうね。",
  ui_story_5028_50280801_121_dialog_content = "攻撃を止めて！\n僕たちは泥棒じゃない！",
  ui_story_5028_50280801_122_dialog_content = "ただ、失踪したヴィックさんの手がかりを\n探してただけなんだ！",
  ui_story_5028_50280801_123_dialog_content = "あの人が失踪？\nあなたたちじゃないとしたら、一体誰のしわざ？",
  ui_story_5028_50280801_124_dialog_content = "あたしたちだって知らないよ…",
  ui_story_5028_50280801_125_dialog_content = "でも、手がかりはあったの！",
  ui_story_5028_50280801_126_dialog_content = "手がかり？探すのも面倒だし、推理なんてもっと面倒だけど…\n一応聞いてあげてもいいわ。",
  ui_story_5028_50280801_127_dialog_content = "一体何を見つけたか、話してみなさい。",
  ui_story_5028_50280801_128_dialog_content = "師匠、中にバツを描いたマルが描かれた紙を置いて行ってるの。\nしかも、最近のもののはず！",
  ui_story_5028_50280801_129_dialog_content = "あと、この写真が本の中に挟まってたんだ。",
  ui_story_5028_50280801_130_dialog_content = "待ちなさい。\nあなた、ヴィックのことを「師匠」と呼んだ？",
  ui_story_5028_50280801_131_dialog_content = "そうだよ？",
  ui_story_5028_50280801_132_dialog_content = "あたし、師匠についてしばらくになるの。\n今は師匠から言われた試練をやり遂げて、もうすぐ卒業するところ！",
  ui_story_5028_50280801_133_dialog_content = "キャロが証拠だよ！\nダメ師匠から面倒見ろって譲られたんだ。",
  ui_story_5028_50280801_134_dialog_content = "…あれ、キャロは？",
  ui_story_5028_50280801_135_dialog_content = "ル？ルルル…",
  ui_story_5028_50280801_136_dialog_content = "そんなとこにいたの？\n本の山は寝床じゃないの、早く出て来なさい！",
  ui_story_5028_50280801_137_dialog_content = "確かに、あのキャロね。\nあなたにも慣れている…",
  ui_story_5028_50280801_138_dialog_content = "珍獣が信じているなら、\n私があなたを疑う理由もないわ。",
  ui_story_5028_50280801_139_dialog_content = "やっと信じてくれた…",
  ui_story_5028_50280801_140_dialog_content = "はぁ…どうやら、私が珍獣探索で空けてる間に、\nまた面倒ごとを起こしたみたいね。",
  ui_story_5028_50280801_141_dialog_content = "子どもの世話なんて、一番面倒だわ…",
  ui_story_5028_50280801_142_dialog_content = "あたし、もう子供じゃないもん！",
  ui_story_5028_50280801_143_dialog_content = "あんた、一体誰？\n師匠のこと、よく知ってるみたいだけど…",
  ui_story_5028_50280801_144_dialog_content = "私が誰か？\nそうね、私、誰なのかしら…",
  ui_story_5028_50280801_145_dialog_content = "複雑すぎて、どういう関係だったか、\n思い出すだけでも疲れるわ…",
  ui_story_5028_50280801_146_dialog_content = "ただ、あの人が師匠だというなら、\n私はあなたの姉弟子にあたるわね。",
  ui_story_5028_50280801_147_dialog_content = "私は、<color=#FFB400>シーラ</color>。",
  ui_story_5028_50280801_148_dialog_content = "シーラ",
  ui_story_5028_50280801_X148_dialog_content = "21歳",
  ui_story_5028_50280801_X149_dialog_content = "謎のタコ女",
  ui_story_5028_50280801_149_dialog_content = "姉弟子！？そんな人がいるって、\n師匠から聞いたこともないよ。",
  ui_story_5028_50280801_150_dialog_content = "あの人はいつだってそう。\n物事をきちんと説明しないの。",
  ui_story_5028_50280801_151_dialog_content = "時どき、私も分からなくなるわ。教えてくれたことと\n私に隠してること、一体どちらが多いのか、って。",
  ui_story_5028_50280801_152_dialog_content = "あの人と一緒にいると、\n本当に疲れるわ。",
  ui_story_5028_50280801_153_dialog_content = "大変だね。",
  ui_story_5028_50280801_154_dialog_content = "まぁ、もう慣れたから。",
  ui_story_5028_50280801_155_dialog_content = "本題に戻りましょう。\nこの写真のことだけど、私にも分からないわね。",
  ui_story_5028_50280801_156_dialog_content = "昔、何か話してくれていたかもしれないけど、記憶にないの。",
  ui_story_5028_50280801_157_dialog_content = "え？記憶力は良さそうなのに。",
  ui_story_5028_50280801_158_dialog_content = "いろんな種類の珍獣の習性とか特徴とか、\n全部覚えてるんでしょ？",
  ui_story_5028_50280801_159_dialog_content = "珍獣以外のことなんて、面倒で覚えてられないわ。",
  ui_story_5028_50280801_160_dialog_content = "ええ…？",
  ui_story_5028_50280801_161_dialog_content = "でも、記号の方は分かるわね。",
  ui_story_5028_50280801_162_dialog_content = "暗号よ。誘拐されたみたいね。",
  ui_story_5028_50280801_163_dialog_content = "このあたりは治安が悪いから…\n時どきこうやって暗号を残して、私が助けなきゃいけなくなるのよ。",
  ui_story_5028_50280801_164_dialog_content = "やっぱり、誘拐されてたんだ！",
  ui_story_5028_50280801_165_dialog_content = "た、たいへん…\nしばらくしたら、脅迫状とかが届くのかな？",
  ui_story_5028_50280801_166_dialog_content = "「師匠を助けたければ、1000万白夜コイン用意しろ」\nなんて言われたって、あたしには払えないよ…",
  ui_story_5028_50280801_167_dialog_content = "もし師匠が殺されちゃったら、\nあたし、永遠に卒業できなくなっちゃう！",
  ui_story_5028_50280801_168_dialog_content = "そこの心配！？",
  ui_story_5028_50280801_169_dialog_content = "でも、少しおかしいわね…",
  ui_story_5028_50280801_170_dialog_content = "この辺で強盗は珍しくもないけど、\nあの人はド貧乏の一文無しよ。",
  ui_story_5028_50280801_171_dialog_content = "だから、いつも騒ぐだけ騒いで、強盗が諦めるの。\n最悪の場合でも、せいぜいあの人が殴られるぐらいね。",
  ui_story_5028_50280801_172_dialog_content = "だけど今回は、誘拐された…？",
  ui_story_5028_50280801_173_dialog_content = "どうして、何の得にもならないことをするのかしら？",
  ui_story_5028_50280801_174_dialog_content = "誘拐したところで、食べ物と水のムダよ。\n値打ちのあるものなんて一切吐き出さないわ。",
  ui_story_5028_50280801_175_dialog_content = "…誘拐犯を哀れむべきか、\n君たちの師匠を哀れむべきか…",
  ui_story_5028_50280801_176_dialog_content = "まずはこんな面倒ごとに巻き込まれた\n自分を哀れんだら？",
  ui_story_5028_50280801_177_dialog_content = "な、なるほど…",
  ui_story_5028_50280801_178_dialog_content = "一体誰がそんなことを…\nまさか…",
  ui_story_5028_50280801_179_dialog_content = "…マズいわ。",
  ui_story_5028_50280801_180_dialog_content = "え！？ちょっと待ってよ！！",
  ui_story_5028_50280801_181_dialog_content = "誘拐犯に心当たりあるの！？\nねえってば！！！",
  ui_story_5028_50280801_182_dialog_content = "あっという間に姿が見えなくなっちゃった…",
  ui_story_5028_50280801_183_dialog_content = "ダメ師匠は失踪するし、\nセンパイも急にどこか行っちゃうし…",
  ui_story_5028_50280801_184_dialog_content = "2人そろって、何なのもう！\nなんできちんと説明してくれないの！？",
  ui_story_5028_50280801_185_dialog_content = "まずはシーラに追いつこうか。",
  ui_story_5028_50280801_186_dialog_content = "街の方へ行ったみたいだ。\n僕たちも追いかけよう。",
  ui_story_5028_50280801_187_dialog_content = "街なら人が多いから、\n誰かが姿を見るはず。",
  ui_story_5028_50280801_188_dialog_content = "うん！",
  ui_story_5028_50280901_1_dialog_content = "すみません、白い髪の、タコの足が生えた女性を\n見かけませんでしたか？",
  ui_story_5028_50280901_4_dialog_content = "あれ、フィア？",
  ui_story_5028_50280901_5_dialog_content = "一緒にいるのは誰？",
  ui_story_5028_50280901_6_dialog_content = "あっ、新聞売り君？",
  ui_story_5028_50280901_7_dialog_content = "こっちはPlayerName。\n「珍獣マスター」であるあたしの相棒！",
  ui_story_5028_50280901_8_dialog_content = "あたしたち、人を探してるの。\n何か手がかりない？",
  ui_story_5028_50280901_12_dialog_content = "女の人のことは分からないけど、\nフィアの師匠、たぶんマズいことになってるよ！",
  ui_story_5028_50280901_13_dialog_content = "師匠が失踪したことはあたしも知ってるよ。\n本当はそっちを探してるところなの。",
  ui_story_5028_50280901_14_dialog_content = "やっぱり…",
  ui_story_5028_50280901_15_dialog_content = "ちょっと前に、フィアの師匠が\n背の高い男にさらわれるところを見たんだ。",
  ui_story_5028_50280901_16_dialog_content = "シャドウマスターの部下の人には伝えたんだけど、\n何かしてくれるかどうかは、分かんない…",
  ui_story_5028_50280901_17_dialog_content = "どんな男の人だったか、覚えてる？",
  ui_story_5028_50280901_18_dialog_content = "ごめん、はっきりとは見えてない。僕が見たのは、\n背の高い誰かが、君の師匠をかついで街を出たってことだけだよ。",
  ui_story_5028_50280901_19_dialog_content = "でも、あの服は…\n最近この辺りによく出るっていう強盗かも。",
  ui_story_5028_50280901_20_dialog_content = "強盗？",
  ui_story_5028_50280901_21_dialog_content = "分かった。\n後の事は「珍獣マスター」のあたしに任せて。",
  ui_story_5028_50280901_22_dialog_content = "ムリは絶対にしちゃダメだよ、フィア。",
  ui_story_5028_50280901_23_dialog_content = "どうしてもって事なら、いくらかお金を出して、\nシャドウマスターに手伝ってもらいなよ…",
  ui_story_5028_50280901_24_dialog_content = "大丈夫！\nあたしたちで何とかなるから。",
  ui_story_5028_50280901_25_dialog_content = "それならいいけど…\nじゃあ、僕は行くね。",
  ui_story_5028_50280901_26_dialog_content = "はあ…あたしだって、\n手伝ってもらった方がいいとは思うけど…",
  ui_story_5028_50280901_27_dialog_content = "師匠、お金なんて持ってないもん。",
  ui_story_5028_50280901_28_dialog_content = "僕たち2人だけで、本当に強盗とやり合うつもり？",
  ui_story_5028_50280901_29_dialog_content = "「2人だけ」？",
  ui_story_5028_50280901_30_dialog_content = "忘れてもらっちゃ困るよ。あたしは「珍獣マスター」！\n珍獣の仲間がたくさんいるんだから！",
  ui_story_5028_50280901_31_dialog_content = "ペコペコ！",
  ui_story_5028_50280901_32_dialog_content = "モチモチ…",
  ui_story_5028_50280901_33_dialog_content = "うんうん！分かったよ、\nあなたたちも助けてくれるんだね！",
  ui_story_5028_50280901_34_dialog_content = "みんなの助けがあれば、きっと師匠を助けられる！",
  ui_story_5028_50280901_35_dialog_content = "ルルル…",
  ui_story_5028_50280901_36_dialog_content = "キャロが何を言ってるのかは相変わらず分からないけど、\nあたしは絶対、師匠を助けてみせるよ！",
  ui_story_5028_50280901_37_dialog_content = "貧乏なヴィックさんをわざわざ狙ったなら…\n知識が目的ってことになるのかな？",
  ui_story_5028_50280901_38_dialog_content = "足取りをつかむ方法が、何か…",
  ui_story_5028_50280901_39_dialog_content = "まさか、本気でシャドウマスターに\n助けてもらうつもり？",
  ui_story_5028_50280901_40_dialog_content = "もっといい方法があるはずだよ。",
  ui_story_5028_50280901_41_dialog_content = "そうだなぁ…",
  ui_story_5028_50280901_42_dialog_content = "強盗同士なら、目標のモノ以外に\nライバルの情報も少なからず知ってるんじゃないかな。",
  ui_story_5028_50280901_43_dialog_content = "法律を守らない分、縄張り意識は強いから。",
  ui_story_5028_50280901_44_dialog_content = "1人捕まえて、尋問できれば、\n手がかりがつかめるかも！",
  ui_story_5028_50280901_45_dialog_content = "でも、強盗ってどこにいるのかな…？",
  ui_story_5028_50280901_46_dialog_content = "強盗を見つけたいの？",
  ui_story_5028_50280901_47_dialog_content = "そんなの、簡単じゃない！",
  ui_story_5028_50280901_48_dialog_content = "あたしたちがお金持ちのフリをすればいいんだよ！",
  ui_story_5028_50280901_49_dialog_content = "例えば――",
  ui_story_5028_50280901_50_dialog_content = "そ、それって…",
  ui_story_5028_50280901_51_dialog_content = "ダメだよ！僕は反対！",
  ui_story_5028_50280901_52_dialog_content = "あれは、僕が地上に出てから\n地道に貯めてきたお金なんだ！！！",
  ui_story_5028_50280901_53_dialog_content = "PlayerNameお兄ちゃん、\nあたしの師匠を見殺しにしちゃうの…？",
  ui_story_5028_50280901_54_dialog_content = "…",
  ui_story_5028_50280901_55_dialog_content = "フィアが珍獣マスターとして\n永遠に卒業できなくなっちゃっていいの…？",
  ui_story_5028_50280901_56_dialog_content = "…",
  ui_story_5028_50280901_57_dialog_content = "ぐすっ…分かったよ。\nじゃあ、ここでお別れだね…",
  ui_story_5028_50280901_58_dialog_content = "フィアは1人で師匠を助けに行くよ。\n強盗に捕まったとしても、PlayerNameには関係ないから！！",
  ui_story_5028_50280901_X58_dialog_content = "うわあああ～ん！！！",
  ui_story_5028_50280901_X59_dialog_content = "……",
  ui_story_5028_50280901_X60_dialog_content = "もう…！！！",
  ui_story_5028_50280901_59_dialog_content = "<color=#e8d9bb>しばらくして</color>",
  ui_story_5028_50280901_60_dialog_content = "雲島の特産、りんごアメとたい焼きだよー！",
  ui_story_5028_50280901_61_dialog_content = "お客さん、何にします？",
  ui_story_5028_50280901_62_dialog_content = "ここにあるもの全部、10個ずつください！\nお金はこの人が払うから！",
  ui_story_5028_50280901_63_dialog_content = "はい、ぼ、僕が払います…！",
  ui_story_5028_50280901_64_dialog_content = "はぁ～、ずいぶん太っ腹ですね！\n今すぐ用意しますよ！",
  ui_story_5028_50280901_65_dialog_content = "わあ、おいしそうなものがいっぱい！",
  ui_story_5028_50280901_66_dialog_content = "（なんでお金持ちのフリをするなんて計画に\n乗せられちゃったんだろう…）",
  ui_story_5028_50280901_67_dialog_content = "（こんなにたくさん使ったら、\nまたバイスに怒られる…！）",
  ui_story_5028_50280901_68_dialog_content = "もぐもぐ…おいしい！",
  ui_story_5028_50280901_69_dialog_content = "もう一つください！",
  ui_story_5028_50280901_70_dialog_content = "はい、お待ち！",
  ui_story_5028_50280901_71_dialog_content = "（ああ…バイト10日分が…）",
  ui_story_5028_50280901_72_dialog_content = "…",
  ui_story_5028_50280901_73_dialog_content = "（あの人、ずっと僕たちのことを見てる…？）",
  ui_story_5028_50280901_74_dialog_content = "僕たちのこと、ずっと見てる人がいるよ。\nかかったみたいだ…",
  ui_story_5028_50280901_75_dialog_content = "もうお腹もいっぱいになったし、\nそろそろ次のステップね！",
  ui_story_5028_50280901_76_dialog_content = "オホン、オホン！",
  ui_story_5028_50280901_77_dialog_content = "あ～、おいしかった！\nこの後は、ショッピングにでも行かない？",
  ui_story_5028_50280901_78_dialog_content = "欲しいものがあれば、\nなんでも買ってくれるんでしょ～？",
  ui_story_5028_50280901_79_dialog_content = "そ、そんなの計画にあったっけ…？",
  ui_story_5028_50280901_80_dialog_content = "<size=45>コホン！</size>",
  ui_story_5028_50280901_81_dialog_content = "イテッ！蹴らないで！？",
  ui_story_5028_50280901_82_dialog_content = "わ、分かったよ！",
  ui_story_5028_50280901_83_dialog_content = "君が気に入ったものは、\n何でも全部買ってあげる！",
  ui_story_5028_50280901_84_dialog_content = "そうそう、それでいいの。",
  ui_story_5028_50280901_85_dialog_content = "（うう、いよいよ言い逃れも出来なくなった…）",
  ui_story_5028_50280901_86_dialog_content = "（バイス、ごめん。\n僕、またお金を使い果たしちゃいそうだ…）",
  ui_story_5028_50280901_87_dialog_content = "（ソラヴァン、ごめん。\n来月のメンテナンスの費用、足りなくなるかも…）",
  ui_story_5028_50280901_88_dialog_content = "…",
  ui_story_5028_50280901_89_dialog_content = "ん？なんか向こうにいる人、\nPlayerNameに似てるね。",
  ui_story_5028_50280901_90_dialog_content = "あれは「似てる」とは言わないわね。\nPlayerName「本人」よ。",
  ui_story_5028_50280901_91_dialog_content = "でも、残念ね。ここからじゃムチが届かないわ。\n縛って止められないわね。",
  ui_story_5028_50280901_93_dialog_content = "お～い、ナビゲーター！",
  ui_story_5028_50280901_94_dialog_content = "ちょっと待って～…",
  ui_story_5028_50280901_95_dialog_content = "うるさい通りをはさんでこんな距離じゃ、\n多分聞こえないでしょうね。",
  ui_story_5028_50280901_96_dialog_content = "おしゃべりしてる間に\n追いかけた方が速くない？",
  ui_story_5028_50280901_97_dialog_content = "<color=#e8d9bb>市街地の外れ</color>",
  ui_story_5028_50280901_98_dialog_content = "（ショッピングと言いつつ、\nフィアは少しずつ人通りの少ない所に動いて来た…）",
  ui_story_5028_50280901_99_dialog_content = "フフン…ここならよさそう。",
  ui_story_5028_50280901_100_dialog_content = "PlayerName～、あたし～、疲れちゃった。\nここで一休みしよう？",
  ui_story_5028_50280901_101_dialog_content = "あっ、そ、そうだね。",
  ui_story_5028_50280901_102_dialog_content = "でも、ここはちょっと危険なんじゃ…",
  ui_story_5028_50280901_103_dialog_content = "あたしがいれば大丈夫だよ～！\n何を怖がってるの？",
  ui_story_5028_50280901_104_dialog_content = "お楽しみみたいじゃねぇか。",
  ui_story_5028_50280901_105_dialog_content = "やっぱり、さっきからついて来てた…！",
  ui_story_5028_50280901_106_dialog_content = "分かってるなら、話は早い。",
  ui_story_5028_50280901_107_dialog_content = "どうやら、ずいぶん金持ちみたいだな。\n大人しくついてこい。",
  ui_story_5028_50280901_108_dialog_content = "仕方ないね、PlayerName。\n大人しくしよう。",
  ui_story_5028_50280901_109_dialog_content = "えっ！？",
  ui_story_5028_50280901_110_dialog_content = "物分かりのいい嬢ちゃんだ。\n手を後ろに回せ。縛らせてもらう。",
  ui_story_5028_50280901_111_dialog_content = "（フィア、何考えてるの！？説明を…）",
  ui_story_5028_50280901_112_option_content = "（強制感知！）",
  ui_story_5028_50280901_113_dialog_content = "（フィア、聞こえる？\n一体どういうつもり！？）",
  ui_story_5028_50280901_114_dialog_content = "（うわっ！急にやらないで！？）",
  ui_story_5028_50280901_115_dialog_content = "（あわてないで、ついでに乗せてもらうだけじゃない。\n隠れ家に直接案内してもらえるでしょ）",
  ui_story_5028_50280901_116_dialog_content = "（そのほうが手間が省けるよ？）",
  ui_story_5028_50280901_117_dialog_content = "（だ、大丈夫かな…）",
  ui_story_5028_50280901_118_dialog_content = "（まあ、いいから見てなさい。\n今は、ガマンが大事だよ…）",
  ui_story_5028_50280901_119_dialog_content = "今日は運がいいぜ。\n目を付けてたエモノが他の奴に取られちまったのに…",
  ui_story_5028_50280901_120_dialog_content = "まさか、その後で大物が釣れるとは思ってなかったぜ！\nハハハハ！",
  ui_story_5028_50280901_121_dialog_content = "しっかり縛ったか？それじゃあ…",
  ui_story_5028_50280901_122_dialog_content = "うっ！！",
  ui_story_5028_50280901_123_dialog_content = "人探しって疲れるわ。",
  ui_story_5028_50280901_124_dialog_content = "こんなことでもなかったら、\n今ごろ休めているはずの時間なのに…",
  ui_story_5028_50280901_125_dialog_content = "またあんた！？",
  ui_story_5028_50280901_126_dialog_content = "「またあんた」？\nまったくよ、どうしてあなたたちがここに？",
  ui_story_5028_50280901_127_dialog_content = "言ったはずでしょう、私に面倒かけないでって。",
  ui_story_5028_50280901_128_dialog_content = "なのに、勝手についてくるどころか、\n強盗とつるむなんて…",
  ui_story_5028_50280901_129_option_content = "さらわれてたんだよ！",
  ui_story_5028_50280901_130_option_content = "つるんでるワケじゃないのは、\n見れば分かるでしょ！",
  ui_story_5028_50280901_131_dialog_content = "あたしの計画が台無しじゃない！",
  ui_story_5028_50280901_133_dialog_content = "「計画」…？まあ、いいわ。\nあなたたちが何をしようと、私は自分のやるべきことをやるだけ。",
  ui_story_5028_50280901_134_dialog_content = "とにかく、私に手間をかけさせないでほしいわね。",
  ui_story_5028_50280901_136_dialog_content = "うっ…ゲホゲホ！\nチクショウ、この女、なんて強ぇんだ！",
  ui_story_5028_50280901_137_dialog_content = "一斉にかかれ！あの女を叩きのめせ！",
  ui_story_5028_50280901_138_dialog_content = "手間をかけさせないでって言ったでしょう？",
  ui_story_5028_50280901_139_dialog_content = "おとなしく、ヴィックの居場所を\n教えてくれないかしら？",
  ui_story_5028_50280901_140_dialog_content = "うっ――！？",
  ui_story_5028_50280901_141_dialog_content = "吐きなさい。ヴィックはどこ？",
  ui_story_5028_50280901_142_dialog_content = "さっさと答えなさい。\nクビを絞めるのって、けっこう疲れるのよ。",
  ui_story_5028_50280901_143_dialog_content = "ううっ…ゲ、<color=#FFB400>ゲイリー</color>だ。\nゲイリーと手下のハンター…「アイアン・ウィップ団」だよ！",
  ui_story_5028_50280901_144_dialog_content = "意外ね。",
  ui_story_5028_50280901_145_dialog_content = "ゲイリー？どこかで聞きおぼえが…",
  ui_story_5028_50280901_146_dialog_content = "追ってるヒマはねぇよ。ゲイリー親分に、\n「ペコペコウサギ」を届けるのが優先だ。",
  ui_story_5028_50280901_147_dialog_content = "思い出した！ペコペコウサギを探してる時に襲われた\nハンターから聞いたんだ！",
  ui_story_5028_50280901_148_dialog_content = "え？そうだっけ？\nフィアは全然覚えてないよ？",
  ui_story_5028_50280901_149_dialog_content = "ゲイリー…珍獣の激減、犯人はアイツだったのね。",
  ui_story_5028_50280901_150_dialog_content = "知ってる人？",
  ui_story_5028_50280901_151_dialog_content = "説明するのも疲れるわ。\nそれに、そもそもあなたとは関係ないことでしょう。",
  ui_story_5028_50280901_152_dialog_content = "ゲイリーはどこ？",
  ui_story_5028_50280901_153_dialog_content = "北に10キロほど行ったところに、洞窟がある。\nそこが隠れ家だ…",
  ui_story_5028_50280901_154_dialog_content = "ぐはっ！！！",
  ui_story_5028_50280901_155_dialog_content = "本当に面倒ね。",
  ui_story_5028_50280901_156_dialog_content = "ちょっと！？待ってってば！",
  ui_story_5028_50280901_157_dialog_content = "PlayerName、あたしたちも行くよ！",
  ui_story_5028_50280901_158_dialog_content = "また見失うワケにはいかない！",
  ui_story_5028_50280901_159_dialog_content = "わ、分かった！",
  ui_story_5028_50280901_160_dialog_content = "<color=#e8d9bb>数分後</color>",
  ui_story_5028_50280901_161_dialog_content = "たくさんキゼツしてるね。",
  ui_story_5028_50280901_162_dialog_content = "はあ？なんでこいつらが？",
  ui_story_5028_50280901_163_dialog_content = "スモーキー、知り合い？",
  ui_story_5028_50280901_164_dialog_content = "コイツら全員、影ノ街の近くでハバ利かせてる強盗だよ。\nそのうち1人か2人ぐらい灰にしてやろうかと思ってたけど。",
  ui_story_5028_50280901_165_dialog_content = "まだ戦いの痕が新しいわね。",
  ui_story_5028_50280901_166_dialog_content = "急げばPlayerNameに追いつけそうだわ。",
  ui_story_5028_50280901_168_dialog_content = "じゃあ、おいらたちも急ご。",
  ui_story_5028_50280901_169_dialog_content = "PlayerName、何してんだろ？",
  ui_story_5028_50280901_170_dialog_content = "<color=#e8d9bb>隠れ家の外</color>",
  ui_story_5028_50280901_171_dialog_content = "たぶん、ここね。",
  ui_story_5028_50280901_172_dialog_content = "ぜぇはぁ…足、速い…！",
  ui_story_5028_50280901_173_dialog_content = "あそこの洞窟が、\n誘拐犯の隠れ家の入口？",
  ui_story_5028_50280901_174_dialog_content = "ま、待って！",
  ui_story_5028_50280901_175_dialog_content = "ルルル！ルルル！",
  ui_story_5028_50280901_176_dialog_content = "…<color=#FFB400>あっち</color>？\nシーラって言ったっけ、指さしなんて…",
  ui_story_5028_50280901_177_dialog_content = "…珍獣がたくさんいる！？",
  ui_story_5028_50280901_178_dialog_content = "どこどこ？僕にも見せて…",
  ui_story_5028_50280901_179_dialog_content = "珍獣だけじゃない…\n暗鬼もたくさんいる！？",
  ui_story_5028_50280901_180_dialog_content = "グオオ！！！",
  ui_story_5028_50280901_181_dialog_content = "見つかった！",
  ui_story_5028_50280901_182_dialog_content = "やっちゃえ、キャロ！",
  ui_story_5028_50280901_183_dialog_content = "はあ…また荒ごとね。",
  ui_story_5028_50280902_1_dialog_content = "キャロ！",
  ui_story_5028_50280902_2_dialog_content = "ルルルル！",
  ui_story_5028_50280902_3_dialog_content = "グア！",
  ui_story_5028_50280902_4_dialog_content = "珍獣たちは傷つけないようにしなさい！",
  ui_story_5028_50280902_5_dialog_content = "捕まってる子たちに罪はないの。",
  ui_story_5028_50280902_6_dialog_content = "ペコ…",
  ui_story_5028_50280902_7_dialog_content = "怖がらないで。\n傷つけたりしないから、こっちへいらっしゃい…",
  ui_story_5028_50280902_8_dialog_content = "ペコペコ！！！",
  ui_story_5028_50280902_9_dialog_content = "ちょっと、逃げちゃったよ！？",
  ui_story_5028_50280902_10_dialog_content = "おどかそうとしたわけじゃないわ、私はただ…",
  ui_story_5028_50280902_11_dialog_content = "グオオ！！！",
  ui_story_5028_50280902_12_dialog_content = "ああ、面倒ね…！",
  ui_story_5028_50280902_13_dialog_content = "（シーラ、何だか寂しそうな表情だ）",
  ui_story_5028_50280902_14_dialog_content = "（それに、敵側の珍獣も、フィアの珍獣も、\nどういうわけかシーラには近づこうとしない）",
  ui_story_5028_50280902_15_dialog_content = "暗鬼は全部倒したけど、\n珍獣たちもシーラにビックリして逃げちゃったよ。",
  ui_story_5028_50280902_16_dialog_content = "フフン！まぁ、あんなヤツら、\n珍獣マスターの相手じゃないし！",
  ui_story_5028_50280902_17_dialog_content = "おかしな話だね。\nなんで珍獣が暗鬼と一緒にいるんだろう？",
  ui_story_5028_50280902_18_dialog_content = "しかも、この洞窟を守ってるみたいだったけど…？",
  ui_story_5028_50280902_X18_dialog_content = "そういう風に訓練されているのでしょうね。",
  ui_story_5028_50280902_19_dialog_content = "暗鬼も！？",
  ui_story_5028_50280902_20_dialog_content = "さあ…でも、ウワサによればゲイリーは、\n<color=#FFB400>動物に言うことを聞かせることのできる鞭</color>を持っているそうよ。",
  ui_story_5028_50280902_21_dialog_content = "その鞭なら、暗鬼を飼いならすことも\nできるのかもしれないわね。",
  ui_story_5028_50280902_22_dialog_content = "何にせよ、力で他人を屈服させることなら、\nああいう手合いの人たちは得意でしょうし。",
  ui_story_5028_50280902_23_dialog_content = "あの珍獣たちも…？",
  ui_story_5028_50280902_24_dialog_content = "当然、その鞭を使ったんでしょうね。",
  ui_story_5028_50280902_25_dialog_content = "そもそも研究者でもないし、動物の気持ちなんてどうでもいいのよ。\nいちばん簡単で乱暴な方法で、目的を果たそうとしてるだけ。",
  ui_story_5028_50280902_26_dialog_content = "ヒドい…！",
  ui_story_5028_50280902_27_dialog_content = "あなたは違うって言うの？",
  ui_story_5028_50280902_28_dialog_content = "珍獣のことなんて、まったく分かっていないでしょう。\n本やヴィックに教わった通りにしているだけ。",
  ui_story_5028_50280902_29_dialog_content = "「珍獣マスター」なんて自称してるようだけど、\nただのわがまま勝手な子供にしか見えないわ。",
  ui_story_5028_50280902_30_dialog_content = "そこに関しては、ヴィックと同類ね。",
  ui_story_5028_50280902_31_dialog_content = "あたしは師匠とは違う！",
  ui_story_5028_50280902_32_dialog_content = "そう？なら、答えてみなさい。",
  ui_story_5028_50280902_33_dialog_content = "アリガタモドキドリの卵を人工ふ化させる場合、\n第二段階の温度は、何度にたもつべきか。分かる？",
  ui_story_5028_50280902_34_dialog_content = "た、確か、30…いや、40度…？",
  ui_story_5028_50280902_35_dialog_content = "42.5度よ。そして6時間ごとに\n卵をひっくり返さなくてはならないの。",
  ui_story_5028_50280902_36_dialog_content = "ひっくり返す！？",
  ui_story_5028_50280902_37_dialog_content = "そうよ。\nやらなかったら、失敗するわ。",
  ui_story_5028_50280902_38_dialog_content = "そ、そんなことぐらい、知ってたよ！",
  ui_story_5028_50280902_39_dialog_content = "ノートを見れば、分かるもん！",
  ui_story_5028_50280902_40_dialog_content = "いちばん大事なはずの珍獣のことでさえ、\nカンニングしないと答えられないの？",
  ui_story_5028_50280902_41_dialog_content = "ずいぶんテキトーに生きてるのね。",
  ui_story_5028_50280902_42_dialog_content = "あ、あたしは…",
  ui_story_5028_50280902_43_dialog_content = "うわあああ～ん！！！",
  ui_story_5028_50280902_44_dialog_content = "フィア！？",
  ui_story_5028_50280902_45_dialog_content = "はぁ…だから、子供は面倒なのよ。",
  ui_story_5028_50280902_46_dialog_content = "子供じゃないもん！！",
  ui_story_5028_50280902_47_dialog_content = "そういうところが子供なのよ。",
  ui_story_5028_50280902_48_dialog_content = "悪いことは言わないわ。早めにあきらめなさい。\nペットたちを連れて、おうちに帰るのよ。",
  ui_story_5028_50280902_49_dialog_content = "それぐらいにしておいて…\nフィアが泣きやまなくなっちゃうよ。",
  ui_story_5028_50280902_50_dialog_content = "うわぁああん！",
  ui_story_5028_50280902_51_dialog_content = "あなたにも責任があるわ。",
  ui_story_5028_50280902_52_dialog_content = "えっ？",
  ui_story_5028_50280902_53_dialog_content = "わがままな子供は、叱られなければ、\n永遠に成長しないの。",
  ui_story_5028_50280902_54_dialog_content = "今みたいなままで放っておいたら、\nいつかきっと、ものすごく面倒なことになるわよ。",
  ui_story_5028_50280902_55_dialog_content = "昔の私みたいにね。",
  ui_story_5028_50280902_56_dialog_content = "うう…！ま、待ちなさい！！",
  ui_story_5028_50280902_57_dialog_content = "アイツ、どうしていつも捨てゼリフ吐いて、\nさっさとどっか行っちゃうの！？",
  ui_story_5028_50280902_58_dialog_content = "洞窟にまっすぐ入っていったよ。",
  ui_story_5028_50280902_59_dialog_content = "あたしのこと、あんな風に…\nそんなことないもん…",
  ui_story_5028_50280902_60_dialog_content = "フィア、大丈夫？",
  ui_story_5028_50280902_61_dialog_content = "ルル！",
  ui_story_5028_50280902_62_dialog_content = "あたしは、ぐすっ…そう簡単にあきらめない！！",
  ui_story_5028_50280902_63_dialog_content = "えっ？",
  ui_story_5028_50280902_64_dialog_content = "あたしの目標は珍獣マスターになることだもん！\nちょっと人に笑われたぐらいで、あきらめないから！！",
  ui_story_5028_50280902_65_dialog_content = "あたしたちも追いかけよう！",
  ui_story_5028_50280902_66_dialog_content = "入口の見張りは全部倒れてるんだし、\nこっそり潜入すれば、師匠を助けられるよ！",
  ui_story_5028_50280902_67_dialog_content = "シーラって言ってたよね？",
  ui_story_5028_50280902_68_dialog_content = "あたしの力を証明してやるんだから！",
  ui_story_5028_50281001_1_dialog_content = "ここがゲイリーの隠れ家って…\n趣味わる～い…",
  ui_story_5028_50281001_2_dialog_content = "汚いところだらけの上に、空っぽのカゴばっかり…\nしかも、すっごく臭い…",
  ui_story_5028_50281001_3_dialog_content = "たぶん最近まで、\n珍獣をたくさん閉じ込めてたのかな…",
  ui_story_5028_50281001_4_dialog_content = "カゴは全部開きっぱなしだ。\n中に動物はいないね。",
  ui_story_5028_50281001_5_dialog_content = "いや、シーラが逃がしたのかな？",
  ui_story_5028_50281001_6_dialog_content = "ちょっと待って…",
  ui_story_5028_50281001_7_dialog_content = "フィア、気を付けて。\n珍獣が大量に、こっちに向かってくるのを感知した…",
  ui_story_5028_50281001_8_dialog_content = "急いで避けないと、ぶつかるよ！",
  ui_story_5028_50281001_9_dialog_content = "えっ？",
  ui_story_5028_50281001_10_dialog_content = "ええっ――！？",
  ui_story_5028_50281001_11_dialog_content = "どういうこと？",
  ui_story_5028_50281001_12_dialog_content = "誰か、教えてよ！？",
  ui_story_5028_50281001_13_dialog_content = "ねえ、何が起こってるの？",
  ui_story_5028_50281001_14_dialog_content = "モチモチ…",
  ui_story_5028_50281001_15_dialog_content = "えっ！？",
  ui_story_5028_50281001_16_dialog_content = "この先に、殺気のあふれた\n恐ろしいヤツがいる？",
  ui_story_5028_50281001_17_dialog_content = "そいつがあなたたちを逃がして、\n一人で奥に行った？",
  ui_story_5028_50281001_18_dialog_content = "恐ろしいヤツ…",
  ui_story_5028_50281001_19_option_content = "ゲイリーかな？",
  ui_story_5028_50281001_20_dialog_content = "PlayerName、単純だね～。",
  ui_story_5028_50281001_21_dialog_content = "それなら珍獣を逃がしてあげるワケないでしょ。",
  ui_story_5028_50281001_22_dialog_content = "た、確かに…",
  ui_story_5028_50281001_23_dialog_content = "たぶん、シーラのことだよ。",
  ui_story_5028_50281001_24_dialog_content = "まさか、今までたくさんの動物が怖がってたって言う、\n「恐ろしい誰か」って…",
  ui_story_5028_50281001_25_option_content = "シーラのこと？",
  ui_story_5028_50281001_26_dialog_content = "珍獣たちから見ると、\n怖そうな感じなのかも。",
  ui_story_5028_50281001_27_dialog_content = "いっつも不機嫌そうだもんね～。",
  ui_story_5028_50281001_28_dialog_content = "それで、さっきも避けられてたのか…",
  ui_story_5028_50281001_29_dialog_content = "動物たちは放っておいて大丈夫。\nケガもないみたいだし、自分で逃げられるよ。",
  ui_story_5028_50281001_30_dialog_content = "あたしたちは、師匠探しを続けるよ。",
  ui_story_5028_50281001_31_dialog_content = "わかった。",
  ui_story_5028_50281001_32_dialog_content = "真っ暗で何も見えないなぁ…",
  ui_story_5028_50281001_33_dialog_content = "珍獣たち、ずっとこんな所に閉じ込められてたの？",
  ui_story_5028_50281001_34_dialog_content = "気分が悪くなるよ…",
  ui_story_5028_50281001_35_dialog_content = "へぇ～、もう怖くなったの～？\n空の末裔って怖がりなんだ～？",
  ui_story_5028_50281001_36_dialog_content = "あの、フィア、君の後ろに…",
  ui_story_5028_50281001_37_dialog_content = "残念でした！そんな古い手には\n引っかからないよ～だ。",
  ui_story_5028_50281001_38_dialog_content = "あなたたち…やっぱり、ついて来ていたのね。",
  ui_story_5028_50281001_39_dialog_content = "うひゃあ！？",
  ui_story_5028_50281001_40_dialog_content = "いつあたしの後ろに！？\n何も物音なんてしなかったのに！",
  ui_story_5028_50281001_41_dialog_content = "い、いちおう言っとくけど、\nあたし、驚いてなんかないからね！",
  ui_story_5028_50281001_42_dialog_content = "…",
  ui_story_5028_50281001_43_dialog_content = "シーラ、ヴィックさんは一緒じゃないの？",
  ui_story_5028_50281001_44_dialog_content = "あの人ならまだ、洞窟の奥で縛り付けられてるわ。",
  ui_story_5028_50281001_45_dialog_content = "なんで助けないの！？",
  ui_story_5028_50281001_46_dialog_content = "縄を解くのも面倒だからよ。\nそれにあの人を連れて行動するなんて、もっと面倒だわ。",
  ui_story_5028_50281001_47_dialog_content = "またそれ？面倒って、もう聞き飽きたよ。",
  ui_story_5028_50281001_48_dialog_content = "それに、あの人を自由にしたら、\n何をしでかすか分からないわ。",
  ui_story_5028_50281001_49_dialog_content = "そもそも珍獣の保護なんて、\n根本的に向かない性格なのよ。",
  ui_story_5028_50281001_50_dialog_content = "もっときちんとした人に任せないと。",
  ui_story_5028_50281001_51_dialog_content = "そこはあたしも賛成…\nダメ師匠、まるでアテにならないもん。",
  ui_story_5028_50281001_52_dialog_content = "だから、この世界の珍獣たちは、\n珍獣マスターのあたしが守ってあげるの！",
  ui_story_5028_50281001_53_dialog_content = "好きにしなさい…",
  ui_story_5028_50281001_54_dialog_content = "中にいるから、助けたければご自由に。",
  ui_story_5028_50281001_55_dialog_content = "ただ、私の邪魔だけはしないで。",
  ui_story_5028_50281001_56_dialog_content = "あたしをバカにしてるの！？",
  ui_story_5028_50281001_57_dialog_content = "また行っちゃった…\nいつかアゴが外れるほど驚かせてやるんだから！",
  ui_story_5028_50281001_58_dialog_content = "ルルル！！",
  ui_story_5028_50281001_59_dialog_content = "キャロ、あんたもそう思うよね？",
  ui_story_5028_50281001_60_dialog_content = "でも、まずは師匠を助けなきゃ。",
  ui_story_5028_50281001_61_dialog_content = "<color=#e8d9bb>ゲイリーの隠れ家・深部</color>",
  ui_story_5028_50281001_62_dialog_content = "師匠！",
  ui_story_5028_50281001_63_dialog_content = "あ～あ、こんな姿で…\nホント、情けな～い。",
  ui_story_5028_50281001_64_dialog_content = "仕方ないから、\nあたしが縄を解いてあげるか。",
  ui_story_5028_50281001_65_dialog_content = "ハハハ、お前なら\nきっと助けに来てくれると思ってたよ。",
  ui_story_5028_50281001_66_dialog_content = "本当にちょうどいいタイミングだ。\n手がそろそろしびれて、限界だったんでな。",
  ui_story_5028_50281001_67_dialog_content = "で、そちらは？",
  ui_story_5028_50281001_68_dialog_content = "初めまして、ヴィックさん。\n僕はPlayerName――",
  ui_story_5028_50281001_69_option_content = "フィアに捕まった希少生物です",
  ui_story_5028_50281001_70_dialog_content = "そうそう！",
  ui_story_5028_50281001_71_dialog_content = "あたしが捕まえた――空の末裔だよ！",
  ui_story_5028_50281001_72_dialog_content = "世界でたった1匹しかいないの！",
  ui_story_5028_50281001_73_option_content = "フィアの仲間です",
  ui_story_5028_50281001_74_dialog_content = "その通り！あたしの仲間になった珍獣の一匹だよ。",
  ui_story_5028_50281001_75_dialog_content = "世界で一匹だけの空の末裔！",
  ui_story_5028_50281001_76_dialog_content = "ほう？ほんとに捕まえたのか。",
  ui_story_5028_50281001_77_dialog_content = "トーゼンでしょ！",
  ui_story_5028_50281001_78_dialog_content = "それだけじゃないよ！\n師匠の試練も全部、クリアしたんだから！",
  ui_story_5028_50281001_79_dialog_content = "そりゃ、すごいな。",
  ui_story_5028_50281001_80_dialog_content = "当たり前でしょ。あたしは未来の「珍獣マスター」だもん。\nこれぐらい出来なくて、どうするの？",
  ui_story_5028_50281001_81_dialog_content = "空の末裔が見つかったなら、\nこの後のことにも希望が出てきたな。",
  ui_story_5028_50281001_82_dialog_content = "「この後」？",
  ui_story_5028_50281001_83_dialog_content = "そうさ。卒業前の最後の試練だ！\nゲイリーの企みを阻止して来い！",
  ui_story_5028_50281001_84_dialog_content = "ちょっとちょっと！？",
  ui_story_5028_50281001_85_dialog_content = "言われた試練が終わったら、\n卒業だって言ってなかった？",
  ui_story_5028_50281001_86_dialog_content = "全ての試練が終わったと思ったら、本当の試練を託される。\n物語って、大体そういうもんだろ？",
  ui_story_5028_50281001_87_dialog_content = "信じらんない！このダメ師匠！！",
  ui_story_5028_50281001_88_dialog_content = "2人とも、何の話をしてるの…？",
  ui_story_5028_50281001_89_dialog_content = "何がどうなってるのか、\n説明してくれないかな…？",
  ui_story_5028_50281001_90_dialog_content = "ヴィックさん、ゲイリーっていう人物とは、\n一体どういう関係で、なんで縛られてたんですか？",
  ui_story_5028_50281001_91_dialog_content = "話すと長くなるんだが…",
  ui_story_5028_50281001_92_dialog_content = "俺とゲイリーは、昔は友人…みたいな付き合いでな。",
  ui_story_5028_50281001_93_dialog_content = "俺は珍獣が好きで、他人からは浮いてたんだ。\n話したがるヤツなんて、ほとんどいなかった。",
  ui_story_5028_50281001_94_dialog_content = "でも、あいつは俺が珍獣好きだって知って、\nよく珍獣のことを聞きに来るようになった。",
  ui_story_5028_50281001_95_dialog_content = "貴重な友人に出会えたと思って、\n俺は自分の知ってることを、何でも教えたよ。",
  ui_story_5028_50281001_96_dialog_content = "だがある日、酒場で飲んでいる時…\nあいつが酔っぱらった俺に、聞いてきたんだ――",
  ui_story_5028_50281001_97_dialog_content = "ヴィック、そんなに珍獣に詳しいなら…",
  ui_story_5028_50281001_98_dialog_content = "世界最強の動物は何かも、知ってるのか？",
  ui_story_5028_50281001_99_dialog_content = "最強の動物…ねぇ？",
  ui_story_5028_50281001_100_dialog_content = "ハハハ、もちろん知ってるさ…ゲップ！",
  ui_story_5028_50281001_101_dialog_content = "世界最強の動物は…<color=#FFB400>キャロ</color>って動物だ！",
  ui_story_5028_50281001_102_dialog_content = "キャロの信用が得られるなら、\nそいつは間違いなく…無敵だろうな！",
  ui_story_5028_50281001_103_dialog_content = "そうなれば…ウプッ…カナン城を踏みつぶすのも、\n白夜城を握りつぶすのも、なんだって…思いのままさ！",
  ui_story_5028_50281001_104_dialog_content = "その質問…単なる好奇心じゃ、\nなかったんですよね？",
  ui_story_5028_50281001_105_dialog_content = "ハハハ…その質問の答えはな…\n俺も今になって、ようやく分かったんだ。",
  ui_story_5028_50281001_106_dialog_content = "あいつが俺に近づいてきたのは、\nある目的のためでしかなかったんだ。",
  ui_story_5028_50281001_107_dialog_content = "どういう目的？",
  ui_story_5028_50281001_108_dialog_content = "復讐だ。珍獣に対してな。",
  ui_story_5028_50281001_109_dialog_content = "どういうことですか？",
  ui_story_5028_50281001_110_dialog_content = "俺だって分からないよ。",
  ui_story_5028_50281001_111_dialog_content = "とにかく、それを聞いた後、\nゲイリーは姿を消したんだ。",
  ui_story_5028_50281001_112_dialog_content = "その次に会った時には、\n俺はこうして縛られてたってワケさ。",
  ui_story_5028_50281001_113_dialog_content = "で、一文無しのダメ師匠のどこに、\nわざわざ誘拐するほどの価値があるの？",
  ui_story_5028_50281001_114_dialog_content = "お前にそんな風に言われると、\n俺の繊細なハートが傷付いちまうなぁ――",
  ui_story_5028_50281001_115_dialog_content = "さっさと答えて！",
  ui_story_5028_50281001_116_dialog_content = "イテテテ！",
  ui_story_5028_50281001_117_dialog_content = "…あいつはキャロの棲息地を知りたがってるんだ。",
  ui_story_5028_50281001_118_dialog_content = "えっ？",
  ui_story_5028_50281001_119_dialog_content = "まさか、キャロがいれば無敵っていう話を、\n本当に信じてるの…？",
  ui_story_5028_50281001_120_dialog_content = "それって、ダメ師匠のウソっぱちでしょ？",
  ui_story_5028_50281001_121_dialog_content = "…",
  ui_story_5028_50281001_122_dialog_content = "もし本当のことなら、\n放っておけば、世界全体が危ない…",
  ui_story_5028_50281001_123_dialog_content = "まあ、安心しなって。\n大丈夫だよ。",
  ui_story_5028_50281001_124_dialog_content = "仮にあいつがこの世界のキャロを全部捕まえられたとしても、\n世界がどうにかなったりはしないさ。",
  ui_story_5028_50281001_125_dialog_content = "放っておいて、何も問題はない。",
  ui_story_5028_50281001_126_dialog_content = "…",
  ui_story_5028_50281001_127_dialog_content = "<size=50>そんなワケないでしょ――！</size>",
  ui_story_5028_50281001_128_dialog_content = "未来の珍獣マスターとして、そんなこと絶対に許さない！",
  ui_story_5028_50281001_129_dialog_content = "ルルル！",
  ui_story_5028_50281001_130_dialog_content = "おいおい…",
  ui_story_5028_50281001_131_dialog_content = "珍獣を使って悪い事ばかりしようとして、\n気持ちなんて、まったく考えない人たちなんだよ！？",
  ui_story_5028_50281001_132_dialog_content = "キャロたちがゲイリーに捕まったら、\n無理やりにでも言うこと聞かせようとするに決まってる！",
  ui_story_5028_50281001_133_dialog_content = "やりたくもないことを動物たちにやらせるなんて、\nあたしが絶対に許さない！",
  ui_story_5028_50281001_134_dialog_content = "そう…そうだ！その通りだな！",
  ui_story_5028_50281001_135_dialog_content = "よし！ならその勢いに乗って、\nゲイリーを見つけて、計画を阻止して来い！",
  ui_story_5028_50281001_136_dialog_content = "キャロたちのために…\n最後にもう1回だけ、師匠を信じてあげる！",
  ui_story_5028_50281001_137_dialog_content = "あたしの仲間たちと一緒に、\n事件を解決してみせるから！",
  ui_story_5028_50281001_138_dialog_content = "未来の珍獣マスターの名にかけて！",
  ui_story_5028_50281001_139_dialog_content = "キャロ、ペコペコウサギ、ネバネバスライム、ビッカー、\nそれからPlayerName。みんな、あたしを手伝ってくれるよね？",
  ui_story_5028_50281001_140_dialog_content = "ルルル！！",
  ui_story_5028_50281001_141_dialog_content = "ペコペコ！",
  ui_story_5028_50281001_142_dialog_content = "モチモチ…",
  ui_story_5028_50281001_143_dialog_content = "ハイハイ！",
  ui_story_5028_50281001_144_dialog_content = "あ…ええと、うん？",
  ui_story_5028_50281001_145_dialog_content = "よ～し、じゃあ今すぐ、出発！",
  ui_story_5028_50281001_146_dialog_content = "ああ、お前たちの様子じゃ、\n今さら師匠の手助けなんざ、要らないようだな…",
  ui_story_5028_50281001_147_dialog_content = "だったら、俺は先に家に帰って、\nいい知らせを待ってるってことに――イテテテテ！！！",
  ui_story_5028_50281001_148_dialog_content = "お、おい、少しは手加減しろ！\n師匠はもういい年なんだぞ、そんなふうに引っ張られたらちぎれちまう！",
  ui_story_5028_50281001_149_dialog_content = "前に「永遠の18歳だ」って言ってたでしょ！！",
  ui_story_5028_50281001_150_dialog_content = "それは…ハ、ハハハハ…",
  ui_story_5028_50281001_151_dialog_content = "だいたいこの事件、\nそもそも師匠が起こした面倒ごとでしょ？",
  ui_story_5028_50281001_152_dialog_content = "自分でやったことなんだから、\n自分で後片付けしなきゃ。ねえ？",
  ui_story_5028_50281001_153_dialog_content = "でも、もし…",
  ui_story_5028_50281001_154_dialog_content = "「偉大な珍獣マスターフィア様、\nどうかお手伝いしてください！」って言うなら…",
  ui_story_5028_50281001_155_dialog_content = "助けてあげてもいいよ？",
  ui_story_5028_50281001_156_dialog_content = "ハハハ…そいつはムリだな。\nせめてゲイリーを止めた後でなきゃ話にならん。",
  ui_story_5028_50281001_157_dialog_content = "へぇ、そうなんだ…？じゃあ、戻って来た見張りの暗鬼は、\n師匠が全部自分で片づけてね！",
  ui_story_5028_50281001_158_dialog_content = "ハハハ…何！？",
  ui_story_5028_50281001_159_dialog_content = "グオオ！",
  ui_story_5028_50281001_160_dialog_content = "うわあ！助けてくれ！！",
  ui_story_5028_50281001_161_dialog_content = "こんな数、俺1人じゃムリだ！",
  ui_story_5028_50281002_1_dialog_content = "うっ、腰が…",
  ui_story_5028_50281002_2_dialog_content = "激しい運動は、\nやっぱり俺には向かないな…",
  ui_story_5028_50281002_3_dialog_content = "大げさでしょう…ヴィックさん、\n僕とそこまで年の差ないですよね？",
  ui_story_5028_50281002_4_dialog_content = "PlayerName、見た目で判断しちゃあ、いけないぜ…",
  ui_story_5028_50281002_5_dialog_content = "確かに俺は永遠の18歳だが、\n人生経験は君よりずっと豊富なんだ。",
  ui_story_5028_50281002_6_dialog_content = "ま～たそれ！ダメ師匠はね、\n誰かに疑われるといっつもそう言うの。",
  ui_story_5028_50281002_7_dialog_content = "どうせ全部ウソなんでしょ！？",
  ui_story_5028_50281002_8_dialog_content = "うう…愛弟子にそんなこと言われるなんて、\n傷付くなぁ…",
  ui_story_5028_50281002_9_dialog_content = "（ヴィックさん、泣きそうな顔してる？）",
  ui_story_5028_50281002_10_dialog_content = "上の弟子には捨てられたし、下の弟子には嫌われてる…\n俺ってヤツは、どうしてこんなに弟子に嫌われるんだ？",
  ui_story_5028_50281002_11_dialog_content = "なるほどね～、「上の弟子」が助けるの面倒だって言ってたワケだよ。\nホント、面倒くさい…",
  ui_story_5028_50281002_12_dialog_content = "いや、お前の姉弟子は助けるのが面倒だったわけじゃないと思うぞ。\n今はちょっと…仲たがいしててな。",
  ui_story_5028_50281002_13_dialog_content = "な、仲たがい？",
  ui_story_5028_50281002_14_dialog_content = "師匠がすぐそこに縛られて捕まってるのを\n分かってて見捨てるほど…？",
  ui_story_5028_50281002_15_dialog_content = "あいつはな…珍獣に対する愛じゃ、\nお前に勝るとも劣らん。",
  ui_story_5028_50281002_16_dialog_content = "だが、少しばかり運が悪かった。\nお前たちも、変わったところがあるって気付いたろ？",
  ui_story_5028_50281002_17_dialog_content = "まさか…",
  ui_story_5028_50281002_18_dialog_content = "あの触手？",
  ui_story_5028_50281002_19_dialog_content = "そうさ。",
  ui_story_5028_50281002_20_dialog_content = "動物に好かれないこと？",
  ui_story_5028_50281002_21_dialog_content = "その通りだ。\n洞察力があるみたいだな。",
  ui_story_5028_50281002_22_dialog_content = "シーラは…事故に遭ってな。\n両足が側にいたタコの足と融合しちまったんだ。",
  ui_story_5028_50281002_23_dialog_content = "もとは動物に好かれるタイプだったんだが、\nタコと融合してからは、怖がられるようになっちまってな。",
  ui_story_5028_50281002_24_dialog_content = "動物たちにとっちゃ、\nあのタコはワケの分からねぇ、恐ろしい生物らしい。",
  ui_story_5028_50281002_25_dialog_content = "シーラはひどくショックを受けた…\nだが、だからといって、珍獣への熱意や愛が薄れることもなかった。",
  ui_story_5028_50281002_26_dialog_content = "ただ、その頃から、\nあいつの珍獣に対する態度が変わったんだ。",
  ui_story_5028_50281002_27_dialog_content = "どんな風に…？",
  ui_story_5028_50281002_28_dialog_content = "気付かなかったか？",
  ui_story_5028_50281002_29_dialog_content = "シーラは今でも珍獣を大事に思ってる。\nだが…",
  ui_story_5028_50281002_30_dialog_content = "あいつ、俺をアマチュア扱いするようになったんだ！！",
  ui_story_5028_50281002_31_dialog_content = "俺のやり方はシロウト同然、\n珍獣たちを傷つけるだけだって、言い出し始めてな。",
  ui_story_5028_50281002_32_dialog_content = "ひどいと思わないか？",
  ui_story_5028_50281002_33_dialog_content = "…",
  ui_story_5028_50281002_34_dialog_content = "センパイ、本当にお疲れ様…",
  ui_story_5028_50281002_35_dialog_content = "まさか、お前まで…",
  ui_story_5028_50281002_36_dialog_content = "…まあ、いい。\n誤解されることには慣れてるからな。",
  ui_story_5028_50281002_37_dialog_content = "とにかく、シーラは俺の成り行きまかせのやり方が気に入らなくて、\n珍獣の「本物のプロ」になることを目指したんだ。",
  ui_story_5028_50281002_38_dialog_content = "「本物のプロ」？具体的にはどういう…",
  ui_story_5028_50281002_39_dialog_content = "あいつは大量の古代の資料をていねいに調べて、\n珍獣の生態を観測する方法を色々と編み出したんだ。",
  ui_story_5028_50281002_40_dialog_content = "例えば、捕まえた珍獣の足に\n輪っかを付けてから放すとかな。",
  ui_story_5028_50281002_41_dialog_content = "そうすれば、次にその動物の群れにあった時、\n群れの数を予測したり移動を追ったりできる。",
  ui_story_5028_50281002_42_dialog_content = "ってことは、ドラゴライオンの足に付いてたリング…\nシーラ先輩がつけたものだったってこと？",
  ui_story_5028_50281002_43_dialog_content = "ああ、たぶんな…\n他にそんなことをするヤツはいないだろう。",
  ui_story_5028_50281002_44_dialog_content = "他にも方法はたくさんあるが…\nそのうちの多くが実績を上げてるのは認めるしかない。",
  ui_story_5028_50281002_45_dialog_content = "だが、あいつの俺に対する間違った認識は消えないどころか、\nどんどんエスカレートしていったんだ！",
  ui_story_5028_50281002_46_dialog_content = "あいつは事故の原因を、珍獣に対する理解不足…\nひいては、俺のせいだと考えてる。",
  ui_story_5028_50281002_47_dialog_content = "それであいつは俺をフマジメだって決めつけて、\n毛嫌いしてるんだ！",
  ui_story_5028_50281002_48_dialog_content = "え？先輩がああなったのって、\n師匠のせいだったの！？",
  ui_story_5028_50281002_49_dialog_content = "違う違う！！\n事故だよ、純粋な事故だ！",
  ui_story_5028_50281002_50_dialog_content = "シーラが自分の出生について何も知らないから、\n調べたいって言いだしたんだ。",
  ui_story_5028_50281002_51_dialog_content = "あいつの側にはずっとタコがいたから、\nそのタコの棲息地から調べてみたらどうかって、アドバイスしたんだ。",
  ui_story_5028_50281002_52_dialog_content = "そしたらあいつ、船でそのタコのいる海に\n一人で向かって、嵐に襲われて…",
  ui_story_5028_50281002_53_dialog_content = "結局、そのタコが自分の意志であいつと融合して、\n不思議な再生能力で救われたんだと。",
  ui_story_5028_50281002_54_dialog_content = "俺は師匠として、タコを探す方法は教えたさ。\nそれ以外だって、何も間違ったことは教えてない…",
  ui_story_5028_50281002_55_dialog_content = "フン、泣きそうな顔したって、\nあたしは同情なんかしないよ。",
  ui_story_5028_50281002_56_dialog_content = "師匠がテキトーだから、\n何もかも面倒なことになってるんじゃない。",
  ui_story_5028_50281002_57_dialog_content = "過ちをつぐなう気があるなら、すぐにあたしたちを\nキャロの住みかに連れてって！ゲイリーってヤツの計画を阻止しなきゃ！",
  ui_story_5028_50281002_58_dialog_content = "ああ、俺の弟子でありながら、お前というヤツは…\nまったく師匠をいたわるってことを知らないな。",
  ui_story_5028_50281002_59_dialog_content = "もうずいぶん長いこと縛られてたんだ。\n腹が減ってるのに、道案内をさせようだなんて…",
  ui_story_5028_50281002_60_dialog_content = "なんだ、お腹が空いてるの？",
  ui_story_5028_50281002_61_dialog_content = "じゃ、このパイでも食べなさい！",
  ui_story_5028_50281002_62_dialog_content = "お？この小麦の香り、黄金色に輝くツヤ…\n遠慮なくいただくぜ！",
  ui_story_5028_50281002_63_dialog_content = "モグモグ…何のへんてつもないパイでも、\n腹が減ってる時は、うまく感じるもんだな！",
  ui_story_5028_50281002_64_dialog_content = "そのパイ、どこかで見たことあるような…\nいや、そもそもどうしてそんなもの持ってるの！？",
  ui_story_5028_50281002_65_dialog_content = "師匠を捕まえた人たち、たぶんご飯なんか\nあげる気にならないだろうなって思ってたんだ。",
  ui_story_5028_50281002_66_dialog_content = "だから、念のため用意しておいたの。",
  ui_story_5028_50281002_67_dialog_content = "モグモグ…さすがは俺の弟子だ。\n気が利くな！",
  ui_story_5028_50281002_68_dialog_content = "でも、そのパイ、買って何日か経ってるんだ。\n腐ってなければいいけど…",
  ui_story_5028_50281002_69_dialog_content = "モグ…ゲホゲホ！？",
  ui_story_5028_50281002_70_dialog_content = "ヴィックさん！？",
  ui_story_5028_50281002_71_dialog_content = "ゴホゴホ…だ、大丈夫だ。\n何ともない。少なくとも、今のところ。",
  ui_story_5028_50281002_72_dialog_content = "まだ食べる？\n他の味もあるよ！",
  ui_story_5028_50281002_73_dialog_content = "い、いや、もういい。腹いっぱいだ。",
  ui_story_5028_50281002_74_dialog_content = "じゃ、さっさと出発するよ！",
  ui_story_5028_50281002_75_dialog_content = "悪いヤツの陰謀を止めないと！",
  ui_story_5028_50281002_76_dialog_content = "あれが、PlayerNameをさらったヤツら？",
  ui_story_5028_50281002_77_dialog_content = "なんか、ヘンなの…",
  ui_story_5028_50281002_78_dialog_content = "構ってらんなくない？ちゃっちゃとツッコんで、\n全員一方的に叩きのめせばいいっしょ。",
  ui_story_5028_50281002_79_dialog_content = "相変わらず無謀ね、スモーキー。",
  ui_story_5028_50281002_80_dialog_content = "貴族の優雅さがないわ。",
  ui_story_5028_50281002_81_dialog_content = "ケンカ、しないで。",
  ui_story_5028_50281002_82_dialog_content = "チッ…",
  ui_story_5028_50281002_83_dialog_content = "こっそり、ついて行こ。\nチャンスがあったら、その時突っ込む。",
  ui_story_5028_50281101_1_dialog_content = "<color=#e8d9bb>キャロの棲息地</color>",
  ui_story_5028_50281101_2_dialog_content = "なかなかやるじゃないか、小娘が。",
  ui_story_5028_50281101_3_dialog_content = "だが、いつまで持つかな…？",
  ui_story_5028_50281101_4_dialog_content = "ゲイリー",
  ui_story_5028_50281101_X4_dialog_content = "38歳",
  ui_story_5028_50281101_X5_dialog_content = "あちこちで珍獣を乱獲している悪者",
  ui_story_5028_50281101_5_dialog_content = "動物を攻撃に使うなんて…\n本当に面倒ね。",
  ui_story_5028_50281101_6_dialog_content = "暗鬼を簡単に消し飛ばせるほどの、\n恐るべき力を持っているというのに…",
  ui_story_5028_50281101_7_dialog_content = "動物たちへの偽善的な関心が\n足かせにできるとはな。",
  ui_story_5028_50281101_8_dialog_content = "反撃もできずにいたぶられているのを見ると、\n実に笑えてくるよ。",
  ui_story_5028_50281101_9_dialog_content = "黙りなさい。",
  ui_story_5028_50281101_10_dialog_content = "あなたがいなければ、\nこんな面倒なことにはならなかったのよ。",
  ui_story_5028_50281101_11_dialog_content = "珍獣があなたの奴隷にされて、\n他の動物と殺し合いをさせられるなんてことにはね！",
  ui_story_5028_50281101_12_dialog_content = "奴隷だと？ハハハ、笑わせるな。",
  ui_story_5028_50281101_13_dialog_content = "こんな奴らには奴隷になる資格さえあるものか。\n最もいやしく、最も愚かな畜生ども…",
  ui_story_5028_50281101_14_dialog_content = "この世に存在すること自体、\n許されはしないのだ！",
  ui_story_5028_50281101_15_dialog_content = "そうはさせない！",
  ui_story_5028_50281101_16_dialog_content = "ふぅ…はぁ…",
  ui_story_5028_50281101_17_dialog_content = "クッ…",
  ui_story_5028_50281101_18_dialog_content = "いけ、殺せ！",
  ui_story_5028_50281101_19_dialog_content = "その小娘をバカげた夢物語から解放してやれ！",
  ui_story_5028_50281101_20_dialog_content = "グオォォ――！",
  ui_story_5028_50281101_21_dialog_content = "これ以上は…",
  ui_story_5028_50281101_22_dialog_content = "やっちゃえ！！",
  ui_story_5028_50281101_23_dialog_content = "ルルルル！",
  ui_story_5028_50281101_24_dialog_content = "フィア、よくやった！",
  ui_story_5028_50281101_25_dialog_content = "フフン！あたしがカッコよく戦う姿を\n思う存分驚きながら見てなさい！",
  ui_story_5028_50281101_26_dialog_content = "シーラ、大丈夫？",
  ui_story_5028_50281101_27_dialog_content = "あなたたち、どうして…",
  ui_story_5028_50281101_28_dialog_content = "安心して。\n僕たちもゲイリーを止めに来たんだよ！",
  ui_story_5028_50281101_29_dialog_content = "君のことは、ヴィックさんから聞いてる。",
  ui_story_5028_50281101_30_dialog_content = "僕たちも手伝うよ！",
  ui_story_5028_50281101_31_dialog_content = "ダメよ、早く逃げて。\n戦ってはダメ。",
  ui_story_5028_50281101_32_dialog_content = "面倒なのよ、すごく…",
  ui_story_5028_50281101_33_dialog_content = "フン、小娘が助っ人を呼んでいるとはな。",
  ui_story_5028_50281101_34_dialog_content = "特にお前は逃げるものだと\n思っていたぞ、ヴィック。",
  ui_story_5028_50281101_35_dialog_content = "俺だって、そこまで軟弱じゃないさ、ゲイリー。",
  ui_story_5028_50281101_36_dialog_content = "そちらが群れる気なら、\nこちらも助けを借りるとするか。",
  ui_story_5028_50281101_37_dialog_content = "お前たちに、この畜生どもの恐ろしさを\n味わせてやるのも、面白かろう。",
  ui_story_5028_50281101_X37_dialog_content = "暗鬼どもも呼べ、一斉にかかれ！",
  ui_story_5028_50281101_38_dialog_content = "グォォ…",
  ui_story_5028_50281101_39_dialog_content = "あいつらを引きちぎれ！",
  ui_story_5028_50281101_40_dialog_content = "はい、お頭！",
  ui_story_5028_50281101_41_dialog_content = "グォォ！",
  ui_story_5028_50281101_42_dialog_content = "いけっ、キャロ、PlayerName！",
  ui_story_5028_50281101_43_dialog_content = "ルルル！",
  ui_story_5028_50281101_44_dialog_content = "え！？僕も！？",
  ui_story_5028_50281101_45_dialog_content = "ぼーっとしてないで、早く指揮してよ！",
  ui_story_5028_50281102_1_dialog_content = "弱すぎる、まったく弱すぎる。",
  ui_story_5028_50281102_2_dialog_content = "それだけの珍獣を連れていながら、\n力の引き出し方も知らないとは。",
  ui_story_5028_50281102_3_dialog_content = "何よ！？",
  ui_story_5028_50281102_4_dialog_content = "俺が教えてやる。畜生どもに最強の力を\n発揮させたいなら、こうするのだ。",
  ui_story_5028_50281102_5_dialog_content = "さっさと起きろ！なまけ者どもが。\nあいつらを叩きのめせ！",
  ui_story_5028_50281102_6_dialog_content = "ガオオォォォ――",
  ui_story_5028_50281102_7_dialog_content = "それは…ドラゴライオン！？",
  ui_story_5028_50281102_8_dialog_content = "ガオォォォ！！！",
  ui_story_5028_50281102_9_dialog_content = "ルルル！",
  ui_story_5028_50281102_10_dialog_content = "止めて！\nこんなこと、珍獣たちは望んでない！",
  ui_story_5028_50281102_11_dialog_content = "望む？",
  ui_story_5028_50281102_12_dialog_content = "ハハハハハ！\n畜生どもにどう思われようが、知ったことか！",
  ui_story_5028_50281102_13_dialog_content = "こいつらは俺をおそれ、\n俺のために命を捧げればいいんだ！！",
  ui_story_5028_50281102_14_dialog_content = "ひどすぎる…\n珍獣マスターとして、このあたしが許さない！",
  ui_story_5028_50281102_15_dialog_content = "我が弟子ながらいいタンカだ。\nそうだ、やっちまえ！",
  ui_story_5028_50281102_16_dialog_content = "あなたの応援なんて\n毛ほどの価値もないわね。",
  ui_story_5028_50281102_17_dialog_content = "はぁ、弟子に嫌われてんな…",
  ui_story_5028_50281102_18_dialog_content = "チビなガキの分際で、口だけは達者だ。",
  ui_story_5028_50281102_19_dialog_content = "その大口に、見合った実力があればよかったんだがな。",
  ui_story_5028_50281102_20_dialog_content = "ガオオォォォ――",
  ui_story_5028_50281102_21_dialog_content = "きゃああ！",
  ui_story_5028_50281102_22_dialog_content = "フィア！！！",
  ui_story_5028_50281102_23_dialog_content = "うっ！",
  ui_story_5028_50281102_24_dialog_content = "ありゃりゃ、完全に劣勢だな…",
  ui_story_5028_50281102_25_dialog_content = "降参！降参だ！！\nどうか見逃してくれ！",
  ui_story_5028_50281102_26_dialog_content = "あなたって人は…\n抵抗することも面倒なの？",
  ui_story_5028_50281102_27_dialog_content = "だって、実際どうしようもないだろ？",
  ui_story_5028_50281102_28_dialog_content = "フィアもお前も、もう戦えないし…",
  ui_story_5028_50281102_29_dialog_content = "PlayerNameは光霊じゃなくて、空の末裔だ。\nそもそも戦う力はない。",
  ui_story_5028_50281102_30_dialog_content = "俺の手足もトシで使い物にならない…",
  ui_story_5028_50281102_31_dialog_content = "だったら、降参しかないだろ？",
  ui_story_5028_50281102_32_dialog_content = "少しぐらい、もがいたっていいんじゃ…",
  ui_story_5028_50281102_33_dialog_content = "仕方ないだろ！\n現実を見ることこそ、生き残る道だ！",
  ui_story_5028_50281102_34_dialog_content = "まさか、降参すれば\n家に帰してもらえるとでも思っているのか？",
  ui_story_5028_50281102_35_dialog_content = "そうはさせん。ここに残ってもらうぞ。\nまもなく迎える重要な時の、証人になってもらおう。",
  ui_story_5028_50281102_36_dialog_content = "あいつらを縛って、閉じ込めておけ！",
  ui_story_5028_50281102_37_dialog_content = "はい、お頭！",
  ui_story_5028_50281102_38_dialog_content = "ヘヘヘ…この間はずいぶん世話になったな。\nじっくり「お礼」させてもらうぜ…",
  ui_story_5028_50281102_39_dialog_content = "ルルル！！！",
  ui_story_5028_50281102_40_dialog_content = "キャロ！",
  ui_story_5028_50281102_41_dialog_content = "うっ！",
  ui_story_5028_50281102_42_dialog_content = "動くんじゃねえ！",
  ui_story_5028_50281102_43_dialog_content = "おいおい、もっと優しく縛ってくれ！\n腕がつっちまう、アイタタ！！",
  ui_story_5028_50281102_44_dialog_content = "チッ…",
  ui_story_5028_50281102_45_dialog_content = "終わった、どうしようもない…",
  ui_story_5028_50281102_46_dialog_content = "目を見開いて、しっかりと見届けるがいい。",
  ui_story_5028_50281102_47_dialog_content = "俺はすべての者に、こいつの恐ろしさを知らしめる。\nそして、恐怖と恨みをすべての者の心に植え付けてやるのだ。",
  ui_story_5028_50281102_48_dialog_content = "へー、それがお前の目的だったのか？",
  ui_story_5028_50281102_49_dialog_content = "なんで珍獣をそんなに恨むようになったんだ？",
  ui_story_5028_50281102_50_dialog_content = "お前のような、動物のことしか\n頭にないヤツには理解できんさ。",
  ui_story_5028_50281102_51_dialog_content = "畜生どもは俺の最も大切なものを奪ったとだけ、\n理解していればいい。",
  ui_story_5028_50281102_52_dialog_content = "最も大事なもの…？",
  ui_story_5028_50281102_53_dialog_content = "まったく、面倒だ…",
  ui_story_5028_50281102_54_dialog_content = "畜生どもに使う落とし穴が、やっと半分完成したところで、\nお前たちに壊されてしまった。",
  ui_story_5028_50281102_55_dialog_content = "だが、構わんさ。\n俺は辛抱強いからな。",
  ui_story_5028_50281102_56_dialog_content = "コイツさえ逃がさなければ…",
  ui_story_5028_50281102_57_dialog_content = "ルルルル！！！",
  ui_story_5028_50281102_58_dialog_content = "あれは何…！？",
  ui_story_5028_50281102_59_dialog_content = "姿は違うけど、\nキャロと同じ鳴き声だ…！",
  ui_story_5028_50281102_60_dialog_content = "ってことは…キャロ？",
  ui_story_5028_50281102_61_dialog_content = "師匠の経験から判断すると、\nあれは確かにキャロと同種の生き物だ。",
  ui_story_5028_50281102_62_dialog_content = "キャロと同種？\nそれなら、なぜあんな姿を？",
  ui_story_5028_50281102_63_dialog_content = "可能性はいろいろだ。",
  ui_story_5028_50281102_64_dialog_content = "突然変異、環境の違い、群れの違い…\nそういったもので個体間の姿の違いが生まれることがある。",
  ui_story_5028_50281102_65_dialog_content = "でも、あたしたちのキャロとは全然違うよ。\n本当に同じなの？",
  ui_story_5028_50281102_66_dialog_content = "そうなる原因は――\nうーん、ちょっとすぐには思いつかないな。",
  ui_story_5028_50281102_67_dialog_content = "もう、肝心の時に役立たず！！",
  ui_story_5028_50281102_68_dialog_content = "ハハハ…最後の楽しいひとときを\n大切に味わうことだ。",
  ui_story_5028_50281102_69_dialog_content = "何をするつもり？",
  ui_story_5028_50281102_70_dialog_content = "こいつらは人の言葉を理解しないが、\n同類の鳴き声には反応する。",
  ui_story_5028_50281102_71_dialog_content = "ルルルルル！！！",
  ui_story_5028_50281102_72_dialog_content = "この習性を利用すれば、辺りのキャロを一網打尽に出来る。\nそして、訓練をすれば…",
  ui_story_5028_50281102_73_dialog_content = "ククク…アハハハハ！！！",
  ui_story_5028_50281102_74_dialog_content = "アストラじゅうの光霊が\nキャロの恐ろしさを知ることになるだろう！",
  ui_story_5028_50281102_75_dialog_content = "そして、俺と同じ痛みを味わうのだ！",
  ui_story_5028_50281102_76_dialog_content = "こいつらをしっかり見張っておけ！\n逃がすんじゃないぞ。",
  ui_story_5028_50281102_77_dialog_content = "はい、お頭！",
  ui_story_5028_50281102_78_dialog_content = "<color=#e8d9bb>ゲイリーの隠れ家</color>",
  ui_story_5028_50281102_79_dialog_content = "入れ！",
  ui_story_5028_50281102_80_dialog_content = "優しく扱いなさいよ！",
  ui_story_5028_50281102_81_dialog_content = "ここを出たら、\nあんたの足を思いっきり踏みつけてやるから！",
  ui_story_5028_50281102_82_dialog_content = "おお、威勢がいいな。",
  ui_story_5028_50281102_83_dialog_content = "こんな時まで相変わらずね。",
  ui_story_5028_50281102_84_dialog_content = "危機感のない人って、\n本当に面倒だわ。",
  ui_story_5028_50281102_85_dialog_content = "静かにしろ！\nこれ以上うるさくするようなら、吊り上げるぞ！",
  ui_story_5028_50281102_86_dialog_content = "…",
  ui_story_5028_50281102_87_dialog_content = "…",
  ui_story_5028_50281102_88_dialog_content = "あんたの言うことなんて聞かないもんね！\n黙れって言うなら、もっと…もごもご！",
  ui_story_5028_50281102_89_dialog_content = "力は温存しておきなさい。\nまずは方法を考えましょう。",
  ui_story_5028_50281102_90_dialog_content = "（どうしよう、僕1人じゃ\n何も思いつかない…）",
  ui_story_5028_50281102_91_dialog_content = "（そうだ、声を出して話せないなら、\n感知能力で相談すればいいんだ！）",
  ui_story_5028_50281102_92_dialog_content = "（そうすれば、相談してるって\n向こうには気付かれない）",
  ui_story_5028_50281102_93_option_content = "強制感知！",
  ui_story_5028_50281102_94_dialog_content = "フィア！聞こえる？",
  ui_story_5028_50281102_95_dialog_content = "わっ！…PlayerNameか。\nこの能力、使う前に一言言ってくれない？",
  ui_story_5028_50281102_96_dialog_content = "ごめん。でも今は緊急事態だから。",
  ui_story_5028_50281102_97_dialog_content = "ヴィックさん？",
  ui_story_5028_50281102_98_dialog_content = "ん？空の末裔の感知能力か、懐かしいね。",
  ui_story_5028_50281102_99_dialog_content = "シーラ！",
  ui_story_5028_50281102_100_dialog_content = "聞こえてるわ。",
  ui_story_5028_50281102_101_dialog_content = "皆で逃げる方法を相談しよう！",
  ui_story_5028_50281102_102_dialog_content = "逃げる？どうやって？",
  ui_story_5028_50281102_103_dialog_content = "キャロはもう捕まっちゃったし、\n他の珍獣たちじゃ、まともに戦えないよ。",
  ui_story_5028_50281102_104_dialog_content = "シーラ先輩に聞いてみたら？変わった人だけど、力は強いよ。\n何か方法があるかも。",
  ui_story_5028_50281102_105_dialog_content = "シーラ、何かいい考えはない？\n珍獣たちの力を借りて、逃げられないかな？",
  ui_story_5028_50281102_106_dialog_content = "こんなに小さくて弱い動物たちを\n命がけで立ち向かわせるぐらいなら…",
  ui_story_5028_50281102_107_dialog_content = "自力で縄を解く方法を考える方がラクね。",
  ui_story_5028_50281102_108_dialog_content = "力さえ回復すれば、\n縄はどうとでもできるわ。",
  ui_story_5028_50281102_109_dialog_content = "動物たちに助けてもらえないなら…\nヴィックさん、何か方法はありませんか？",
  ui_story_5028_50281102_110_dialog_content = "PlayerName、慌てるな。",
  ui_story_5028_50281102_111_dialog_content = "全員身動きは取れないが、\n君は空の末裔の力であたりを探れるだろ？",
  ui_story_5028_50281102_112_dialog_content = "俺たちの運命は君に託したぞ、PlayerName。",
  ui_story_5028_50281102_113_dialog_content = "いきなり命を託してこないでくださいよ！？",
  ui_story_5028_50281102_114_dialog_content = "…でも、試してみます。",
  ui_story_5028_50281102_115_option_content = "強制感知！",
  ui_story_5028_50281102_116_dialog_content = "…",
  ui_story_5028_50281102_117_dialog_content = "（この近くには巡回してる見張りがいる…）",
  ui_story_5028_50281102_118_dialog_content = "（閉じ込められた珍獣たち…）",
  ui_story_5028_50281102_119_dialog_content = "（キャロとそっくりな珍獣がいっぱいいる！？）",
  ui_story_5028_50281102_120_dialog_content = "ヴィックさん、大変です！\nもう、キャロの同族がたくさん捕まってます！",
  ui_story_5028_50281102_121_dialog_content = "へー、本当に捕まえたのか。",
  ui_story_5028_50281102_122_dialog_content = "ま、関係ないさ。キャロの能力を\n覚醒させる方法を知らない限り、怖いことは無い。",
  ui_story_5028_50281102_123_dialog_content = "もう少し周りを見てみます…\n遠くで何かが動いてるみたいです。",
  ui_story_5028_50281102_124_dialog_content = "ガラクタの中に、レビィが隠れてる…",
  ui_story_5028_50281102_125_dialog_content = "待って、レビィ！？",
  ui_story_5028_50281102_126_dialog_content = "PlayerName！やっと気付いた！",
  ui_story_5028_50281102_127_dialog_content = "遊んでる途中だったのに、\nいきなり消えちゃうんだもん。",
  ui_story_5028_50281102_128_dialog_content = "そうなんだよ。\nフィアに無理やり手伝いさせられることになって…",
  ui_story_5028_50281102_129_dialog_content = "本当にごめん！",
  ui_story_5028_50281102_130_dialog_content = "おいらたち、ずいぶん探したんだよ！",
  ui_story_5028_50281102_131_dialog_content = "他にも誰かいるの？感知してみるよ！",
  ui_story_5028_50281102_132_dialog_content = "ジュヌヴィエーヴ…",
  ui_story_5028_50281102_133_dialog_content = "PlayerNameの近くにいるのは、\n新しいお仲間かしら？",
  ui_story_5028_50281102_134_dialog_content = "ずいぶんモテるみたいじゃない？",
  ui_story_5028_50281102_135_dialog_content = "またいろんな人の心を\n縛りあげてるってワケね。",
  ui_story_5028_50281102_136_dialog_content = "スモーキーもいるの！？\n…ジュヌヴィエーヴとケンカしてない？",
  ui_story_5028_50281102_137_dialog_content = "は？なんだ、そっちのは仲間か…",
  ui_story_5028_50281102_138_dialog_content = "燃やしがいありそーだなって思ってたんだけど。",
  ui_story_5028_50281102_139_dialog_content = "やめてね！？",
  ui_story_5028_50281102_140_dialog_content = "よかった…これだけたくさん仲間がいれば、\n逆転の手はあるはず！",
  ui_story_5028_50281102_141_dialog_content = "今、ちょっと困ったことになってて…\n助けてほしいんだ！",
  ui_story_5028_50281102_142_dialog_content = "もちろん、いつだって助けるよ。\nPlayerNameはおいらの仲間だもんね。",
  ui_story_5028_50281102_143_dialog_content = "みんなもそうだよ。\nPlayerNameを探しに来てるの。",
  ui_story_5028_50281102_144_dialog_content = "ありがとう！",
  ui_story_5028_50281102_145_dialog_content = "フィア、シーラ、ヴィックさん、\n方法が見つかったよ！",
  ui_story_5028_50281102_146_dialog_content = "近くに助っ人がいる！",
  ui_story_5028_50281102_147_dialog_content = "フフン、遅いじゃない！",
  ui_story_5028_50281102_148_dialog_content = "あんたが考えてる間に、\nあたしが<color=#FFB400>カンペキな計画</color>を思いついたよ！",
  ui_story_5028_50281102_149_dialog_content = "え？どんな？",
  ui_story_5028_50281102_150_dialog_content = "珍獣マスターを甘く見ないでよね！",
  ui_story_5028_50281102_151_dialog_content = "まずはこうして、それから…",
  ui_story_5028_50281201_1_dialog_content = "<color=#e8d9bb>ゲイリーの隠れ家の外</color>",
  ui_story_5028_50281201_2_dialog_content = "なあ…親分の計画、本当にうまくいくのか？",
  ui_story_5028_50281201_3_dialog_content = "シッ…声が大きい。",
  ui_story_5028_50281201_4_dialog_content = "計画を疑ってるって親分に知られたら、\n1晩中吊るし上げられるぞ。",
  ui_story_5028_50281201_5_dialog_content = "あのヴィックってヤツ、\n一体何を吹き込んだんだろうな。",
  ui_story_5028_50281201_6_dialog_content = "親分がこんな話を信じるなんてよ！",
  ui_story_5028_50281201_7_dialog_content = "<color=#e8d9bb>ピーッ…</color>",
  ui_story_5028_50281201_8_dialog_content = "聞いたか、命令だ。",
  ui_story_5028_50281201_9_dialog_content = "何だって？何て言ってる？",
  ui_story_5028_50281201_10_dialog_content = "<color=#e8d9bb>ピー…ピュー…</color>",
  ui_story_5028_50281201_11_dialog_content = "て…敵襲だ！",
  ui_story_5028_50281201_12_dialog_content = "西北の方角！",
  ui_story_5028_50281201_13_dialog_content = "急げ！",
  ui_story_5028_50281201_14_dialog_content = "ふぅ…ふぅ…どこに敵がいるってんだ？",
  ui_story_5028_50281201_15_dialog_content = "どういうことだ、誰もいねえじゃねえか！？",
  ui_story_5028_50281201_16_dialog_content = "<color=#e8d9bb>ピピピ…ピー</color>",
  ui_story_5028_50281201_17_dialog_content = "どういうことだ？\n今度は朝飯の合図だぞ！？",
  ui_story_5028_50281201_18_dialog_content = "遊んでるのは誰だ！？",
  ui_story_5028_50281201_19_dialog_content = "よかった、一段目の作戦は大成功！",
  ui_story_5028_50281201_20_dialog_content = "レビィが敵の暗号表を\n盗んできてくれたおかげだ…",
  ui_story_5028_50281201_21_dialog_content = "暗号表を食べたペコペコウサギの手柄でもあるよ！",
  ui_story_5028_50281201_22_dialog_content = "ペコペコ！",
  ui_story_5028_50281201_23_dialog_content = "空の末裔、後は任せたよ！",
  ui_story_5028_50281201_24_dialog_content = "恥ずかしい話だけど、\n何度も事件に巻き込まれるうちに――",
  ui_story_5028_50281201_25_dialog_content = "逃げ足だけは、\n大きく進歩したんだ！",
  ui_story_5028_50281201_26_dialog_content = "やい！！そこののろま！！\n捕まえられるものなら、捕まえてみろ！！",
  ui_story_5028_50281201_27_dialog_content = "何だ！？アイツら、逃げやがったのか？",
  ui_story_5028_50281201_28_dialog_content = "おい、待て！",
  ui_story_5028_50281201_29_dialog_content = "ヒィ…ヒィ…",
  ui_story_5028_50281201_30_dialog_content = "こっちでいいんだよね。\nキャロの棲息地は、そう遠くないはず…",
  ui_story_5028_50281201_31_dialog_content = "ここに来る前に、\nソラヴァンを近くに停めてあるんだ。それに…",
  ui_story_5028_50281201_32_dialog_content = "ソラヴァンをしつこく\n追いかけ回してるヤツも、まだいるはず！",
  ui_story_5028_50281201_33_dialog_content = "ガオオォ――！",
  ui_story_5028_50281201_34_dialog_content = "おい、あれを見ろ！",
  ui_story_5028_50281201_35_dialog_content = "なんだと！？\nドラゴライオンがなんでもう一匹いるんだ！？",
  ui_story_5028_50281201_36_dialog_content = "ガオオォォォ――！！",
  ui_story_5028_50281201_37_dialog_content = "うわあああ！！！",
  ui_story_5028_50281201_38_dialog_content = "急いで親分に報告しろ！",
  ui_story_5028_50281201_39_dialog_content = "わ、分かった！",
  ui_story_5028_50281201_40_dialog_content = "おかしいぞ…ドラゴライオンは行っちまったのに、\nなんでまだこんなに暗いんだ？",
  ui_story_5028_50281201_41_dialog_content = "うわああああ！",
  ui_story_5028_50281201_42_dialog_content = "ハイハイ、ハ～イ！",
  ui_story_5028_50281201_43_dialog_content = "分かった、分かったって。\n今度はあんなに大きな石を食べさせたりしないから…",
  ui_story_5028_50281201_44_dialog_content = "誰が叫んでるんだ！？\n何が起こった！？",
  ui_story_5028_50281201_45_dialog_content = "うわぁ！",
  ui_story_5028_50281201_46_dialog_content = "モチモチ…",
  ui_story_5028_50281201_47_dialog_content = "なんだこりゃ…？\nなんで地面がこんなに…",
  ui_story_5028_50281201_48_dialog_content = "ホウ！？",
  ui_story_5028_50281201_49_dialog_content = "こ、今度はなんだ！？",
  ui_story_5028_50281201_50_dialog_content = "なんで…こんなに眠…",
  ui_story_5028_50281201_51_dialog_content = "すぅ…",
  ui_story_5028_50281201_52_dialog_content = "順調なようね。",
  ui_story_5028_50281201_53_dialog_content = "あの子たち、しっかりかき回してるみたいじゃない。",
  ui_story_5028_50281201_54_dialog_content = "あなた、見た目のわりに\nなかなかやるみたいね。",
  ui_story_5028_50281201_55_dialog_content = "フィアは俺の弟子だからな。\n優秀で当然だ。",
  ui_story_5028_50281201_56_dialog_content = "あたしは「珍獣マスター」だもん！\nこれぐらい、簡単に決まってるでしょ！",
  ui_story_5028_50281201_57_dialog_content = "追われてないよ。",
  ui_story_5028_50281201_58_dialog_content = "PlayerName、待ってて。\nおいらが縄を解いてあげる。",
  ui_story_5028_50281201_59_dialog_content = "ふぅ…ありがとう。",
  ui_story_5028_50281201_60_dialog_content = "ルルル！",
  ui_story_5028_50281201_61_dialog_content = "キャロ！よかった、ケガはない？",
  ui_story_5028_50281201_62_dialog_content = "作戦第一段階は大成功！",
  ui_story_5028_50281201_63_dialog_content = "次はゲイリーを見つけて、\n陰謀を止めなくちゃ。",
  ui_story_5028_50281201_64_dialog_content = "フィア。",
  ui_story_5028_50281201_65_dialog_content = "そ、その目は何…？",
  ui_story_5028_50281201_66_dialog_content = "バカにしないで！",
  ui_story_5028_50281201_67_dialog_content = "バカになんてしていないわ。",
  ui_story_5028_50281201_68_dialog_content = "まだまだ子供みたいね。",
  ui_story_5028_50281201_69_dialog_content = "言ったでしょ、あたしは子供じゃない！",
  ui_story_5028_50281201_70_dialog_content = "珍獣マスターって呼んで！",
  ui_story_5028_50281201_71_dialog_content = "呼び方はどうでもいいでしょ。\n覚えるのも面倒だわ。",
  ui_story_5028_50281201_72_dialog_content = "あんたね――！",
  ui_story_5028_50281201_73_dialog_content = "でも、あなたは、側にいる珍獣たちのことをよく理解してるって、\n行動で証明してみせた。",
  ui_story_5028_50281201_74_dialog_content = "見直したわ。",
  ui_story_5028_50281201_75_dialog_content = "えっ？",
  ui_story_5028_50281201_76_dialog_content = "あたしを認めてくれたってこと？",
  ui_story_5028_50281201_77_dialog_content = "トーゼンよね！細かいことは覚えてなくても、\nあたしには才能があるの！",
  ui_story_5028_50281201_78_dialog_content = "仲間のことは、\nちゃんと理解してるんだから！",
  ui_story_5028_50281201_79_dialog_content = "フフフフ…珍獣マスターのすごさを思い知ったでしょ？",
  ui_story_5028_50281201_80_dialog_content = "得意になるのはまだ早いわ。\n私が認めるには、まだまだ未熟よ。",
  ui_story_5028_50281201_81_dialog_content = "その前に、まずは…",
  ui_story_5028_50281201_82_dialog_content = "騒がしいと思ったら、\nお前たちだったか。",
  ui_story_5028_50281201_83_dialog_content = "ルルル！！",
  ui_story_5028_50281201_84_dialog_content = "戻って来た！",
  ui_story_5028_50281201_85_dialog_content = "こいつがユウカイハン？",
  ui_story_5028_50281201_86_dialog_content = "暗鬼を従えるなんて、まったく趣味が悪いわね。",
  ui_story_5028_50281201_87_dialog_content = "へー、あたしもドーカンだね。珍しく。",
  ui_story_5028_50281201_88_dialog_content = "誰と意見が同じですって！？",
  ui_story_5028_50281201_89_dialog_content = "何か気分の悪いヤローだし、\nパーッと隠れ家ごと焼き払う？",
  ui_story_5028_50281201_90_dialog_content = "おいおい、そりゃダメだ。",
  ui_story_5028_50281201_91_dialog_content = "キャロがたくさん捕まってるんだ。\n焼き払っちまったら、無事じゃすまん。",
  ui_story_5028_50281201_92_dialog_content = "ん？なんだ、仲間が増えているようだな。\nそこのモヤシの仲間か？",
  ui_story_5028_50281201_93_dialog_content = "僕はモヤシじゃない！",
  ui_story_5028_50281201_94_dialog_content = "どいつもこいつも、\nなんだって畜生どものために戦うのだろうな。",
  ui_story_5028_50281201_95_dialog_content = "この子たちは畜生じゃない！\n仲間なんだよ！",
  ui_story_5028_50281201_96_dialog_content = "仲間？クク…アハハハ！\nいや、こいつらは畜生さ。",
  ui_story_5028_50281201_97_dialog_content = "お前が仲間と思っていても、\n向こうはそうとは限らないぞ。",
  ui_story_5028_50281201_98_dialog_content = "一見無害でも、\n畜生はしょせん畜生に過ぎん。",
  ui_story_5028_50281201_99_dialog_content = "お前の利用価値が無くなれば、\n何の情けもなく、お前は捨てられ、殺される。",
  ui_story_5028_50281201_100_dialog_content = "そんなことない！",
  ui_story_5028_50281201_101_dialog_content = "ちょっと、そこのお子様？",
  ui_story_5028_50281201_102_dialog_content = "フィアだよ！",
  ui_story_5028_50281201_103_dialog_content = "どうでもいいわ。\nこいつはもう、恨みで訳が分からなくなってるのよ。",
  ui_story_5028_50281201_104_dialog_content = "説得なんて、すごく面倒だわ。\nもっと直接的な方法で解決しましょ…",
  ui_story_5028_50281201_105_dialog_content = "それって？",
  ui_story_5028_50281201_106_dialog_content = "つまり…",
  ui_story_5028_50281201_107_dialog_content = "力づくで。",
  ui_story_5028_50281201_108_dialog_content = "実にシーラらしい答えだ。",
  ui_story_5028_50281201_109_dialog_content = "戦うつもりか？",
  ui_story_5028_50281201_110_dialog_content = "ハハハ、いいだろう…",
  ui_story_5028_50281201_111_dialog_content = "1度目も2度目も同じだ。\nお前たちは永遠に勝てない。",
  ui_story_5028_50281201_112_dialog_content = "グオオ！！！",
  ui_story_5028_50281202_1_dialog_content = "キャロ、やっちゃえ！",
  ui_story_5028_50281202_2_dialog_content = "ルルル！！",
  ui_story_5028_50281202_3_dialog_content = "遅いな。",
  ui_story_5028_50281202_4_dialog_content = "グオオオ！",
  ui_story_5028_50281202_5_dialog_content = "レビィ、フィアを守って！",
  ui_story_5028_50281202_6_dialog_content = "させない！",
  ui_story_5028_50281202_7_dialog_content = "ファイアロープ！",
  ui_story_5028_50281202_8_dialog_content = "どう？あたしの仲間は！\nなかなかのチームワークでしょ？",
  ui_story_5028_50281202_9_dialog_content = "ふむ…",
  ui_story_5028_50281202_10_dialog_content = "しょせんは小手先の連携だ。\nこの程度ではな。",
  ui_story_5028_50281202_11_dialog_content = "だが、そちらの光霊たちは、\n確かに厄介なようだ。",
  ui_story_5028_50281202_12_dialog_content = "ならば、これはどうだ？",
  ui_story_5028_50281202_13_dialog_content = "鞭から<color=#FFB400>怪しい光</color>が出てる！？",
  ui_story_5028_50281202_14_dialog_content = "気を付けて！",
  ui_story_5028_50281202_15_dialog_content = "ル…ル…！",
  ui_story_5028_50281202_16_dialog_content = "キャロ！？キャロ！！",
  ui_story_5028_50281202_17_dialog_content = "ペコ…",
  ui_story_5028_50281202_18_dialog_content = "何をしたの！？",
  ui_story_5028_50281202_19_dialog_content = "そう焦るな。",
  ui_story_5028_50281202_20_dialog_content = "もう少しすれば、お前の可愛い仲間たちが、\nお前を八つ裂きにしてくれるさ。",
  ui_story_5028_50281202_21_dialog_content = "あたしの仲間はそんなことしない！",
  ui_story_5028_50281202_22_dialog_content = "あの鞭を狙って！",
  ui_story_5028_50281202_23_dialog_content = "分かった！",
  ui_story_5028_50281202_24_dialog_content = "あっ！",
  ui_story_5028_50281202_25_dialog_content = "一体どれだけの暗鬼を操ってるの…！？",
  ui_story_5028_50281202_26_dialog_content = "暗鬼など、欲しいだけ手に入る。",
  ui_story_5028_50281202_27_dialog_content = "いくら死のうが、\n次がいくらでも補充できるからな。",
  ui_story_5028_50281202_28_dialog_content = "皆、一斉に行くよ！",
  ui_story_5028_50281202_29_dialog_content = "<color=#e8d9bb>ルルル！</color>",
  ui_story_5028_50281202_30_dialog_content = "キャロの鳴き声？",
  ui_story_5028_50281202_31_dialog_content = "<color=#e8d9bb>ルルルル！</color>",
  ui_story_5028_50281202_32_dialog_content = "違う、あたしのキャロじゃない！",
  ui_story_5028_50281202_33_dialog_content = "キャロの鳴き声があたり全部から聞こえてくる！",
  ui_story_5028_50281202_34_dialog_content = "面倒ね…",
  ui_story_5028_50281202_35_dialog_content = "さっきのでフィアの連れてる珍獣以外も、\n全部操ろうとしてたってことでしょうね。",
  ui_story_5028_50281202_36_dialog_content = "はーん、そりゃよくないな…",
  ui_story_5028_50281202_37_dialog_content = "キャロたちを置いて行くワケにはいかないよ！\n誰かが逃がしてあげないと…",
  ui_story_5028_50281202_38_dialog_content = "シーラ先輩！",
  ui_story_5028_50281202_39_dialog_content = "…何？",
  ui_story_5028_50281202_40_dialog_content = "珍獣のことよく理解してるって、言ってたでしょ？",
  ui_story_5028_50281202_41_dialog_content = "今、先輩はケガをしてるし、戦えない。\nだから、あの子たちを連れて逃げて！",
  ui_story_5028_50281202_42_dialog_content = "死に際でも、\nまだ畜生どもを気にかけるのか？",
  ui_story_5028_50281202_43_dialog_content = "まったく、おかしな奴らだ。",
  ui_story_5028_50281202_44_dialog_content = "グオォォ――！",
  ui_story_5028_50281202_45_dialog_content = "かかれ！",
  ui_story_5028_50281202_46_dialog_content = "うわっ！！",
  ui_story_5028_50281202_47_dialog_content = "今度はいくつ縛り上げられたかしら？\n1、2、3…",
  ui_story_5028_50281202_48_dialog_content = "ま、十分ね。",
  ui_story_5028_50281202_49_dialog_content = "どいつもこいつもトロいんだよ！\nやっぱ、一気に燃やしたほうがスカッとするんだよね。",
  ui_story_5028_50281202_50_dialog_content = "そう？だったら、\nどちらがたくさん倒せるか、試してみる？",
  ui_story_5028_50281202_51_dialog_content = "ルルルル！！！",
  ui_story_5028_50281202_52_dialog_content = "ヴィックに聞いてないの？\n珍獣たちは、私に近づきたがらないの。",
  ui_story_5028_50281202_53_dialog_content = "だったら、あたしが教えてあげる！\nそれは昔の話！",
  ui_story_5028_50281202_54_dialog_content = "どういうこと…？",
  ui_story_5028_50281202_55_dialog_content = "おいで、ドラゴライオン！",
  ui_story_5028_50281202_56_dialog_content = "ガオオ！",
  ui_story_5028_50281202_57_dialog_content = "（フィアが…ドラゴライオンを呼び寄せた）",
  ui_story_5028_50281202_58_dialog_content = "ガォ…",
  ui_story_5028_50281202_59_dialog_content = "怖いかもしれないけど、ごめんね。\nでも、お願い…",
  ui_story_5028_50281202_60_dialog_content = "シーラ先輩を連れて、森の中にいる珍獣たちを探しに行って！\nそれから、皆を連れて、ここを離れて！",
  ui_story_5028_50281202_61_dialog_content = "シーラ先輩！",
  ui_story_5028_50281202_62_dialog_content = "…",
  ui_story_5028_50281202_63_dialog_content = "（シーラが竜に少しずつ近づいていく…）",
  ui_story_5028_50281202_64_dialog_content = "…！",
  ui_story_5028_50281202_65_dialog_content = "（ドラゴライオンが逃げない！）",
  ui_story_5028_50281202_66_dialog_content = "まさか、本当に…",
  ui_story_5028_50281202_67_dialog_content = "「珍獣マスター」様に感謝しなさい！！",
  ui_story_5028_50281202_68_dialog_content = "ほら、早く行って！",
  ui_story_5028_50281202_69_dialog_content = "ハハ……ハハハハ……",
  ui_story_5028_50281202_70_dialog_content = "何がおかしいんだろう？",
  ui_story_5028_50281202_71_dialog_content = "お前たちはやはり、\nどうしようもないガキどもだな。",
  ui_story_5028_50281202_72_dialog_content = "畜生どもとモヤシを引き連れて、\n俺の邪魔をするとは…",
  ui_story_5028_50281202_73_dialog_content = "一番面白いものは最後に残しておけ、というが…",
  ui_story_5028_50281202_74_dialog_content = "少しぐらい、早めにお披露目してもいいか。",
  ui_story_5028_50281202_75_dialog_content = "出てこい。",
  ui_story_5028_50281202_76_dialog_content = "ル…",
  ui_story_5028_50281202_77_dialog_content = "これって、キャロの鳴き声…？",
  ui_story_5028_50281202_78_dialog_content = "さっきのあのキャロ！？",
  ui_story_5028_50281202_79_dialog_content = "そ、そんなことで\nあたしがひるむと思ったら、大間違いだよ！",
  ui_story_5028_50281202_80_dialog_content = "ルルル！",
  ui_story_5028_50281202_81_dialog_content = "きゃあ！？",
  ui_story_5028_50281202_82_dialog_content = "こ…これって、どう見ても…暗鬼でしょ！？",
  ui_story_5028_50281202_83_dialog_content = "どうして…キャロの鳴き声で…",
  ui_story_5028_50281202_84_dialog_content = "ルルル…ルル！",
  ui_story_5028_50281202_85_dialog_content = "こいつは、確かにあのキャロだ。",
  ui_story_5028_50281202_86_dialog_content = "キャロの持つ最も大きな力…\nそれは<color=#FFB400>「擬態」</color>だ。",
  ui_story_5028_50281202_87_dialog_content = "仲間に刺激されると、どんな生き物の姿にも変わることができて…\n能力もそっくりそのまま使える。",
  ui_story_5028_50281202_88_dialog_content = "そういう大事なことは、\nもっと早く言ってくださいよ！？",
  ui_story_5028_50281202_89_dialog_content = "いやいや、俺もキャロが怖がってる状態で、\nこの力を使えるとは思ってなかったんだよ。",
  ui_story_5028_50281202_90_dialog_content = "本来、キャロってのは、\n自分の信用する仲間のためだけに能力を使うんだ。",
  ui_story_5028_50281202_91_dialog_content = "こいつはとんでもなく面倒なことになって来たな。",
  ui_story_5028_50281202_92_dialog_content = "笑ってる場合ですか！？",
  ui_story_5028_50281202_93_dialog_content = "見るからに強そうですよ！\n何か方法は…",
  ui_story_5028_50281202_94_dialog_content = "よくぞ俺に聞いてくれた！",
  ui_story_5028_50281202_95_dialog_content = "キャロは希少な珍獣だ。\nキャロの信頼を得られれば、誰もかなわない…",
  ui_story_5028_50281202_96_dialog_content = "つまり、キャロに対抗できるのは、\nキャロしかないってことさ。",
  ui_story_5028_50281301_1_dialog_content = "ルルル！",
  ui_story_5028_50281301_2_dialog_content = "ルル！",
  ui_story_5028_50281301_3_dialog_content = "こいつ…どうしてこんなに強いの！？",
  ui_story_5028_50281301_4_dialog_content = "もっとあがけ！\n恐怖を深く刻みつけるんだ！",
  ui_story_5028_50281301_5_dialog_content = "これから、こいつらが、\nアストラ大陸を隅々まで踏みにじるぞ！",
  ui_story_5028_50281301_6_dialog_content = "ハハ…ハハハハ…！",
  ui_story_5028_50281301_7_dialog_content = "ここまでだな、ガキ…",
  ui_story_5028_50281301_8_dialog_content = "今だ、PlayerName！",
  ui_story_5028_50281301_9_dialog_content = "君の力を使って、\nフィアの信頼をキャロに伝えろ！",
  ui_story_5028_50281301_10_dialog_content = "え？ぼ、僕の力！？",
  ui_story_5028_50281301_11_dialog_content = "頭を使え！考えてみろ！！",
  ui_story_5028_50281301_12_dialog_content = "（僕の力…）",
  ui_story_5028_50281301_13_dialog_content = "（僕にできる事と言えば、\n感知能力で、皆の意識をつなぐこと…）",
  ui_story_5028_50281301_14_dialog_content = "（…フィアは、キャロだけは何を考えてるか、\n分からないって言ってた。まさか…）",
  ui_story_5028_50281301_15_dialog_content = "キャロの考えと気持ちを感知して、\nフィアにつなげるんだよ。",
  ui_story_5028_50281301_16_dialog_content = "その後のことは、\nフィアの才能があれば解決できるさ！",
  ui_story_5028_50281301_17_dialog_content = "僕にキャロの考えが感知できるってこと？",
  ui_story_5028_50281301_18_dialog_content = "もちろんだ！忘れるな。\n君は空の末裔なんだぞ！",
  ui_story_5028_50281301_19_dialog_content = "そ、そうですね…やってみます！",
  ui_story_5028_50281301_20_option_content = "強制感知！",
  ui_story_5028_50281301_21_dialog_content = "キャロの考えを感知…",
  ui_story_5028_50281301_22_dialog_content = "ル、ルル！",
  ui_story_5028_50281301_23_dialog_content = "すごく焦ってる。\n何かの力が抑えられていて、使えないみたいだ…",
  ui_story_5028_50281301_24_dialog_content = "ルル！",
  ui_story_5028_50281301_25_dialog_content = "この気持ち…守りたいってことかな？",
  ui_story_5028_50281301_26_dialog_content = "守りたい…何を？そうか…",
  ui_story_5028_50281301_27_dialog_content = "フィア！キャロが君を守りたいって思ってる！",
  ui_story_5028_50281301_28_dialog_content = "えっ！？",
  ui_story_5028_50281301_29_dialog_content = "ルルル！",
  ui_story_5028_50281301_30_dialog_content = "これって、そういう意味なの！？",
  ui_story_5028_50281301_31_dialog_content = "ルル、ルル！",
  ui_story_5028_50281301_32_dialog_content = "そうだって言ってる。\nあと、すごくあせってる！",
  ui_story_5028_50281301_33_dialog_content = "あせる気持ち…鳴き声…",
  ui_story_5028_50281301_34_dialog_content = "そういう意味だったんだね。",
  ui_story_5028_50281301_35_dialog_content = "分かった…フィア、全部分かったよ！",
  ui_story_5028_50281301_36_dialog_content = "「分かった」？何が？",
  ui_story_5028_50281301_37_dialog_content = "教えてくれたおかげで、\nキャロの鳴き声の意味が分かったんだよ。",
  ui_story_5028_50281301_38_dialog_content = "キャロの言葉が分かるようになったってこと！",
  ui_story_5028_50281301_39_dialog_content = "本当に！？",
  ui_story_5028_50281301_40_dialog_content = "ルルル！ルル、ル！！！",
  ui_story_5028_50281301_41_dialog_content = "な、なんて言ってるの？",
  ui_story_5028_50281301_42_dialog_content = "「僕がフィアを守る」だって！",
  ui_story_5028_50281301_43_dialog_content = "ルルル！！",
  ui_story_5028_50281301_44_dialog_content = "なーに？あたしと気持ちが通じて、\n新しい力が湧いたって？",
  ui_story_5028_50281301_45_dialog_content = "だったら、早く使って！",
  ui_story_5028_50281301_46_dialog_content = "キャロが光りだした！？",
  ui_story_5028_50281301_47_dialog_content = "キャロの様子が…！？",
  ui_story_5028_50281301_48_dialog_content = "フィア、キャロ！\nその力を使って、ゲイリーを倒せ！",
  ui_story_5028_50281301_49_dialog_content = "言われなくても分かってる！",
  ui_story_5028_50281301_50_dialog_content = "お前たちごときが、俺を倒すだと？\n寝言もほどほどにするがいい！",
  ui_story_5028_50281301_51_dialog_content = "行け、やつらを粉々につぶしてしまえ！",
  ui_story_5028_50281301_52_dialog_content = "グォォ――！",
  ui_story_5028_50281301_53_dialog_content = "ルルル！",
  ui_story_5028_50281302_1_dialog_content = "行って、キャロ！あたしたちはそう簡単にやられないって、\n思い知らせてやりなさい！",
  ui_story_5028_50281302_2_dialog_content = "ルルル！",
  ui_story_5028_50281302_3_dialog_content = "そ、そんな…まさか！？",
  ui_story_5028_50281302_4_dialog_content = "ル！ルルル！",
  ui_story_5028_50281302_5_dialog_content = "ゲイリーのキャロが、辛そうだ…",
  ui_story_5028_50281302_6_dialog_content = "キャロ…",
  ui_story_5028_50281302_7_dialog_content = "キャロ！ゲイリーの鞭を狙って！",
  ui_story_5028_50281302_8_dialog_content = "ルルル！！",
  ui_story_5028_50281302_9_dialog_content = "うっ！！",
  ui_story_5028_50281302_10_dialog_content = "今だ！",
  ui_story_5028_50281302_11_dialog_content = "おいらに任せて！",
  ui_story_5028_50281302_12_dialog_content = "燃えろ！",
  ui_story_5028_50281302_13_dialog_content = "ファイアロープ！",
  ui_story_5028_50281302_14_dialog_content = "暗鬼は、全部片づけたよ！",
  ui_story_5028_50281302_15_dialog_content = "最後の1人も私が縛りあげておいたわ。\n勝利は私のものよ。",
  ui_story_5028_50281302_16_dialog_content = "ジュヌヴィエーヴちゃん、\nいいとこどりは感心しねーなー…",
  ui_story_5028_50281302_17_dialog_content = "先にあたしがそいつをツブしたんだし。",
  ui_story_5028_50281302_18_dialog_content = "アンタは鞭のあとを付けただけじゃん？",
  ui_story_5028_50281302_19_dialog_content = "全員倒せた…？",
  ui_story_5028_50281302_20_dialog_content = "うまくいったの…？",
  ui_story_5028_50281302_21_dialog_content = "ルルル！",
  ui_story_5028_50281302_22_dialog_content = "イエ～イ！",
  ui_story_5028_50281302_23_dialog_content = "クソッ…",
  ui_story_5028_50281302_24_dialog_content = "ゲイリーのキャロが自由になった！",
  ui_story_5028_50281302_25_dialog_content = "PlayerName、フィアの心の声を、\nあのキャロにも伝えてやってくれ！さっきと同じだ！",
  ui_story_5028_50281302_26_dialog_content = "うん！",
  ui_story_5028_50281302_27_option_content = "強制感知！",
  ui_story_5028_50281302_28_dialog_content = "あなた、キャロと同じ種族だよね？",
  ui_story_5028_50281302_29_dialog_content = "アイツのことは、\nもう怖がらなくていいよ。",
  ui_story_5028_50281302_30_dialog_content = "あいつの術は解いたから、\nこれからは誰もあなたに、嫌なことを無理やりさせたりしない！",
  ui_story_5028_50281302_31_dialog_content = "もう戦う必要はないんだよ。\nあたしたちと一緒に行こう！",
  ui_story_5028_50281302_32_dialog_content = "珍獣マスターのあたしが、\n守ってあげる！",
  ui_story_5028_50281302_33_dialog_content = "ル…ル？",
  ui_story_5028_50281302_34_dialog_content = "ルルル！",
  ui_story_5028_50281302_35_dialog_content = "安心して、あたしはあっちの悪いおじさんと違って、\nあなたを大切にするから！",
  ui_story_5028_50281302_36_dialog_content = "…",
  ui_story_5028_50281302_37_dialog_content = "まずいな。ゲイリーに乱暴に扱われてきたせいで、\n心も身体も壊れかけてるんだ。",
  ui_story_5028_50281302_38_dialog_content = "早いとこ、ここから連れ出して、\nゆっくり休ませないと…",
  ui_story_5028_50281302_39_dialog_content = "俺の復讐も、俺の恨みも…お前たちのような何も知らん奴らに、\n簡単に壊されてたまるか！！",
  ui_story_5028_50281302_40_dialog_content = "立て、この畜生め！！",
  ui_story_5028_50281302_41_dialog_content = "まだ終わってない！",
  ui_story_5028_50281302_42_dialog_content = "ル…ル…！",
  ui_story_5028_50281302_43_dialog_content = "こっちのキャロ…\nずっと痛いって、叫んでたんだね…",
  ui_story_5028_50281302_44_dialog_content = "止めなさい！！！",
  ui_story_5028_50281302_45_dialog_content = "痛がってるでしょ！？",
  ui_story_5028_50281302_46_dialog_content = "「痛い」？",
  ui_story_5028_50281302_47_dialog_content = "それでいいんだ！",
  ui_story_5028_50281302_48_dialog_content = "痛いからこそ、こいつは俺をおそれる。",
  ui_story_5028_50281302_49_dialog_content = "おそれがなければ、\nこいつらの力を最大限発揮させることはできない。",
  ui_story_5028_50281302_50_dialog_content = "力を出しきれ！\nやつらを叩きのめすんだ！",
  ui_story_5028_50281302_51_dialog_content = "さもないと、\nまたひどい目に遭わせるぞ！",
  ui_story_5028_50281302_52_dialog_content = "ルル、ル――",
  ui_story_5028_50281302_53_dialog_content = "ルルル！",
  ui_story_5028_50281302_54_dialog_content = "ど、どうすればいいの？\n助けて欲しいって…",
  ui_story_5028_50281302_55_dialog_content = "もう1回、倒せばいいの！？",
  ui_story_5028_50281302_56_dialog_content = "ルルル！",
  ui_story_5028_50281302_57_dialog_content = "止めろ、フィア！",
  ui_story_5028_50281302_58_dialog_content = "あのキャロは、もう相当弱ってる！\nこれ以上の攻撃には耐えられない！",
  ui_story_5028_50281302_59_dialog_content = "じゃ、じゃあ、どうすればいいのか教えてよ、\nダメ師匠！",
  ui_story_5028_50281302_60_dialog_content = "うーん…ここまで来たら、\nもう天に助けてもらえるように祈るしか…",
  ui_story_5028_50281302_61_dialog_content = "信じたあたしがバカだった！",
  ui_story_5028_50281302_62_dialog_content = "ハハハ…祈るがいい！\nお前たちの最後のチャンスだ。",
  ui_story_5028_50281302_63_dialog_content = "その後は――",
  ui_story_5028_50281302_64_dialog_content = "…ケンカって、一番疲れるのよね…",
  ui_story_5028_50281302_65_dialog_content = "どこだ！？",
  ui_story_5028_50281302_66_dialog_content = "だけど、あなたみたいなクズを逃がしたら、\nあとあともっと面倒なことになりそうね！",
  ui_story_5028_50281302_67_dialog_content = "ガオオォォォ――",
  ui_story_5028_50281302_68_dialog_content = "うっ！この俺が、まさか…",
  ui_story_5028_50281302_69_option_content = "文字通り、天からの助け…！？\nシーラ！！",
  ui_story_5028_50281302_70_option_content = "空から降りてきて、\nゲイリーを蹴飛ばした！！",
  ui_story_5028_50281302_71_dialog_content = "天の助けなんてないわ。",
  ui_story_5028_50281302_72_dialog_content = "私は1回1回、努力してきただけ。\n積み重ねが変化をもたらしたのよ。",
  ui_story_5028_50281302_73_dialog_content = "シーラ先輩――！",
  ui_story_5028_50281302_74_dialog_content = "フ…フフン！！あたしの作戦大成功ね！！\nシーラ先輩たちに他の動物を助けに行ってもらっておいて、良かった！",
  ui_story_5028_50281302_75_dialog_content = "おかげで、ゲイリーの野望が阻止できたもんね！",
  ui_story_5028_50281302_76_dialog_content = "はあ…あなたって子は、\n成長したというべきか、少しも成長してないというべきか…",
  ui_story_5028_50281302_77_dialog_content = "ル…",
  ui_story_5028_50281302_78_dialog_content = "うわあっ！？",
  ui_story_5028_50281302_79_dialog_content = "ルル！？",
  ui_story_5028_50281302_80_dialog_content = "この子、ゲイリーに\n相当痛めつけられてきたようね。",
  ui_story_5028_50281302_81_dialog_content = "休ませてあげましょ。",
  ui_story_5028_50281302_82_dialog_content = "ところで、こいつの処分は、\nどうするの？",
  ui_story_5028_50281302_83_dialog_content = "ゴホゴホッ…！\nぐっ…",
  ui_story_5028_50281302_84_dialog_content = "（シーラが腕1本でゲイリーの襟元をつかんでる…）",
  ui_story_5028_50281302_85_dialog_content = "（しかも、すごい殺気だ！）",
  ui_story_5028_50281302_86_dialog_content = "（背筋が凍りそうなほど、\nビンビンに伝わってくる…）",
  ui_story_5028_50281302_87_dialog_content = "ルルル…",
  ui_story_5028_50281302_88_dialog_content = "ハハハ…この俺が…失敗するとはな…",
  ui_story_5028_50281302_89_dialog_content = "さっさと殺せ…",
  ui_story_5028_50281302_90_dialog_content = "結局、畜生どもに殺されるのが\n俺の宿命だったのかもしれんな…",
  ui_story_5028_50281302_91_dialog_content = "こいつを活かしておいたら、\n面倒にしかならないわ。",
  ui_story_5028_50281302_92_dialog_content = "いっそ、ひと思いに…",
  ui_story_5028_50281302_93_dialog_content = "それについては、\nまずは今回の最大の功労者――フィアの意見を聞こうじゃないか。",
  ui_story_5028_50281302_94_dialog_content = "…",
  ui_story_5028_50281302_95_dialog_content = "フィア？",
  ui_story_5028_50281302_96_dialog_content = "トーゼン、こいつには牢屋に入ってもらうよ！",
  ui_story_5028_50281302_97_dialog_content = "…",
  ui_story_5028_50281302_98_dialog_content = "フン、牢屋だと？",
  ui_story_5028_50281302_99_dialog_content = "出たら、俺はまた同じように、\n畜生どもに復讐するぞ。",
  ui_story_5028_50281302_100_dialog_content = "それなら、「珍獣マスター」のあたしが\nもう一度阻止する！",
  ui_story_5028_50281302_101_dialog_content = "「珍獣マスター」のあたしの保護のもとで、\n珍獣が無事にたくましく育っていくのを見るのが――",
  ui_story_5028_50281302_102_dialog_content = "あんたにとって一番の罰になるでしょ！",
  ui_story_5028_50281302_103_dialog_content = "ああ、実に素晴らしいね。",
  ui_story_5028_50281302_104_dialog_content = "うわあ！？\nタ、タコ男！？シーラ先輩と同じ！？",
  ui_story_5028_50281302_105_dialog_content = "そんな風に呼ばれると、傷付くね。",
  ui_story_5028_50281302_106_dialog_content = "クレーケン、君が来たってことは、\nシャドウマスターが…",
  ui_story_5028_50281302_107_dialog_content = "実に奇遇だね、PlayerName。君たちが捕まえたのは、\nシャドウマスターが探していた人物なんだよ。",
  ui_story_5028_50281302_108_dialog_content = "これだけ面倒なことをやっていて、\n目を付けられてない方がおかしいわね。",
  ui_story_5028_50281302_109_dialog_content = "そのお嬢さんの言う通りだよ。",
  ui_story_5028_50281302_110_dialog_content = "ゲイリー、君の奥さんは10年前に誤って珍獣の縄張りに入り、\n凶暴な珍獣にケガをさせられて亡くなったそうだね。",
  ui_story_5028_50281302_111_dialog_content = "君があちこちで珍獣狩りを始めたのは、その後だ。",
  ui_story_5028_50281302_112_dialog_content = "単なる狩りであれば、\nシャドウマスターも干渉などしないが…",
  ui_story_5028_50281302_113_dialog_content = "君の行為は一線を越えて、\n影ノ街を脅かした。",
  ui_story_5028_50281302_114_dialog_content = "影ノ街を？\nそんなにおおごとだったの？",
  ui_story_5028_50281302_115_dialog_content = "そうだよ、お嬢さん。",
  ui_story_5028_50281302_116_dialog_content = "影ノ街の周りには、たくさんの珍獣が棲息している。\n街の安全にとって重要な存在なんだ。",
  ui_story_5028_50281302_117_dialog_content = "珍獣たちは自分たちの縄張りを守るために、\n他の脅威になる生物を追い払う。その中には暗鬼も含まれるんだ。",
  ui_story_5028_50281302_118_dialog_content = "そうやって、影ノ街の周囲に見えない壁を作って、\n暗鬼と光霊の世界の壁になってくれているのさ。",
  ui_story_5028_50281302_119_dialog_content = "そんな珍獣たちが消えてしまったら、\n影ノ街は暗鬼の侵入を直接受けることになってしまう。",
  ui_story_5028_50281302_120_dialog_content = "あ、そういうことか…",
  ui_story_5028_50281302_121_dialog_content = "ハッ、シャドウマスターだと？",
  ui_story_5028_50281302_122_dialog_content = "シャドウマスターに俺を捕まえる力があるなら、\nなんであの時、畜生どもを追い払って、俺の家族を守らなかったんだ？",
  ui_story_5028_50281302_123_dialog_content = "俺の家族は、お前たちのいう「ルール」の中で\n生きてた者じゃないというのか！？",
  ui_story_5028_50281302_124_dialog_content = "シャドウマスターは影ノ街のルールであって、\n森のルールではないんだよ。",
  ui_story_5028_50281302_125_dialog_content = "ルールに守られたければ、ルールを守らないとね。",
  ui_story_5028_50281302_126_dialog_content = "ふん！口だけは達者だな。",
  ui_story_5028_50281302_127_dialog_content = "ゲイリー…",
  ui_story_5028_50281302_128_dialog_content = "なんだ？お前まで俺に説教か？",
  ui_story_5028_50281302_129_dialog_content = "それとも、俺がお前をだましていたから、\n復讐しようとでもいうのか？",
  ui_story_5028_50281302_130_dialog_content = "フン、好きなようにしろ。\nお前に何と言われようと、俺の考えは変わらない。",
  ui_story_5028_50281302_131_dialog_content = "誰も俺を止められない、誰にもな！",
  ui_story_5028_50281302_132_dialog_content = "それは君が決めることじゃないよ。",
  ui_story_5028_50281302_133_dialog_content = "珍獣たちを互いに殺し合うように訓練し、\n最終的には、この世界からすべての珍獣を抹殺するなんて、大それたこと…",
  ui_story_5028_50281302_134_dialog_content = "シャドウマスターが止めなかったとしても、\n阻止しようとする者が必ず他に現われるさ。そこのお嬢さんのようにね。",
  ui_story_5028_50281302_135_dialog_content = "ゲイリー…",
  ui_story_5028_50281302_136_dialog_content = "俺にはなんで翼が片方しかないのか、知ってるか？",
  ui_story_5028_50281302_137_dialog_content = "知らんな。俺に何の関係がある？",
  ui_story_5028_50281302_138_dialog_content = "えっ？",
  ui_story_5028_50281302_139_option_content = "どうしてなんですか？",
  ui_story_5028_50281302_140_dialog_content = "私もだいぶ前から気になっていたけど、\nいつも他の話ではぐらかされてきたわ。",
  ui_story_5028_50281302_141_dialog_content = "俺は子どもの頃から珍獣たちが大好きで、\nいつもなんとか近づこうとしてたんだ。",
  ui_story_5028_50281302_142_dialog_content = "だが、その頃の俺は、珍獣たちの習性を知らなくてな。\nうっかり、ある珍獣を怒らせちまったんだよ。",
  ui_story_5028_50281302_143_dialog_content = "怒ったヤツに襲われて、片方の翼を裂かれちまった。\nそれでこうなったってワケだ。",
  ui_story_5028_50281302_144_dialog_content = "畜生どもにそんな目に遭わされて、\n怒りを感じなかったのか？",
  ui_story_5028_50281302_145_dialog_content = "その時は理解できなかったし、悔しかったさ。\nでも、その後友人に助けられて、珍獣を少しずつ理解できるようになった。",
  ui_story_5028_50281302_146_dialog_content = "珍獣たちからしたって、\n俺たち光霊は同じように、理解できない生き物なんだよ。",
  ui_story_5028_50281302_147_dialog_content = "あいつらは本能的に俺たちを疑い、恐れる。\n俺たちが近づけば、自分の身を守るために攻撃する。",
  ui_story_5028_50281302_148_dialog_content = "俺たちの珍獣たちに対する態度と、まったく同じなんだ。",
  ui_story_5028_50281302_149_dialog_content = "それに珍獣から見れば、光霊は自分たちを狩ったり、捕まえたりする。\n自分たちの家を侵す悪者だ。",
  ui_story_5028_50281302_150_dialog_content = "光霊と動物の心を通じ合わせる能力を持った、\nあの友人がいなかったら…",
  ui_story_5028_50281302_151_dialog_content = "珍獣たちが俺たちのことをそんな風に思ってるなんて、\n一生知ることもなかっただろうな。",
  ui_story_5028_50281302_152_dialog_content = "だから、俺は珍獣たちを理解して、\n許すことを選んだんだよ。",
  ui_story_5028_50281302_153_dialog_content = "だが、俺の場合は違う！",
  ui_story_5028_50281302_154_dialog_content = "お前が許すかどうかは、\nお前自身の一方的な感情の話だ。",
  ui_story_5028_50281302_155_dialog_content = "俺の家族は、命を奪われたんだぞ！？",
  ui_story_5028_50281302_156_dialog_content = "俺の知る限り…事件の後、\nあの森の中で、一人で狩りを始めたそうだな？",
  ui_story_5028_50281302_157_dialog_content = "その通りだ。あの森にいた畜生どもを\n全部あの世へ送ってやった。1匹残らずだ。",
  ui_story_5028_50281302_158_dialog_content = "そいつらを殺したなら、もう復讐は終わっただろ。\nなんで他の珍獣たちまで苦しめ続けた？",
  ui_story_5028_50281302_159_dialog_content = "苦しめるだけじゃ飽き足らずに、\n従わせて、光霊を攻撃させようとまでした。",
  ui_story_5028_50281302_160_dialog_content = "むろん、すべての者に、畜生と光霊は違う、\nやつらは恐ろしく、滅んで当然の存在だと知らしめるためだ。",
  ui_story_5028_50281302_161_dialog_content = "お前にとって、珍獣が――",
  ui_story_5028_50281302_162_dialog_content = "お前の親しい者を殺し、お前の幸せを奪い、\nお前の半生を台無しにした存在だっていうなら…",
  ui_story_5028_50281302_163_dialog_content = "むやみに殺戮を続けてるお前と、\nお前自身の嫌いな「畜生」と、何の違いがあるんだ？",
  ui_story_5028_50281302_164_dialog_content = "…！",
  ui_story_5028_50281302_165_dialog_content = "お前の一生はまだ長い。\nこれから生きているうちに、分かってくれることを願ってるよ。",
  ui_story_5028_50281302_166_dialog_content = "謎のタコ男君、\n俺からヤツに言うことはもうないよ。",
  ui_story_5028_50281302_167_dialog_content = "話は終わったのかい？",
  ui_story_5028_50281302_168_dialog_content = "では、僕からのお願いを聞いてもらえるかな。",
  ui_story_5028_50281302_169_dialog_content = "彼と手下たちの身柄は\nシャドウマスターに預けてもらいたい。",
  ui_story_5028_50281302_170_dialog_content = "影ノ街の安全を守り、罪を犯した者には相応の罰を与える。\nそれがシャドウマスターの決まりなんでね。",
  ui_story_5028_50281302_171_dialog_content = "お嬢さんの「牢に入れる」という意見は、\n僕からシャドウマスターに伝えておくよ。",
  ui_story_5028_50281302_172_dialog_content = "俺に異議はないよ。",
  ui_story_5028_50281302_173_dialog_content = "珍獣には興味がない人だが、\n罪人の扱いに関しては、詳しいだろうしな。お前たちは？",
  ui_story_5028_50281302_174_dialog_content = "こいつのために、わざわざ\n閉じ込める場所を作るなんて面倒だわ。",
  ui_story_5028_50281302_175_dialog_content = "シャドウマスターのところなら、\nきっと監獄もたくさんあるでしょ。",
  ui_story_5028_50281302_176_dialog_content = "異議はないわ。",
  ui_story_5028_50281302_177_dialog_content = "そいつが牢屋送りになるなら、\nあたしも異議なし！",
  ui_story_5028_50281302_178_option_content = "じゃあ…クレーケン、お願いするよ。",
  ui_story_5028_50281302_179_option_content = "感謝するよ。",
  ui_story_5028_50281302_180_dialog_content = "そちらの諸君には、密漁犯たちの\n影ノ街への護送のお手伝いを依頼できないかな？",
  ui_story_5028_50281302_181_dialog_content = "手伝い？いいよ。",
  ui_story_5028_50281302_182_dialog_content = "チッ、またつまんなそーな仕事か…",
  ui_story_5028_50281302_183_dialog_content = "ここにいても、私たちに手伝えることはなさそうね。\n残った動物たちの救助は、専門家に任せた方がいいでしょうし。",
  ui_story_5028_50281302_184_dialog_content = "うん！",
  ui_story_5028_50281302_185_dialog_content = "それじゃ、僕は帰って報告することにするよ。\nでは、またいずれ。",
  ui_story_5028_50281302_186_dialog_content = "あいつ、また別の面倒を起こさなければいいけど。",
  ui_story_5028_50281302_187_dialog_content = "ま、そりゃまた後で考えればいい話だ。",
  ui_story_5028_50281401_1_dialog_content = "とにかく、今回は一件落着！\nめでたし、めでたしってヤツだ。",
  ui_story_5028_50281401_2_dialog_content = "キャロって、本当に強かったんだね。",
  ui_story_5028_50281401_3_dialog_content = "「無敵」とか言ってたの、\n師匠の大ボラだと思ってた！",
  ui_story_5028_50281401_4_dialog_content = "俺はなあ、自分の弟子をだまそうとしたことなんてないんだよ。\nシーラもフィアも、俺にとっては一番大事な弟子なんだ。",
  ui_story_5028_50281401_5_dialog_content = "確かにだまそうとはしていないわね。",
  ui_story_5028_50281401_6_dialog_content = "ほら、お前の先輩も――",
  ui_story_5028_50281401_7_dialog_content = "あなたが信用されないのは、\nただ単に頼りにならないからよ。",
  ui_story_5028_50281401_8_dialog_content = "シーラ、仮にも師匠だろうが…\n俺、泣きそう。よよよ…",
  ui_story_5028_50281401_9_dialog_content = "でも、キャロってこんなに強かったのに、\n今まで危険な目に遭った時、なんで力を使えなかったんだろう？",
  ui_story_5028_50281401_10_dialog_content = "いや、それよりもっと不思議なのは…",
  ui_story_5028_50281401_11_dialog_content = "師匠って、そんなにすごい珍獣がいたのに、\nなんでずっと何もできないダメ人間のままなの？",
  ui_story_5028_50281401_12_dialog_content = "なるほど、すごく不思議だ…",
  ui_story_5028_50281401_13_dialog_content = "…",
  ui_story_5028_50281401_14_dialog_content = "はあ…それは私が説明してあげるわ。",
  ui_story_5028_50281401_15_dialog_content = "キャロは、とても特殊な生物なの。\n強大な力を持っているけど…",
  ui_story_5028_50281401_16_dialog_content = "その力は、お互いに信頼し合う生物と\n意思疎通ができて初めて、使うことができるのよ。",
  ui_story_5028_50281401_17_dialog_content = "ただ、キャロは数がとても少なくて、\nキャロたちの言葉に関する情報も徐々に失われていったの。",
  ui_story_5028_50281401_18_dialog_content = "おまけに変幻自在っていう特性のせいで、\n身動きによるコミュニケーションもそれぞれ違うから、理解が難しいの。",
  ui_story_5028_50281401_19_dialog_content = "それで、キャロと意思疎通ができる光霊はほとんどいない…",
  ui_story_5028_50281401_20_dialog_content = "それどころか、キャロ同士でも相手の鳴き声の意味が分からなくて、\n交流できないことがあるみたいね。",
  ui_story_5028_50281401_21_dialog_content = "そのせいで、キャロの幼体の外界での生存率は、\nものすごく低くなってしまったのよ。",
  ui_story_5028_50281401_22_dialog_content = "それで、キャロの棲息地っていうのは…\n実は全部、その人が育ててたのよ。",
  ui_story_5028_50281401_23_dialog_content = "師匠、そんなにすごかったんだ！？",
  ui_story_5028_50281401_24_dialog_content = "でも、キャロの考えてることが分からないなら、\n師匠はどうやってキャロの習性を知ったの？",
  ui_story_5028_50281401_25_dialog_content = "1つだけ、キャロの心を読める方法があるの、それが…",
  ui_story_5028_50281401_26_option_content = "僕…？",
  ui_story_5028_50281401_27_dialog_content = "正確に言うと、空の末裔の感知能力ね。",
  ui_story_5028_50281401_28_option_content = "空の末裔の…",
  ui_story_5028_50281401_29_dialog_content = "そうよ。",
  ui_story_5028_50281401_30_dialog_content = "空の末裔の感知能力があれば、言葉の壁を無視して、\nキャロの思考を直接感じることができる。",
  ui_story_5028_50281401_31_dialog_content = "それで考えや思いを理解して、鳴き声と突き合わせていけば、\n少しずつキャロたちの言うことが理解できるようになる…",
  ui_story_5028_50281401_32_dialog_content = "私にもようやく分かったわ。フィア、あなたの才能があれば、\nキャロたちの言葉はすぐに理解できる。",
  ui_story_5028_50281401_33_dialog_content = "だから、師匠が出した最初の試練が、\n「空の末裔を捕まえる」だったんだね？",
  ui_story_5028_50281401_34_dialog_content = "その通りよ。思いが通じることが、\nキャロの真の能力を引き出す重要なカギなの。",
  ui_story_5028_50281401_35_dialog_content = "でも、キャロが僕を感知させてくれるとは限らないよ？",
  ui_story_5028_50281401_36_dialog_content = "一緒に旅をしていたから、キャロはとっくに\nあなたを仲間だと思ってたんでしょうね。",
  ui_story_5028_50281401_37_dialog_content = "それに、ゲイリーのキャロが、\n能力を使えたのは…？",
  ui_story_5028_50281401_38_dialog_content = "それは分からないわ。",
  ui_story_5028_50281401_39_dialog_content = "推測だけど、あの鞭と関係があるでしょうね。",
  ui_story_5028_50281401_40_dialog_content = "あの鞭は、きっと恐怖を珍獣たちの心に刻んで、\n屈服させられるものなんでしょう。",
  ui_story_5028_50281401_41_dialog_content = "恐怖は信頼の正反対にあるもの…恐怖が極限に達していたから、\nあんな歪んだ姿になっていたのかもしれないわ。",
  ui_story_5028_50281401_42_dialog_content = "ふん、そんなんじゃ、\n分かりあえたとは言えないもんね！",
  ui_story_5028_50281401_43_dialog_content = "キャロと分かりあえる「珍獣マスター」のあたしに\nあいつが勝てなかった理由、きっとそれだよ！",
  ui_story_5028_50281401_44_dialog_content = "ヴィックさんって、ずっと前から\nそのことを分かってたの？",
  ui_story_5028_50281401_45_dialog_content = "ずっと前からってワケじゃないわ。",
  ui_story_5028_50281401_46_dialog_content = "師匠は昔、空の末裔の知り合いがいたの。",
  ui_story_5028_50281401_47_dialog_content = "その空の末裔の手助けのおかげで\nコミュニケーションができて、キャロの生態が判明したのよ。",
  ui_story_5028_50281401_48_dialog_content = "17年前の話ね。",
  ui_story_5028_50281401_49_dialog_content = "…ヴィックさん、永遠の18歳って…",
  ui_story_5028_50281401_50_dialog_content = "本当は一体いくつ…！？",
  ui_story_5028_50281401_51_dialog_content = "オッホン！！そこまでだ！\n今は昔話をしてる場合じゃあないぞ！",
  ui_story_5028_50281401_52_dialog_content = "俺たちにはまだ、\nここでやらなきゃいけないことがたくさんある。",
  ui_story_5028_50281401_53_dialog_content = "ルルル！",
  ui_story_5028_50281401_54_dialog_content = "どうしたの？この子の調子を見てくれって？",
  ui_story_5028_50281401_55_dialog_content = "ル…ル…",
  ui_story_5028_50281401_56_dialog_content = "これは…急に悪化してるわね。",
  ui_story_5028_50281401_57_dialog_content = "まずいな、長い間の恐怖とキズだ。\nもともと良くない状況だったんだ。",
  ui_story_5028_50281401_58_dialog_content = "その上に今回戦わされて、ひどいキズを負ったもんだから、\n身体がもう限界なんだ。",
  ui_story_5028_50281401_59_dialog_content = "誰か、治療できる光力術は…？",
  ui_story_5028_50281401_60_dialog_content = "…",
  ui_story_5028_50281401_61_dialog_content = "急ごう、影ノ街に行って助けを呼べば、\nまだ間に合う！",
  ui_story_5028_50281401_62_dialog_content = "ドラゴライオン、お願い、手伝って！",
  ui_story_5028_50281401_63_dialog_content = "間に合わんぞ！？",
  ui_story_5028_50281401_64_dialog_content = "ルルル！",
  ui_story_5028_50281401_65_dialog_content = "あれ？キャ、キャロ！？",
  ui_story_5028_50281401_66_dialog_content = "ルル！ルルル！",
  ui_story_5028_50281401_67_dialog_content = "この子たちは、私がさっき逃がした…",
  ui_story_5028_50281401_68_dialog_content = "みんな、戻ってきたの？",
  ui_story_5028_50281401_69_dialog_content = "ルルル！ルルル！",
  ui_story_5028_50281401_70_dialog_content = "話を聞けば、何か助けになるかも？",
  ui_story_5028_50281401_71_dialog_content = "いいよ、やってみる！",
  ui_story_5028_50281401_72_dialog_content = "キャロの同種のみんな、\nなんとかこの子を助けてあげて！",
  ui_story_5028_50281401_73_dialog_content = "お願い…",
  ui_story_5028_50281401_74_dialog_content = "この子を助けて…",
  ui_story_5028_50281401_75_dialog_content = "ルルル！",
  ui_story_5028_50281401_76_dialog_content = "ルルルル！",
  ui_story_5028_50281401_77_dialog_content = "この光は、さっきフィアのキャロが出した光と同じだ！",
  ui_story_5028_50281401_78_dialog_content = "お前たち、よく見とけよ…",
  ui_story_5028_50281401_79_dialog_content = "もしかしたら、本当に貴重な瞬間に\n立ち会えるかもしれないぞ。",
  ui_story_5028_50281401_80_dialog_content = "キャロたちが空の末裔の助けを借りて、\nフィアと心を通わせ、力を目覚めさせたんだ…",
  ui_story_5028_50281401_81_dialog_content = "ルルル…",
  ui_story_5028_50281401_82_dialog_content = "キャロたちの放った光が、\nケガをしたキャロを包み込んで…",
  ui_story_5028_50281401_83_dialog_content = "傷がどんどん回復してる！",
  ui_story_5028_50281401_83X_dialog_content = "これこそキャロの力だ。",
  ui_story_5028_50281401_84_dialog_content = "ほかの珍獣の能力だけじゃなく、\n光霊の能力もマネできるのさ。",
  ui_story_5028_50281401_85_dialog_content = "まさに「無敵」だろ？",
  ui_story_5028_50281401_86_dialog_content = "まさに「無敵」だろ？",
  ui_story_5028_50281401_87_dialog_content = "そういうことね…",
  ui_story_5028_50281401_88_option_content = "本当にすごい",
  ui_story_5028_50281401_89_dialog_content = "君もなかなかすごかったさ。",
  ui_story_5028_50281401_90_dialog_content = "えっ？",
  ui_story_5028_50281401_91_option_content = "うらやましい",
  ui_story_5028_50281401_92_dialog_content = "僕にもこんなに強い力があったら、\n絶対に友だちを守れるのに…",
  ui_story_5028_50281401_93_dialog_content = "君だって、すごく強大な力をもってるだろ。\nみんなの心をつなぐ、感知能力ってもんをさ。",
  ui_story_5028_50281401_94_dialog_content = "戦いには使えないかもしれんが、\nその力を生かせば、皆がお互いを理解できるようになる。",
  ui_story_5028_50281401_95_dialog_content = "誤解を解いて、恨みをなくし、\n戦いが起こること自体を、阻止することもできるだろう。",
  ui_story_5028_50281401_96_dialog_content = "そうでしょうか…？",
  ui_story_5028_50281401_97_dialog_content = "…分かりました！",
  ui_story_5028_50281401_98_dialog_content = "見て。あのキャロ、元気を取り戻したみたいよ。",
  ui_story_5028_50281401_99_dialog_content = "ル…ル？",
  ui_story_5028_50281401_100_dialog_content = "もう大丈夫！",
  ui_story_5028_50281401_101_dialog_content = "皆が協力して、治してくれたんだよ！",
  ui_story_5028_50281401_102_dialog_content = "ルル、ル――",
  ui_story_5028_50281401_103_dialog_content = "うんうん、もちろん、\n「珍獣マスター」のあたしにも感謝してよ！",
  ui_story_5028_50281401_104_dialog_content = "ルルル！",
  ui_story_5028_50281401_105_dialog_content = "ひゃあ！アハハ、くすぐったい！",
  ui_story_5028_50281401_106_dialog_content = "ずっとここに居るのもよくないな。\nそろそろ、こいつらを元いた場所に戻してやらないと。",
  ui_story_5028_50281401_107_dialog_content = "え？キャロたち、帰っちゃうの？",
  ui_story_5028_50281401_108_dialog_content = "ルルル！",
  ui_story_5028_50281401_109_dialog_content = "キャロ、あなたも行っちゃうの…？",
  ui_story_5028_50281401_110_dialog_content = "一緒にいてよ…",
  ui_story_5028_50281401_111_dialog_content = "ル…",
  ui_story_5028_50281401_112_dialog_content = "ルゥ！",
  ui_story_5028_50281401_113_dialog_content = "だ、ダメ？でも、でも…",
  ui_story_5028_50281401_114_dialog_content = "はぁ…まだまだ子供ね。",
  ui_story_5028_50281401_115_dialog_content = "珍獣自身の習性と欲求を尊重することは、\n私たちが研究者として持っているべき品格よ。",
  ui_story_5028_50281401_116_dialog_content = "自分の考えを珍獣に\n押し付けようとしてはいけないわ。",
  ui_story_5028_50281401_117_dialog_content = "子供じゃないもん！",
  ui_story_5028_50281401_118_dialog_content = "ルルル！",
  ui_story_5028_50281401_119_dialog_content = "これは…",
  ui_story_5028_50281401_120_dialog_content = "アリガタモドキドリの力だ！\nこれも使えるんだね…ぐぅ…",
  ui_story_5028_50281401_121_dialog_content = "ルル！",
  ui_story_5028_50281401_122_dialog_content = "なんとまぁ、こんなにアッサリ別れるとはな。",
  ui_story_5028_50281401_123_dialog_content = "寝てる間に相棒とお別れなんて、\n起きたらきっと、大泣きして騒ぐでしょうね。",
  ui_story_5028_50281401_124_dialog_content = "泣く子をなだめるなんて、面倒そうだわ。",
  ui_story_5028_50281401_125_dialog_content = "師匠はもっと面倒が苦手なもんでね。\nその件は、一番弟子に任せるとしよう。",
  ui_story_5028_50281401_126_dialog_content = "はぁ…",
  ui_story_5028_50281401_127_dialog_content = "みんなと仲良く暮らせよ！",
  ui_story_5028_50281401_128_dialog_content = "危険そうなやつには近づかないようにしなさい。",
  ui_story_5028_50281401_129_dialog_content = "ルルル！",
  ui_story_5028_50281401_130_dialog_content = "この話はこれでおしまい…",
  ui_story_5028_50281401_131_dialog_content = "キャロと仲間たちは、\n今でも森の中で幸せに暮らしてる。",
  ui_story_5028_50281401_132_dialog_content = "フィアという女の子も成長して、\n立派な「珍獣マスター」になったんだ。",
  ui_story_5028_50281401_133_dialog_content = "めでたし、めでたし。",
  ui_story_5028_50281401_134_dialog_content = "それで？その後はどうなったの？",
  ui_story_5028_50281401_135_dialog_content = "バイス、まずはちょっと休憩させてくれない？",
  ui_story_5028_50281401_136_dialog_content = "もう丸々3時間、『珍獣探して大冒険』の話をし続けてるんだ…",
  ui_story_5028_50281401_137_dialog_content = "のどがガラガラだよ！",
  ui_story_5028_50281401_138_dialog_content = "あっ、ごめんごめん。\nじゃ、一休みしましょ。",
  ui_story_5028_50281401_139_dialog_content = "思わず聞き入っちゃったわね。\nまだちょっとドキドキしてる。",
  ui_story_5028_50281401_140_dialog_content = "その後が気になって仕方ないわ。",
  ui_story_5028_50281401_141_dialog_content = "この本の作者に直接聞けばいいよ。\nきっと――",
  ui_story_5028_50281401_142_dialog_content = "PlayerName！！！",
  ui_story_5028_50281401_143_dialog_content = "…ほら、ウワサをすればなんとやらだ…",
  ui_story_5028_50281401_144_dialog_content = "海で珍獣を探したいの！",
  ui_story_5028_50281401_145_dialog_content = "あたしの珍獣として、\n拒否は許さないから！",
  ui_story_5028_50281401_146_dialog_content = "分かった分かった、分かったけど…\n何度言ったら分かってくれるのかな。僕は珍獣じゃないって。",
  ui_story_5028_50281401_147_dialog_content = "今さら否定する気？\n残念でした！もう遅いよーだ！！",
  ui_story_5028_50281401_148_dialog_content = "ご主人サマとして、\nあんたが勝手に逃げたら許さないから！",
  ui_story_5028_50281401_149_dialog_content = "どうしてもソラヴァンに乗りたいって\n言いだしたのは君の方でしょ！？",
  ui_story_5028_50281401_150_dialog_content = "おまけに、ドラゴライオンがまだついて来てるし！！",
  ui_story_5028_50281401_151_dialog_content = "早く、何とかして帰ってもらってよ！",
  ui_story_5028_50281401_152_dialog_content = "ソラヴァンに求愛しても無意味だって！！",
  ui_story_5028_50281401_153_dialog_content = "言ったでしょ？繁殖期を過ぎれば、\nそのうち勝手に帰るよ。",
  ui_story_5028_50281401_154_dialog_content = "珍獣自身の習性と欲求を尊重するのが、\nあたしたちが研究者として備えるべき品格だもん。",
  ui_story_5028_50281401_155_dialog_content = "だから、あたしは無理に帰らせたりしないの！",
  ui_story_5028_50281401_156_dialog_content = "こういう時だけ、うまいことを…",
  ui_story_5028_50281401_157_dialog_content = "あの後キャロが帰って来なかったら、\nきっと何時間も泣いてたくせに！",
  ui_story_5028_50281401_158_dialog_content = "な、なんのこと？",
  ui_story_5028_50281401_159_dialog_content = "お、覚えがないな～？",
  ui_story_5028_50281401_160_dialog_content = "言い訳してもムダだよ、素直に認めなよ。",
  ui_story_5028_50281401_161_dialog_content = "もう、うるさーい！",
  ui_story_5028_50281401_162_dialog_content = "キャロ、咬んじゃえ！！",
  ui_story_5028_50281401_163_dialog_content = "ル…ルルル！",
  ui_story_5028_50281401_164_dialog_content = "うわあ！？",
  ui_story_5028_50281401_165_dialog_content = "足が！！！",
  ui_story_5028_50281401_166_dialog_content = "プッ…フフフ…",
  ui_story_5028_50281401_167_dialog_content = "PlayerName…子供を叱るにしたって、\nもう少し遠回しに言わないと。",
  ui_story_5028_50281401_168_dialog_content = "バイス、早く助けて！",
  ui_story_5028_50281401_169_dialog_content = "早くキャロを追い払って！",
  ui_story_5028_50281401_170_dialog_content = "はいはい…お願い、PlayerNameを放してあげて？",
  ui_story_5028_50281401_171_dialog_content = "ルルル！！",
  ui_story_5028_50281401_172_dialog_content = "ふふん、珍獣マスターのすごさを思い知った？",
  ui_story_5028_50281401_173_dialog_content = "足にキャロの咬みあとが…",
  ui_story_5028_50281401_174_dialog_content = "キャロとはお別れしたって聞いてたけど、\nまだ側にいるみたいね？",
  ui_story_5028_50281401_175_dialog_content = "あたしが魅力的すぎるから、\nやっぱり離れたくないんだって！",
  ui_story_5028_50281401_176_dialog_content = "ルルルル！",
  ui_story_5028_50281401_177_dialog_content = "あら？何か言いたそうね。",
  ui_story_5028_50281401_178_dialog_content = "そう？よく聞こえなかったよ。\nキャロ、なんて言ったの？もう1回言ってもらえる？",
  ui_story_5028_50281401_179_dialog_content = "ルルル…",
  ui_story_5028_50281401_180_dialog_content = "「フィアのことが心配だったから…？」",
  ui_story_5028_50281401_181_dialog_content = "「きっと、長いこと泣くだろうなと思ったら…」",
  ui_story_5028_50281401_182_dialog_content = "「心配で仕方なくなって、それで結局、戻ってきた…？」",
  ui_story_5028_50281401_183_dialog_content = "そういうことね。",
  ui_story_5028_50281401_184_dialog_content = "ルルル！ルル！",
  ui_story_5028_50281401_185_dialog_content = "キャ、キャロ！？",
  ui_story_5028_50281401_186_dialog_content = "それ以上言わないで！！！",
  ui_story_5028_50281401_187_dialog_content = "この物語はここでおしまい。",
  ui_story_5028_50281401_188_dialog_content = "だが、珍獣マスターの冒険は、永遠に続く…"
}
